\begin{defn}[Disjoint Union; \citealp{lee2010introduction}]\label{defn:disjoint-union}\index{disjoint union}
    Let $(X_\alpha)_{\alpha \in A}$ be a family of sets over a non-empty set $A$. The set
    \begin{align*}
        \bigsqcup_{\alpha \in A} X_\alpha = \bigcup_{\alpha \in A} X_\alpha \times \{\alpha\} = \bigcup_{\alpha \in A} \{(x,\alpha) \mid x \in X_\alpha \}
    \end{align*}
    is called the disjoint union of $(X_\alpha)_{\alpha \in A}$. 
\end{defn}

