\begin{prop}\label{prop:disjoint-isomorphism}
    Let $(X_\alpha)_{\alpha \in A}$ be a family of sets such that
    \begin{align*}
        X_\alpha \cap X_{\alpha^\prime} = \emptyset,
    \end{align*}
    for all $\alpha, \alpha^\prime \in A: \alpha \neq \alpha^\prime$. Then 
    \begin{align*}
        \bigcup_{\alpha \in A} X_\alpha \cong \bigsqcup_{\alpha \in A} X_\alpha.
    \end{align*}
\end{prop}

environments.statement:
\label{prop:disjoint-isomorphism}
    Let $(X_\alpha)_{\alpha \in A}$ be a family of sets such that
    \begin{align*}
        X_\alpha \cap X_{\alpha^\prime} = \emptyset,
    \end{align*}
    for all $\alpha, \alpha^\prime \in A: \alpha \neq \alpha^\prime$. Then 
    \begin{align*}
        \bigcup_{\alpha \in A} X_\alpha \cong \bigsqcup_{\alpha \in A} X_\alpha.
    \end{align*}

proof.rawEnvironment:
\begin{proof}
    Notice that by definition 
    \begin{align*}
        (x,\alpha) \in X_{\alpha} \times \{\alpha\} \implies (x,\alpha) \in \Bigl(\bigcup_{\alpha^\prime \in A} X_{\alpha^\prime}\Bigr) \times A,
    \end{align*}
    since $x \in X_\alpha \subseteq \bigcup_{\alpha^\prime \in A}X_{\alpha^\prime}$ and $\alpha \in A$. Therefore, the above shows that in general 
    \begin{align*}
        \bigsqcup_{\alpha \in A} X_\alpha = \bigcup_{\alpha \in A} X_\alpha \times \{\alpha\} \subseteq \Bigl(\bigcup_{\alpha \in A} X_\alpha\Bigr) \times A.
    \end{align*}
    If $X_\alpha = X_{\alpha^\prime}$ for all $\alpha,\alpha^\prime \in A$, then
    \begin{align*}
        \Bigl(\bigcup_{\alpha \in A} X_\alpha\Bigr) \times A
        &= \bigcup_{\alpha \in A} \bigcup_{\alpha^\prime \in A} X_\alpha \times \{\alpha^\prime\}\\
        &= \bigcup_{\alpha^\prime \in A} X_{\alpha^\prime} \times \{\alpha^\prime\}
        = \bigsqcup_{\alpha^\prime \in A} X_{\alpha^\prime},
    \end{align*}
    proving the reverse inclusion and hence equality.

    Conversely, assume that
    \begin{align*}
        \bigsqcup_{\alpha \in A} X_\alpha = \Bigl(\bigcup_{\alpha \in A} X_\alpha\Bigr) \times A.
    \end{align*}
    Fix $\alpha,\alpha^\prime \in A$ and let $x \in X_\alpha$. Then $(x,\alpha^\prime)$ belongs to the right-hand side and therefore, by the assumed equality, also to the left-hand side. Hence $(x,\alpha^\prime) \in X_{\alpha^\prime} \times \{\alpha^\prime\}$, which implies $x \in X_{\alpha^\prime}$. Thus $X_\alpha \subseteq X_{\alpha^\prime}$. By symmetry, $X_{\alpha^\prime} \subseteq X_\alpha$, and therefore $X_\alpha = X_{\alpha^\prime}$. 
\end{proof}

