\begin{prop}\label{prop:disjoint-product}
    Let $(X_\alpha)_{\alpha \in A}$ be a family of sets. Then 
    \begin{align*}
        \bigsqcup_{\alpha \in A} X_\alpha \subseteq\Bigl(\bigcup_{\alpha \in A} X_\alpha\Bigr) \times A.
    \end{align*}
    Moreover,
    \begin{align*}
        \bigsqcup_{\alpha \in A} X_\alpha = \Bigl(\bigcup_{\alpha \in A} X_\alpha\Bigr) \times A \iff \forall \alpha, \alpha^\prime \in A: X_\alpha = X_{\alpha^\prime} .
    \end{align*}
\end{prop}

