\begin{proof}
    We must show that for all $(x,\alpha),(x^\prime,\alpha^\prime),(x^\ast,\alpha^\ast)\in X$ we have 
    \begin{enumerate}
        \item $(x,\alpha) \preceq (x, \alpha)$. \label{eq:disjoint-partial-order-1}
        \item $(x,\alpha) \preceq (x^\prime, \alpha^\prime)$ and $(x^\prime,\alpha^\prime) \preceq (x, \alpha)$ implies $(x,\alpha) = (x^\prime, \alpha^\prime)$. \label{eq:disjoint-partial-order-2}
        \item $(x,\alpha) \preceq (x^\prime, \alpha^\prime)$ and $(x^\prime, \alpha^\prime) \preceq (x^\ast, \alpha^\ast)$ implies $(x,\alpha)\preceq (x^\ast, \alpha^\ast)$. \label{eq:disjoint-partial-order-3}
    \end{enumerate}
    These properties follow from the corresponding axioms on each component: 
    \begin{enumerate}[-]
        \item For \eqref{eq:disjoint-partial-order-1} note that $(x,\alpha) \preceq (x, \alpha) \iff (\alpha = \alpha) \land x \preceq_\alpha x$, which holds by reflexivity of $\preceq_\alpha$.
        \item Likewise, for \eqref{eq:disjoint-partial-order-2}, note that  $((x,\alpha) \preceq (x^\prime, \alpha^\prime)) \land ((x^\prime,\alpha^\prime) \preceq (x, \alpha))$ holds if and only if  $(\alpha^\prime =\alpha) \land (x \preceq_\alpha x^\prime) \land (x^\prime \preceq_\alpha x)$. However, as $\preceq_\alpha$ is a partial order, this is equivalent to $(\alpha = \alpha^\prime) \land (x = x^\prime)$. 
        \item Finally, for $\eqref{eq:disjoint-partial-order-3}$, note that $(x,\alpha) \preceq (x^\prime, \alpha^\prime)$ and $(x^\prime, \alpha^\prime)\preceq (x^\ast, \alpha^\ast)$ imply that $\alpha = \alpha^\prime$ and $\alpha^\prime= \alpha^\ast$. But then $\alpha = \alpha^\prime = \alpha^\ast$. Hence, by the transitivity of $\preceq_\alpha$, it holds that $x \preceq_\alpha x^\prime$ and  $x^\prime \preceq_\alpha x^\ast$ implies $x \preceq_\alpha x^\ast$. However, then clearly, $(\alpha = \alpha^\ast) \land (x \preceq_{\alpha} x^\ast)$ as desired. 
    \end{enumerate}
\end{proof}

