\begin{prop}[Disjoint Union Partial Ordering]\label{prop:disjoint-partial-order}\index{partial order}
    Let $(X_\alpha, \preceq_\alpha)_{\alpha \in A}$ be a family of partially ordered sets. Let $X = \sqcup_{\alpha \in A} X_\alpha$ and define the relation $\preceq$ on $X$ by
    \begin{align*}
        (x,\alpha) \preceq (x^\prime, \alpha^\prime) \iff (\alpha = \alpha^\prime) \land x \preceq_\alpha x^\prime.
    \end{align*}
    Then $(X,\preceq)$ is a partially ordered set. 
\end{prop}

environments.statement:
\label{prop:disjoint-partial-order}\index{partial order}
    Let $(X_\alpha, \preceq_\alpha)_{\alpha \in A}$ be a family of partially ordered sets. Let $X = \sqcup_{\alpha \in A} X_\alpha$ and define the relation $\preceq$ on $X$ by
    \begin{align*}
        (x,\alpha) \preceq (x^\prime, \alpha^\prime) \iff (\alpha = \alpha^\prime) \land x \preceq_\alpha x^\prime.
    \end{align*}
    Then $(X,\preceq)$ is a partially ordered set.

environments.rawEnvironment:
\begin{exmp}[Partial Order on a Static Market]\label{exmp:partial-order-static-market}
    Let us consider the setting of Example~\ref{exmp:adm-static}. Now, define 
    \begin{align*}
        (p,q) \preceq_{\mathrm{buy}} (p^\prime, q^\prime) \iff (p > p^\prime) \lor ((p = p^\prime) \land (q \geq q^\prime)), 
    \end{align*}
    which states that a buy order is ``better'' if the price per unit is greater, or if the prices are equal and more volume is provided. Similarly, 
    \begin{align*}
        (p,q) \preceq_{\mathrm{sell}} (p^\prime, q^\prime) \iff (p < p^\prime) \lor ((p = p^\prime) \land (q \geq q^\prime)), 
    \end{align*}
    that is, a sell order is ``better'' if the price per unit is smaller or the price per unit is equal but more volume is provided. The orderings rank orders by priority, and in both cases the order on the left-hand side has priority over the one on the right-hand side. The resulting ordering on the disjoint union allows us to compare orders of the same type, but buy and sell orders are, once again, incomparable.
\end{exmp}

environments.statement:
\label{exmp:partial-order-static-market}
    Let us consider the setting of Example~\ref{exmp:adm-static}. Now, define 
    \begin{align*}
        (p,q) \preceq_{\mathrm{buy}} (p^\prime, q^\prime) \iff (p > p^\prime) \lor ((p = p^\prime) \land (q \geq q^\prime)), 
    \end{align*}
    which states that a buy order is ``better'' if the price per unit is greater, or if the prices are equal and more volume is provided. Similarly, 
    \begin{align*}
        (p,q) \preceq_{\mathrm{sell}} (p^\prime, q^\prime) \iff (p < p^\prime) \lor ((p = p^\prime) \land (q \geq q^\prime)), 
    \end{align*}
    that is, a sell order is ``better'' if the price per unit is smaller or the price per unit is equal but more volume is provided. The orderings rank orders by priority, and in both cases the order on the left-hand side has priority over the one on the right-hand side. The resulting ordering on the disjoint union allows us to compare orders of the same type, but buy and sell orders are, once again, incomparable.

proof.rawEnvironment:
\begin{proof}
    We must show for all $(x,\alpha),(x^\prime,\alpha^\prime), (x^\ast, \alpha^\ast)$ that 
    \begin{enumerate}
        \item $(x,\alpha) \preceq (x,\alpha)$. \label{property:disjoint-total-order-1}
        \item $(x,\alpha) \preceq (x^\prime,\alpha^\prime)$ and $(x^\prime, \alpha^\prime) \preceq (x^\ast, \alpha^\ast)$ implies $(x,\alpha) \preceq (x^\ast, \alpha^\ast)$. \label{property:disjoint-total-order-2}
        \item $(x,\alpha) \preceq (x^\prime ,\alpha^\prime )$ and $(x^\prime ,\alpha^\prime ) \preceq (x,\alpha)$ implies $(x,\alpha) =(x^\prime,\alpha^\prime)$. \label{property:disjoint-total-order-3}
        \item $(x,\alpha) \preceq (x^\prime, \alpha^\prime)$ or $(x^\prime, \alpha^\prime) \preceq (x,\alpha)$. \label{property:disjoint-total-order-4}
    \end{enumerate}
    Note that \eqref{property:disjoint-total-order-1} is $(x,\alpha) \preceq (x,\alpha)$ if and only if $(\alpha < \alpha) \lor ((\alpha =\alpha) \land (x \preceq_\alpha x))$ which holds if and only if $x \preceq_\alpha x$. However, since each $\preceq_\alpha$ is a total order the property follows. 

    For transitivity, suppose $(x,\alpha) \preceq (x^\prime,\alpha^\prime)$ and $(x^\prime,\alpha^\prime) \preceq (x^\ast,\alpha^\ast)$. If either $\alpha<\alpha^\prime$ or $\alpha^\prime<\alpha^\ast$, then transitivity of the total order on $A$ gives $\alpha\leq\alpha^\ast$; moreover, $\alpha \neq \alpha^\ast$, since $\alpha = \alpha^\ast$ would give $\alpha \leq \alpha^\prime \leq \alpha$ with one inequality strict, contradicting antisymmetry. Hence $\alpha<\alpha^\ast$. In the remaining case $\alpha=\alpha^\prime=\alpha^\ast$, transitivity of $\preceq_\alpha$ gives $x\preceq_\alpha x^\ast$. Thus $(x,\alpha)\preceq (x^\ast,\alpha^\ast)$. For antisymmetry, if both $(x,\alpha)\preceq (x^\prime,\alpha^\prime)$ and $(x^\prime,\alpha^\prime)\preceq (x,\alpha)$ hold, then total-order antisymmetry on $A$ forces $\alpha=\alpha^\prime$, and antisymmetry of $\preceq_\alpha$ then forces $x=x^\prime$. Hence $(x,\alpha)=(x^\prime,\alpha^\prime)$. 

    Finally, we must show that $(x,\alpha) \preceq (x^\prime, \alpha^\prime)$ or $(x^\prime, \alpha^\prime) \preceq (x,\alpha)$. To do so, notice that 
    \begin{align*}
        &((x,\alpha) \preceq (x^\prime, \alpha^\prime) )\lor ((x^\prime, \alpha^\prime) \preceq (x,\alpha))\iff\\ &(\alpha < \alpha^\prime) \lor (\alpha^\prime < \alpha) \lor ((\alpha = \alpha^\prime) \land ((x \preceq_\alpha x^\prime) \lor (x^\prime \preceq_\alpha x))),
    \end{align*}
    and the three mutually exclusive cases are $\alpha < \alpha^\prime$, $\alpha^\prime < \alpha$, and $\alpha = \alpha^\prime$. Since $\leq$ is total on $A$, exactly one of them holds, and in the third case the disjunction holds because $\preceq_\alpha$ is total. For the antisymmetric relation $\preceq$, this connexity property is equivalent to the totality condition~(iv) of Definition~\ref{defn:ordered-sets}.
\end{proof}

