\begin{thm}[Szpilrajn Extension Theorem; \citealp{szpilrajn1930extension}]\label{thm:szpilrajn}\index{Szpilrajn extension theorem}
    Let $(X, \preceq)$ be a partially ordered set. Then, there exists a total order, $\leq$, on $X$ such that
    \begin{align*}
        \forall x,x^\prime\in X : x \preceq x^\prime \implies x \leq x^\prime.
    \end{align*}
\end{thm}

environments.statement:
\label{thm:szpilrajn}\index{Szpilrajn extension theorem}
