\begin{exmp}[Total Order for a Static Market]\label{exmp:total-order-static-market}
    We continue from Examples~\ref{exmp:adm-static} and \ref{exmp:partial-order-static-market} in which we considered the orders as elements of the set 
    \begin{align*}
        O = \bigsqcup_{\kappa \in \{\mathrm{buy},~\mathrm{sell}\}} \mathbb{R}\times [0,\infty),  
    \end{align*}
    where we endowed the buy and sell orders with the two orders $\preceq_{\mathrm{buy}}$ and $\preceq_{\mathrm{sell}}$ of Example~\ref{exmp:partial-order-static-market}.
    Endow $\{\mathrm{buy}, ~\mathrm{sell}\}$ with the (arbitrarily chosen) total order $\leq$ in which buy precedes sell, given by
    \begin{align*}
        \kappa \leq \kappa^\prime \iff \kappa = \kappa^\prime \lor (\kappa = \mathrm{buy} \land \kappa^\prime = \mathrm{sell}).
    \end{align*}
    Since $\leq, \preceq_{\mathrm{buy}}$, and  $\preceq_{\mathrm{sell}}$ are all total orders, we have that the lexicographic order defined by
    \begin{align*}
        (o, \kappa) \preceq (o^\prime, \kappa^\prime) \iff \kappa < \kappa^\prime \lor (\kappa = \kappa^\prime \land o \preceq_\kappa o^\prime), 
    \end{align*}
    is total, where $<$ is the strict part of $\leq$, $(o,\kappa) =((p,q),\kappa)\in O$ and $(o^\prime, \kappa^\prime)=((p^\prime,q^\prime),\kappa^\prime) \in O$. 
\end{exmp}

