\begin{prop}\label{prop:disjoint-union-metric-properties}
    Let $(X_\alpha, d_\alpha)_{\alpha \in A}$ be a family of metric spaces over an index set $A$. Let $(X,d)$ be the corresponding disjoint union metric space. Then:
    \begin{enumerate}[(i)]
        \item if $A$ is countable and $(X_\alpha, d_\alpha)_{\alpha \in A}$ are all separable metric spaces, then $(X,d)$ is separable;\label{property:disjoint-metric-1}
        \item if $(X_\alpha, d_\alpha)_{\alpha \in A}$ are all complete metric spaces, then $(X,d)$ is complete.\label{property:disjoint-metric-2}
    \end{enumerate}
\end{prop}

environments.statement:
\label{prop:disjoint-union-metric-properties}
    Let $(X_\alpha, d_\alpha)_{\alpha \in A}$ be a family of metric spaces over an index set $A$. Let $(X,d)$ be the corresponding disjoint union metric space. Then:
    \begin{enumerate}[(i)]
        \item if $A$ is countable and $(X_\alpha, d_\alpha)_{\alpha \in A}$ are all separable metric spaces, then $(X,d)$ is separable;\label{property:disjoint-metric-1}
        \item if $(X_\alpha, d_\alpha)_{\alpha \in A}$ are all complete metric spaces, then $(X,d)$ is complete.\label{property:disjoint-metric-2}
    \end{enumerate}

proof.rawEnvironment:
\begin{proof}
    First, suppose that $f$ is continuous. Fix $\alpha \in A$, $x_0\in X_\alpha$, and $\varepsilon>0$. Since $f$ is continuous at $(x_0,\alpha)$, there exists $\delta>0$ such that
    \begin{align*}
        d((x,\alpha),(x_0,\alpha))<\delta \implies d^\ast(f(x,\alpha),f(x_0,\alpha))<\varepsilon.
    \end{align*}
    For $x\in X_\alpha$,
    \begin{align*}
        d((x,\alpha),(x_0,\alpha))=d_\alpha(x,x_0),
    \end{align*}
    so $f\restriction_{X_\alpha}$ is continuous.

    Conversely, suppose that each restriction $f\restriction_{X_\alpha}$ is continuous. Fix $(x_0,\alpha_0)\in X$ and $\varepsilon>0$. By continuity of $f\restriction_{X_{\alpha_0}}$ at $x_0$, choose $\delta_0>0$ such that
    \begin{align*}
        d_{\alpha_0}(x,x_0)<\delta_0
        \implies
        d^\ast(f(x,\alpha_0),f(x_0,\alpha_0))<\varepsilon.
    \end{align*}
    Set $\delta=\min\left(\delta_0,\frac{1}{2}\right)$. If $d((x,\alpha),(x_0,\alpha_0))<\delta$, then $\alpha=\alpha_0$ by the definition of the disjoint-union metric, and hence the preceding implication applies, so $d^\ast(f(x,\alpha),f(x_0,\alpha_0))<\varepsilon$. Thus $f$ is continuous at $(x_0,\alpha_0)$.
\end{proof}

