\begin{thm}[Pasting Lemma for Disjoint Unions; \citealp{lee2010introduction}]\label{thm:pasting-lemma}\index{pasting lemma}\index{continuous functions!pasting lemma}
    Let $(X_\alpha, d_\alpha)_{\alpha \in A}$ be a family of metric spaces and $(Y,d^\ast)$ be a metric space. Moreover, let $(X,d)$ be the disjoint union metric space and let $f:X \to Y$ be a function. Then, $f$ is continuous if and only if the maps 
    \begin{align*}
        f\restriction_{X_\alpha}&: X_\alpha \to Y\\
        x &\mapsto f(x,\alpha)        
    \end{align*} 
    are continuous for each $\alpha \in A$. 
\end{thm}

environments.statement:
\label{thm:pasting-lemma}\index{pasting lemma}\index{continuous functions!pasting lemma}
    Let $(X_\alpha, d_\alpha)_{\alpha \in A}$ be a family of metric spaces and $(Y,d^\ast)$ be a metric space. Moreover, let $(X,d)$ be the disjoint union metric space and let $f:X \to Y$ be a function. Then, $f$ is continuous if and only if the maps 
    \begin{align*}
        f\restriction_{X_\alpha}&: X_\alpha \to Y\\
        x &\mapsto f(x,\alpha)        
    \end{align*} 
    are continuous for each $\alpha \in A$.

proof.rawEnvironment:
\begin{proof}
    Recall the canonical injection
    \begin{align*}
        \iota_\alpha : X_\alpha \to X,\qquad x \mapsto (x,\alpha).
    \end{align*}
    By construction, $\iota_\alpha$ is an isometry from $(X_\alpha,d_\alpha)$ onto the subset $X_\alpha \times \{\alpha\} \subseteq X$. Moreover, each set $X_\alpha \times \{\alpha\}$ is both open and closed in $X$. It is open because every point $(x,\alpha)$ has a ball of radius, say, $1/2$ contained in $X_\alpha \times \{\alpha\}$, and it is closed because its complement is the union of the other open components.

    If $f$ is measurable, then for every $B \in \Sigma$ and every $\alpha \in A$,
    \begin{align*}
        (f\restriction_{X_\alpha})^{-1}(B)
        = \iota_\alpha^{-1}(f^{-1}(B)) \in \mathcal{B}(X_\alpha),
    \end{align*}
    since $\iota_\alpha$ is continuous.

    Conversely, assume that each $f\restriction_{X_\alpha}$ is measurable. We use that the Borel $\sigma$-algebra of a subspace $Y \subseteq X$ is the trace $\{B \cap Y \mid B \in \mathcal{B}(X)\}$, so that $\iota_\alpha$ maps Borel sets of $X_\alpha$ to Borel sets of the Borel subspace $X_\alpha\times\{\alpha\}$, and hence of $X$. Let $B \in \Sigma$. Then
    \begin{align*}
        f^{-1}(B)
        &= \left\{(x,\alpha) \in \bigsqcup_{\alpha\in A}X_\alpha ~\middle|~ f(x,\alpha) \in B \right\}\\
        &= \bigcup_{\alpha \in A} \iota_\alpha\big((f\restriction_{X_\alpha})^{-1}(B)\big).
    \end{align*}
    Each set $(f\restriction_{X_\alpha})^{-1}(B)$ belongs to $\mathcal{B}(X_\alpha)$ by assumption, and $\iota_\alpha$ is a homeomorphism onto the Borel set $X_\alpha \times \{\alpha\}$. Hence each image
    \begin{align*}
        \iota_\alpha\big((f\restriction_{X_\alpha})^{-1}(B)\big)
    \end{align*}
    is Borel in $X$. Since the family is countable, the union is Borel as well. Therefore, $f^{-1}(B) \in \mathcal{B}(X)$ for every $B \in \Sigma$, proving that $f$ is measurable. 
\end{proof}

