\begin{rem}
For countable $A$, the measurable space $(X,\mathcal{B}(X))$ is the \emph{direct sum of measurable spaces} $(X_\alpha,\mathcal{B}(X_\alpha))$, and a more general statement can be found in \citet{fremlin2000measure}.
 \end{rem}

\begin{defn}[Set of Finite Subsets]\label{defn:finite-subsets}\index{finite subsets}
    Let $X$ be a set. Then the set of finite subsets of $X$ is denoted by 
    \begin{align*}
        \mathscr{F}(X) = \{\xi \subseteq X \mid |\xi| < \infty\},
    \end{align*}
    where $|\cdot|$ denotes the cardinality. 
\end{defn}

environments.statement:
\label{defn:finite-subsets}\index{finite subsets}
    Let $X$ be a set. Then the set of finite subsets of $X$ is denoted by 
    \begin{align*}
        \mathscr{F}(X) = \{\xi \subseteq X \mid |\xi| < \infty\},
    \end{align*}
    where $|\cdot|$ denotes the cardinality.

environments.rawEnvironment:
\begin{prop}\label{prop:injection-into-finite-sets}
  Let $\mathscr{F}(X)$ be the set of finite subsets of a set $X$. Then, the mapping from $X$ to $\mathscr{F}(X)$ defined by $x \mapsto \{x\}$ is injective. 
\end{prop}

\begin{prop}\label{prop:finite-sets-over-finite-set}
    Let $X$ be a finite set. Then $\mathscr{F}(X) = \wp(X)$, where $\wp(X)$ denotes the power set of $X$.
\end{prop}

\begin{prop}[Finite Subsets of a Countable Set Form a Countable Set; \citealp{smullyan1996set}]\label{prop:countable-finite-sets}
    Let $X$ be countable. Then $\mathscr{F}(X)$ is countable. 
\end{prop}

\begin{defn}[Hausdorff Distance; \citealp{hausdorff1914grundzuege}]\label{defn:Hausdorff-distance}
    Let $(X, d)$ be a metric space. The function $d_H :\wp(X) \times \wp(X) \to [0,\infty]$ defined by 
    \begin{align*}
        d_H(\xi, \eta) = \max\left(\adjustlimits\sup_{x \in \xi}\inf_{x^\prime \in \eta}d(x,x^\prime), \adjustlimits\sup_{x^\prime\in \eta} \inf_{x \in \xi}d(x,x^\prime) \right),
    \end{align*}
    is called the Hausdorff distance induced by $d$, or simply the Hausdorff distance if the inducing metric is clear from context.
\end{defn}

