\begin{prop}\label{prop:finite-set-cauchy}
    Let $(X,d)$ be a metric space. Then, if $(x_n)_{n\in\mathbb{N}} \subseteq X$ is a Cauchy sequence, the sequence $(\xi_n)_{n\in\mathbb{N}} \subseteq \mathscr{F}(X)$ defined by
    \begin{align*}
        \xi_{n} = \bigcup_{i = 1}^n \{x_i\} 
    \end{align*}
    is a Cauchy sequence in $(\mathscr{F}(X), d_H)$.
\end{prop}

