\begin{defn}[{Uniformly Discrete; \citealp[cf.][Definition~1.1]{lagarias1996meyer}}]\label{defn:uniformly-discrete}\index{uniformly discrete spaces}
    Let $(X,d)$ be a metric space. We call $(X,d)$ \emph{uniformly discrete} if there exists a $\beta > 0$ such that
    \begin{align*}
        \forall x, x^\prime \in X: x \neq x^\prime \implies d(x,x^\prime) \geq \beta.
    \end{align*}
\end{defn}

