\begin{prop}\label{prop:uniformly-discrete-complete}
    Let $(X,d)$ be a uniformly discrete metric space. Then, any Cauchy sequence $(x_n)_{n\in\mathbb{N}} \subseteq X$ is eventually constant. In particular, $(X,d)$ is complete.
\end{prop}

proof.rawEnvironment:
\begin{proof}
    Let $\beta > 0$ be the separation bound for $(X,d)$. Let $\xi, \eta \in \mathscr{F}(X)$ with $\xi \neq \eta$. If either $\xi$ or $\eta$ is empty, then Remark~\ref{rem:hausdorff-convention} gives
    \begin{align*}
        d_H(\xi,\eta)=\infty \geq \beta,
    \end{align*}
    so the claim is immediate. Therefore, it remains to consider the case where both $\xi$ and $\eta$ are non-empty. Since $\xi \neq \eta$, without loss of generality there exists an $x_0 \in \xi \setminus \eta$. In particular, since $x_0 \notin \eta$, it holds that
    \begin{align*}
        \min_{x^\prime \in \eta} d(x_0,x^\prime) \geq \beta,
    \end{align*}
    and so
    \begin{align*}  
        d_H(\xi, \eta) &= \max\left(\max_{x \in \xi}\min_{x^\prime \in \eta} d(x,x^\prime), \max_{x^\prime \in \eta} \min_{x\in \xi} d(x,x^\prime) \right) \\&\geq \max_{x \in \xi}\min_{x^\prime \in \eta} d(x,x^\prime) \geq \beta,
    \end{align*}
    as desired.
\end{proof}

