\begin{prop}\label{prop:finite-hausdorff-uniformly-discrete}
    Let $(X,d)$ be a uniformly discrete metric space. Then, $(\mathscr{F}(X), d_H)$ is uniformly discrete, with the same bound.
\end{prop}

\begin{prop}\label{prop:finite-hausdorff-uniformly-discrete-iff}
    Let $(X,d)$ be a metric space. Then, $(\mathscr{F}(X), d_H)$ is uniformly discrete if and only if $(X,d)$ is uniformly discrete. 
\end{prop}

\begin{defn}[Labelled Finite Sets]\label{defn:labelled-finite-sets}\index{labelled finite sets}
    Let $X$ be a set. We call the set
    \begin{align*}
        \mathscr{L}(X) = \{\xi \in \mathscr{F}(\mathbb{N} \times X) \mid \forall n \in \mathbb{N}: |(\{n\} \times X) \cap \xi| \leq 1\},
    \end{align*}
    the set of labelled finite sets over $X$. 
\end{defn}

environments.statement:
\label{defn:labelled-finite-sets}\index{labelled finite sets}
    Let $X$ be a set. We call the set
    \begin{align*}
        \mathscr{L}(X) = \{\xi \in \mathscr{F}(\mathbb{N} \times X) \mid \forall n \in \mathbb{N}: |(\{n\} \times X) \cap \xi| \leq 1\},
    \end{align*}
    the set of labelled finite sets over $X$.

proof.rawEnvironment:
\begin{proof}[Proof of Theorem~\ref{thm:labelled-properties}]
    For \eqref{property:labelled-finite-separable}, note that if $(X,d)$ is separable, then $(\mathbb{N} \times X, d^\ast)$ is separable, as it is a product of two separable spaces. By Proposition~\ref{prop:finite-separable}, $(\mathscr{F}(\mathbb{N}\times X), d_H^\ast)$ is separable; since $\mathscr{L}(X) \subseteq \mathscr{F}(\mathbb{N}\times X)$, the subspace $\mathscr{L}(X)$ is also separable, because every subspace of a separable metric space is separable.

    Now let $(\xi_k)_{k\in\mathbb{N}} \subseteq \mathscr{L}(X)$ be a Cauchy sequence. We must show that there exists an element $\xi \in \mathscr{L}(X)$ such that $\lim_{k\to\infty} d_H^\ast(\xi_k, \xi) = 0$. We proceed constructively; first, let $N \in \mathbb{N}$ be such that $d_H^\ast(\xi_k,\xi_m) < 1$ for all $k,m\geq N$, which exists because the sequence is Cauchy. Now, define
    \begin{align*}
        \Pi:\mathscr{L}(X)&\to \mathscr{F}(\mathbb{N}) \\
        \xi &\mapsto \{n \in \mathbb{N} \mid \exists x \in X : (n,x) \in \xi\}.
    \end{align*}
    By Lemma~\ref{lem:helpful-labelled}, there is a finite set $I \subseteq \mathbb{N}$ such that 
    \begin{align*}
        k \geq N \implies \Pi(\xi_k) = I.
    \end{align*}
    Note that if $I$ is empty, then the claim is verified, as this immediately implies, by Lemma~\ref{lem:helpful-labelled}, that $k \geq N \implies\xi_k = \emptyset$. Therefore, we assume without loss of generality that $I \neq \emptyset$. For each $i \in I$, define 
    \begin{align*}
        x_k(i) = x,
    \end{align*}
    where $x \in X$ is the unique element such that $(i,x) \in \xi_k$. Notice that since the sequence $(\xi_k)_{k\in\mathbb{N}}$ is Cauchy, for every $\varepsilon>0$ we may choose $N_\varepsilon\geq N$ such that $d_H^\ast(\xi_k,\xi_m)<\min(\varepsilon,1)$ for $k,m\geq N_\varepsilon$. Lemma~\ref{lem:helpful-labelled}, applied with $r=\min(\varepsilon,1)$, then gives, since each label occurs at most once in $\xi_m$,
    \begin{align*}
        d(x_k(i),x_m(i))<\varepsilon,\qquad i\in I,\ k,m\geq N_\varepsilon.
    \end{align*}
    Thus $(x_k(i))_{k = N}^\infty$ is a Cauchy sequence for each $i \in I$. Since $X$ is assumed complete, each sequence $(x_k(i))_{k = N}^\infty$ has a limit, say $x(i) \in X$. We claim that 
    \begin{align*}
        \xi = \{(i,x(i)) \mid i \in I\}
    \end{align*}
    is the limit of the Cauchy sequence. For $k \geq N$ one has 
    \begin{align*}
        d_H^\ast(\xi_k, \xi) \leq \max_{i \in I} d(x_k(i), x(i)),
    \end{align*}
    since the same indexed point in $\xi$ is an admissible Hausdorff match for the corresponding indexed point in $\xi_k$, and conversely. The right-hand side corresponds to the maximum metric on a finite product of $X$. Therefore, one has that 
    \begin{align}
        \lim_{k\to\infty} d_H^\ast(\xi_k, \xi) = 0,
    \end{align}
    since $x_k(i) \to x(i)$ for each of the finitely many $i \in I$, which proves the claim.
\end{proof}

proof.text:
For \eqref{property:labelled-finite-separable}, note that if $(X,d)$ is separable, then $(\mathbb{N} \times X, d^\ast)$ is separable, as it is a product of two separable spaces. By Proposition~\ref{prop:finite-separable}, $(\mathscr{F}(\mathbb{N}\times X), d_H^\ast)$ is separable; since $\mathscr{L}(X) \subseteq \mathscr{F}(\mathbb{N}\times X)$, the subspace $\mathscr{L}(X)$ is also separable, because every subspace of a separable metric space is separable.

