\begin{thm}\label{thm:labelled-properties}
    Let $(X,d)$ be a metric space and endow $\mathbb{N}$ with the Euclidean distance. On $\mathbb{N}\times X$, define $d^\ast:(\mathbb{N}\times X) \times (\mathbb{N}\times X) \to [0, \infty]$ by 
    \begin{align*}
        d^\ast((n,x),(n^\prime, x^\prime)) = d(x,x^\prime) + |n-n^\prime|.
    \end{align*}
    Let $\mathscr{L}(X) \subseteq \mathscr{F}(\mathbb{N}\times X)$ be endowed with the Hausdorff distance $d_H^\ast : \mathscr{L}(X) \times \mathscr{L}(X) \to [0,\infty]$ induced by $d^\ast$; since $d^\ast$ is a metric on $\mathbb{N}\times X$, Theorem~\ref{thm:Hausdorff-finite-sets} makes $d_H^\ast$ a metric on $\mathscr{L}(X)$. It holds that
    \begin{enumerate}[(i)]
        \item if $(X,d)$ is separable, then so is $(\mathscr{L}(X), d_H^\ast)$.\label{property:labelled-finite-separable}
        \item if $(X,d)$ is complete, then so is $(\mathscr{L}(X), d_H^\ast)$.\label{property:labelled-finite-complete}
    \end{enumerate}
\end{thm}

