\begin{defn}[Tuple Space \citep{zinn2023mathematical}]\label{defn:tuple}\index{tuple space}
    Let $X$ be a non-empty set. The set 
    \begin{align}\label{defn:tuple-space}
        \mathscr{T}(X) = \bigcup_{n\in\mathbb{N}_0} X^n,
    \end{align}
    where $X^0$ is the singleton containing the empty function, is called the space of tuples over $X$, and the elements $\bm{x} \in \mathscr{T}(X)$ are called either $X$-tuples or simply tuples. 
\end{defn}

environments.statement:
