\begin{rem}
    We denote the \emph{empty} tuple by $\bm{e}:\emptyset \to X$. Strictly speaking, one has that $\bm{e} = \emptyset$ within the $\mathbf{\mathtt{ZFC}}$ axioms, because any function is specified by its graph and the graph of $\bm{e}$ is a subset of $\emptyset \times X = \emptyset$. However, it is convenient to think of it as an empty map, which is why it is presented as such. 
\end{rem}

\begin{defn}[Length of a Tuple]\label{defn:tuple-length}\index{tuple length}
    Let $X$ be a non-empty set and $\mathscr{T}(X)$ the space of tuples over $X$. Then, the mapping $\ell:\mathscr{T}(X)  \to \mathbb{N}_0$ defined by 
    \begin{align}
        \ell(\bm{x}) = |\mathrm{domain}(\bm{x})|, 
    \end{align}
    where $|\cdot|$ denotes the cardinality, is called the length map, and $\ell(\bm{x})$ is called the length of $\bm{x}$. 
\end{defn}

