\begin{prop}\label{prop:totally-ordered-tuple-sorted-iff-monotone}
    Let $(X,\preceq)$ be a totally ordered set. Then any tuple $\bm{x} \in \mathscr{T}(X)$ is sorted with respect to $\preceq$ if and only if 
    \begin{align*}
        \forall i,j \in \mathrm{domain}(\bm{x}): i \leq j \implies \bm{x}(i) \preceq \bm{x}(j). 
    \end{align*}
\end{prop}

