\begin{defn}[Finite Permutations]\label{defn:finite-permutations}\index{finite permutations}
    For any $n \in \mathbb{N}_0$, we call the set 
    \begin{align*}
        \mathscr{P}_n = \{\pi:\{1, \dots, n\}\to \{1,\dots, n\} \mid  \pi \text{ is bijective}\}
    \end{align*}
    the $n$-permutations, with the case $\mathscr{P}_0$ being a singleton containing the empty function. Moreover, we call 
    \begin{align*}
        \mathscr{P} = \bigcup_{n\in\mathbb{N}_0} \mathscr{P}_n,
    \end{align*}
    the set of finite permutations.
\end{defn}

