\begin{defn}[Sorting Permutations]\label{defn:sorting-permutations}\index{sorting permutations}
    Let $(X,\preceq)$ be a partially ordered set. Then, for any $\bm{x} \in \mathscr{T}(X)$, we call the set 
    \begin{align*}
        \mathscr{P}_{\bm{x}} = \{\pi:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x}) \mid \pi\text{ is bijective and } \bm{x} \circ \pi \in \mathscr{S}(X,\preceq)\}
    \end{align*}
    the sorting permutations for $\bm{x}$. 
\end{defn}

environments.statement:
\label{defn:sorting-permutations}\index{sorting permutations}
    Let $(X,\preceq)$ be a partially ordered set. Then, for any $\bm{x} \in \mathscr{T}(X)$, we call the set 
    \begin{align*}
        \mathscr{P}_{\bm{x}} = \{\pi:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x}) \mid \pi\text{ is bijective and } \bm{x} \circ \pi \in \mathscr{S}(X,\preceq)\}
    \end{align*}
    the sorting permutations for $\bm{x}$.

proof.rawEnvironment:
\begin{proof}
    Let $\bm{x}\in\mathscr{T}(X)$ be given. If $\ell(\bm{x})=0$, then the unique map $\emptyset\to\emptyset$ is a sorting permutation. Hence assume $\ell(\bm{x})>0$.
    First, since $(X,\preceq)$ is a partially ordered set, $(\mathrm{image}(\bm{x}), \preceq)$ is partially ordered. By Theorem~\ref{thm:szpilrajn}, this order extends to a total order, $\preceq^\ast$, on $\mathrm{image}(\bm{x})$. Since this order is total, define recursively
    \begin{align*}
        \pi_1 &= \min\{ j \in \mathrm{domain}(\bm{x}) \mid \bm{x}(j) = \min_{\preceq^\ast} \mathrm{image}(\bm{x})\} \\ I_1 &= \mathrm{domain}(\bm{x}) \setminus\{\pi_1\}
    \end{align*}
    and for $2 \leq k \leq \ell(\bm{x})$
    \begin{align*}
        \pi_k &= \min \{j \in I_{k-1} \mid \bm{x}(j) = \min_{\preceq^\ast} \{\bm{x}(m) \mid m \in I_{k-1}\}\}\\
        I_k&=\mathrm{domain}(\bm{x})\setminus \{\pi_1, \dots, \pi_k\}
    \end{align*}
    where $\min_{\preceq^\ast}$ refers to the extended order on $\mathrm{image}(\bm{x})$, while the outer minima over indices are taken in the usual order on $\mathbb{N}$. We then define $\pi:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x})$ by
    \begin{align*}
        \pi(i) = \pi_i.
    \end{align*}
    The recursive construction chooses each index exactly once, so $\pi$ is a bijection of $\mathrm{domain}(\bm{x})$. Moreover, by construction, $\bm{x} \circ \pi$ is non-decreasing for the linear extension $\preceq^\ast$. If $i\leq j$ and $\bm{x}(\pi(j))\prec \bm{x}(\pi(i))$ in the original partial order, then also $\bm{x}(\pi(j))\prec^\ast \bm{x}(\pi(i))$, contradicting the $\preceq^\ast$-ordering. Hence $\bm{x} \circ \pi \in \mathscr{S}(X,\preceq)$ and $\pi \in \mathscr{P}_{\bm{x}}$.
\end{proof}

