\begin{thm}\label{thm:permutation-exists}
    Let $(X,\preceq)$ be a partially ordered set. Then, for any tuple in $\mathscr{T}(X)$ there exists a sorting permutation. 
\end{thm}

\begin{defn}[Sorting Map \citep{zinn2023mathematical}]\label{defn:sorting-map}\index{sorting map}
    For a partially ordered set $(X,\preceq)$ let $\mathscr{T}(X)$ and $\mathscr{S}(X,\preceq)$ be the sets of tuples and of sorted tuples, respectively. Any function $\varsigma:\mathscr{T}(X)\to \mathscr{S}(X,\preceq)$ such that, for every $\bm{x} \in \mathscr{T}(X)$, there exists a bijective map $\pi:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x})$ such that
    \begin{align}\label{eq:sort-permute}
        \varsigma(\bm{x}) = \bm{x} \circ \pi
    \end{align}
    is called a sorting map. 
\end{defn}

environments.statement:
\label{defn:sorting-map}\index{sorting map}
    For a partially ordered set $(X,\preceq)$ let $\mathscr{T}(X)$ and $\mathscr{S}(X,\preceq)$ be the sets of tuples and of sorted tuples, respectively. Any function $\varsigma:\mathscr{T}(X)\to \mathscr{S}(X,\preceq)$ such that, for every $\bm{x} \in \mathscr{T}(X)$, there exists a bijective map $\pi:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x})$ such that
    \begin{align}\label{eq:sort-permute}
        \varsigma(\bm{x}) = \bm{x} \circ \pi
    \end{align}
    is called a sorting map.

proof.rawEnvironment:
\begin{proof}
    Note that by Theorem~\ref{thm:permutation-exists}, for any $\bm{x} \in \mathscr{T}(X)$ the set $\mathscr{P}_{\bm{x}} \neq \emptyset$. Therefore, by the \hyperref[axiom:choice]{axiom of choice} there exists a choice function
    \begin{align*}
        \mathfrak{p}:\mathscr{T}(X) \to \mathscr{P}
    \end{align*}
    such that 
    \begin{align*}
        \mathfrak{p}_{\bm{x}} \equiv \mathfrak{p}(\bm{x}) \in \mathscr{P}_{\bm{x}}.
    \end{align*}
    Equivalently, $\mathfrak{p}$ chooses one element from each set in the family $(\mathscr{P}_{\bm{x}})_{\bm{x}\in\mathscr{T}(X)}$ of non-empty subsets of $\mathscr{P}$. Consequently, we may define the function $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ by 
    \begin{align*}
        \varsigma(\bm{x}) = i \mapsto \bm{x}(\mathfrak{p}_{\bm{x}}(i)).
    \end{align*}
\end{proof}

