\begin{cor}[Uniqueness, Idempotency and Permutation Invariance]\label{cor:unique-sorting-map-total-order}
    Let $(X,\preceq)$ be a totally ordered set. Then, there exists a unique sorting map $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$. Moreover, $\varsigma$ fixes every sorted tuple, so that $\varsigma\circ\varsigma=\varsigma$, and $\varsigma(\bm{x}\circ\rho)=\varsigma(\bm{x})$ for every $\bm{x}\in\mathscr{T}(X)$ and every bijection $\rho:\mathrm{domain}(\bm{x})\to\mathrm{domain}(\bm{x})$.
\end{cor}

\begin{rem}\label{rem:sorting-permutations-not-unique}
    The proof verifies that the sorting map is unique. However, there may still be multiple permutations that sort the tuple in the event that there are repeated elements. For instance, if $\bm{x} = (x,x)$ for some $x \in X$, then any permutation of the two entries will sort the tuple, as they are identical. Nevertheless, the resulting sorted tuple is unique, as it is the same regardless of the permutation applied.
\end{rem}

\begin{prop}\label{prop:graph-injects}
    Let $X$ be a set, $\mathscr{T}(X)$ be the associated tuple space, and $\mathscr{L}(X)$ denote the set of labelled finite sets over $X$. Then $\Gamma: \mathscr{T}(X) \to \mathscr{L}(X)$ is injective.
\end{prop}

proof.rawEnvironment:
\begin{proof}[Proof of Theorem~\ref{thm:tuple-space-metrisation}]
    This follows from the fact that $\Gamma:\mathscr{T}(X) \to \mathscr{L}(X)$ is injective, and $\mathscr{L}(X)$ is a metric space (Theorem~\ref{thm:Hausdorff-finite-sets} applied to $(\mathbb{N}\times X, d^\ast)$) when endowed with the Hausdorff distance induced by the metric $d^\ast:(\mathbb{N}\times X)\times(\mathbb{N}\times X) \to [0,\infty]$ defined by $d^\ast((n,x), (m,x^\prime)) = |n-m| + d(x,x^\prime)$.
\end{proof}

