\begin{thm}[Tuple Space Properties]\label{thm:tuple-space-properties}\index{tuple space!metrisation}
    Let $(X,d)$ be a metric space. Then, for every $\bm{x}, \bm{x}^\prime \in \mathscr{T}(X)$ it holds that
    \begin{enumerate}[(i)]
        \item $\mathscr{d}_H(\bm{x}, \bm{x}^\prime) < 1$ implies $\ell(\bm{x}) = \ell(\bm{x}^\prime)$. \label{eq:tuple-length}
        \item $\mathscr{d}_H(\bm{x}, \bm{x}^\prime) < 1$ and $\ell(\bm{x}) > 0$ implies $\mathscr{d}_H(\bm{x},\bm{x}^\prime) = \max_{i\in\{1,\dots, \ell(\bm{x})\}} d(\bm{x}(i), \bm{x}^\prime(i))$; without the restriction $\mathscr{d}_H(\bm{x},\bm{x}^\prime) < 1$, $\ell(\bm{x}) = \ell(\bm{x}^\prime) > 0$ implies $\mathscr{d}_H(\bm{x},\bm{x}^\prime) \leq \max_{i\in\{1,\dots, \ell(\bm{x})\}} d(\bm{x}(i), \bm{x}^\prime(i))$. \label{eq:tuple-collapse}
    \end{enumerate}
    Moreover:
    \begin{enumerate}[(i)]
        \setcounter{enumi}{2}
        \item if $(X,d)$ is a complete metric space, then $(\mathscr{T}(X),\mathscr{d}_H)$ is a complete metric space; \label{eq:tuple-complete}
        \item if $(X,d)$ is a separable metric space, then $(\mathscr{T}(X),\mathscr{d}_H)$ is a separable metric space;\label{eq:tuple-separable}
        \item if $(X,d)$ is a separable metric space and $\preceq$ is any partial order on $X$, then $(\mathscr{S}(X, \preceq),\mathscr{d}_H)$ is a separable metric subspace of $(\mathscr{T}(X),\mathscr{d}_H)$. \label{eq:sorted-tuple-separable}
    \end{enumerate}
\end{thm}

