\begin{cor}\label{cor:tuple-metrisation}
    Let $(X,d)$ be a metric space, and let $\mathscr{T}(X)$ be the associated tuple space. Define the mapping $\mathscr{d}_\infty : \mathscr{T}(X) \times \mathscr{T}(X) \to [0,\infty]$ by 
    \begin{align*}
        \mathscr{d}_\infty(\bm{x},\bm{x}^\prime) = \begin{cases}
            0 & \ell(\bm{x}) = \ell(\bm{x}^\prime) = 0\\
            \max_{i \in \{1,\dots, \ell(\bm{x})\}} d(\bm{x}(i), \bm{x}^\prime(i)) & \ell(\bm{x}) = \ell(\bm{x}^\prime) > 0\\
            \infty & \ell(\bm{x})\neq\ell(\bm{x}^\prime). 
        \end{cases}
    \end{align*}
    Then $(\mathscr{T}(X), \mathscr{d}_\infty)$ is a metric space. Moreover, if $(X,d)$ is separable, then $(\mathscr{T}(X), \mathscr{d}_\infty)$ is separable. Similarly, if $(X,d)$ is complete, then $(\mathscr{T}(X), \mathscr{d}_\infty)$ is complete. 
\end{cor}

