\begin{prop}\label{prop:truncated-metric-equivalent-topology}\index{truncated metric}
    Let $(X,d)$ be a metric space and let $\bar{d}:X\times X \to [0,1]$ be the metric defined by 
    \begin{align*}
        \bar{d}(x,x^\prime)=\min(d(x,x^\prime), 1).
    \end{align*}
    Then $(X,d)$ and $(X,\bar{d})$ are topologically equivalent.
\end{prop}

