\begin{defn}[Index Connectivity Generator]\label{defn:index-comparable}
Let $(X,\preceq)$ be a partially ordered set and let $\bm{x}\in\mathscr{T}(X)$. We define the relation $\overset{\bm{x}}{\leftrightsquigarrow}$ on $\mathrm{domain}(\bm{x})$ by
\begin{align*}
    i \overset{\bm{x}}{\leftrightsquigarrow} j
\iff (\bm{x}(i)\preceq \bm{x}(j))\ \lor\ (\bm{x}(j)\preceq \bm{x}(i)).
\end{align*}
\end{defn}

