\begin{defn}[Reflexive Transitive Closure]\label{defn:reflexive-transitive-closure}
    Let $X$ be a set and let $R \subseteq X \times X$ be a relation on $X$. Then, the reflexive transitive closure of $R$ is the relation $\overline{R} \subseteq X \times X$ defined by
    \begin{align*}
        \overline{R} = \Delta_X \cup \bigcup_{n\in\mathbb{N}} R^n,
    \end{align*}
    where $R^1 = R$ and $R^{n+1} = R^n \circ R$ for $n \in \mathbb{N}$, and $\Delta_X = \{(x,x) \mid x \in X\}$ is the diagonal relation on $X$.
\end{defn}

