\begin{defn}[Component Arrival Index]\label{defn:tau}
Let $(X,\preceq)$ be a partially ordered set and let $\bm{x}\in\mathscr{T}(X)$. Define the arrival-index map $\operatorname{arr}_{\bm{x}}:\mathcal{K}(\bm{x})\to\mathbb{N}$ by
\begin{align*}
\operatorname{arr}_{\bm{x}}(K) = \min\{i\in\mathbb{N} \mid (i,\bm{x}(i))\in K\}.
\end{align*}
\end{defn}

environments.statement:
\label{defn:tau}
Let $(X,\preceq)$ be a partially ordered set and let $\bm{x}\in\mathscr{T}(X)$. Define the arrival-index map $\operatorname{arr}_{\bm{x}}:\mathcal{K}(\bm{x})\to\mathbb{N}$ by
\begin{align*}
\operatorname{arr}_{\bm{x}}(K) = \min\{i\in\mathbb{N} \mid (i,\bm{x}(i))\in K\}.
\end{align*}

proof.rawEnvironment:
\begin{proof}
    We must show that $\operatorname{arr}_{\bm{x}}(K) = \operatorname{arr}_{\bm{x}}(K^\prime)$ implies $K = K^\prime$. Suppose $\operatorname{arr}_{\bm{x}}(K) = \operatorname{arr}_{\bm{x}}(K^\prime)$ for some $K, K^\prime \in \mathcal{K}(\bm{x})$. Then, by definition of $\operatorname{arr}_{\bm{x}}$, there exists an index $i = \operatorname{arr}_{\bm{x}}(K) = \operatorname{arr}_{\bm{x}}(K^\prime)$ such that $(i,\bm{x}(i))\in K$ and $(i,\bm{x}(i))\in K^\prime$. However, by Proposition~\ref{prop:components-partition-incomp}, the components form a partition of the graph of $\bm{x}$, which means that $K$ and $K^\prime$ cannot have any elements in common unless they are the same component. Therefore, we must have $K = K^\prime$, as desired.
\end{proof}

