\begin{prop}[Injectivity of Arrival Index]\label{prop:tau-injective}
Let $(X,\preceq)$ be a partially ordered set and let $\bm{x}\in\mathscr{T}(X)$. Then the map $\operatorname{arr}_{\bm{x}}:\mathcal{K}(\bm{x})\to\mathbb{N}$ is injective.
\end{prop}

\begin{cor}\label{cor:components-totally-ordered-by-arrival-index}
    Let $(X, \preceq)$ be a partially ordered set and let $\bm{x} \in \mathscr{T}(X)$ be a tuple. Then, the set of comparability components $\mathcal{K}(\bm{x})$ is totally ordered by the relation 
    \begin{align*}
    K \leq K^\prime \iff \operatorname{arr}_{\bm{x}}(K) \leq \operatorname{arr}_{\bm{x}}(K^\prime).
    \end{align*}
\end{cor}

