\begin{defn}[Permutation Map]\label{defn:permutation-map}\index{permutation maps}
    Let $X$ be a set, $\mathscr{T}(X)$ the associated tuple space, and $\mathscr{P}$ the set of all finite permutations. Define the map from $\mathscr{T}(X)\times \mathscr{P}$ into $\mathscr{T}(X)$ by 
    \begin{align*}
        \bm{x}[\pi] = \begin{cases}
            \bm{x} \circ \pi & \ell(\bm{x}) = \ell(\pi)\\
            \bm{e} & \ell(\bm{x}) \neq \ell(\pi).
        \end{cases}
    \end{align*}
    We call $(\bm{x}, \pi) \mapsto \bm{x}[\pi]$ the permutation map. 
\end{defn}

