\begin{prop}\label{prop:permuting-continuous}
    Let $(X, d)$ be a metric space and let $(\mathscr{T}(X), \mathscr{d}_H)$ be the associated tuple Hausdorff space. Moreover, let $\mathscr{P} \subseteq \mathscr{T}(\mathbb{N})$ be endowed with the tuple Hausdorff distance induced by the Euclidean distance on $\mathbb{N}$, which we denote by $\mathscr{d}_H^{\mathbb{N}}$. Then, the permutation map 
    \begin{align*}
        (\bm{x}, \pi) \mapsto \bm{x}[\pi]
    \end{align*}
    is continuous when $\mathscr{T}(X) \times \mathscr{P}$ is endowed with the product topology.
\end{prop}

