\begin{prop}\label{prop:induced-sorting}
 Let $(X, \preceq)$ be a partially ordered set, and let $\varphi:\mathscr{P} \to \mathbb{N}$ be a bijection. Then, the function $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ defined by 
 \begin{align*}
     \varsigma(\bm{x}) = \begin{cases}
         \varsigma_{\pi_{(1)}}(\bm{x}) & \bm{x} \in \mathscr{U}_1 \\
         ~~~~\vdots ~~~~ &~~~~\vdots \\ 
         \varsigma_{\pi_{(n)}}(\bm{x}) & \bm{x} \in \mathscr{U}_n \\ 
         ~~~~\vdots ~~~~ &~~~~\vdots \\ 
     \end{cases}
 \end{align*}
    is a sorting map, where $\pi_{(n)} = \varphi^{-1}(n)$, $\varsigma_{\pi_{(i)}} : \mathscr{U}_i \to \mathscr{S}(X, \preceq)$ are defined by $\varsigma_{\pi_{(i)}}(\bm{x}) = \bm{x}[\pi_{(i)}]$, and $\mathscr{U}_i = \mathscr{V}_{\pi_{(i)}} \setminus \bigcup_{j < i} \mathscr{V}_{\pi_{(j)}}$.
\end{prop}

