         ~~~~\vdots ~~~~ &~~~~\vdots \\ 
     \end{cases}
 \end{align*}
    is a sorting map, where $\pi_{(n)} = \varphi^{-1}(n)$, $\varsigma_{\pi_{(i)}} : \mathscr{U}_i \to \mathscr{S}(X, \preceq)$ are defined by $\varsigma_{\pi_{(i)}}(\bm{x}) = \bm{x}[\pi_{(i)}]$, and $\mathscr{U}_i = \mathscr{V}_{\pi_{(i)}} \setminus \bigcup_{j < i} \mathscr{V}_{\pi_{(j)}}$.

environments.rawEnvironment:
\begin{rem}
    Note that the measurability results below require only that the order relation belong to the Borel $\sigma$-algebra $\mathcal{B}(X\times X)$ of the product topology, and therefore require neither completeness nor separability of $X$. Separability becomes important when measurable maps into $X\times X$ are constructed componentwise from maps into each coordinate. For instance, if $\xi$ and $\eta$ are $X$-valued random elements on a measurable space $(\Omega, \mathcal{F})$, then the paired map $\omega \mapsto (\xi(\omega), \eta(\omega))$ is $(\mathcal{F}, \mathcal{B}(X)\otimes\mathcal{B}(X))$-measurable; consequently, the comparison set $\{\omega \in \Omega \mid \xi(\omega) \preceq \eta(\omega)\}$ is guaranteed to be an event in $\mathcal{F}$ whenever $\mathcal{B}(X\times X)=\mathcal{B}(X)\otimes\mathcal{B}(X)$, which holds when $X$ is separable, whereas without separability even the diagonal $\Delta_X$ may fail to lie in $\mathcal{B}(X)\otimes\mathcal{B}(X)$.
\end{rem}

proof.rawEnvironment:
\begin{proof}
    Note that by construction we have 
    \begin{align*}
        \bigcup_{n \in \mathbb{N}} \mathscr{U}_n = \bigcup_{\pi \in \mathscr{P}} \mathscr{V}_\pi = \mathscr{T}(X),
    \end{align*}
    and $\mathscr{U}_n \cap \mathscr{U}_m = \emptyset$ for all $n,m\in \mathbb{N}: n \neq m$. Therefore, it suffices to show that each $\mathscr{U}_n$ is measurable. To this end, note that it is enough to show that each $\mathscr{V}_\pi$ for $\pi \in \mathscr{P}$ is measurable, since the union over $m<n$ in the definition of $\mathscr{U}_n$ is finite. 

    Notice that, by definition, we have 
    \begin{align*}
        \mathscr{V}_\pi = \{\bm{x} \in \mathscr{T}(X) \mid \ell(\bm{x}) = \ell(\pi) \text{ and } \bm{x} \circ \pi \in \mathscr{S}(X, \preceq)\} \subseteq X^{\ell(\pi)}.
    \end{align*}
    Let $N = \ell(\pi)$ and note that by the \hyperref[thm:the-standard-machinery]{standard machinery}, it suffices to show that $\mathscr{V}_\pi$ is measurable in $X^N$ endowed with the maximum product metric and the associated Borel $\sigma$-algebra. Since $X$ is metric, the diagonal is closed, and hence the strict order relation $\prec=\preceq\setminus\Delta_X$ is Borel whenever $\preceq$ is Borel. Thus the set
    \begin{align*}
        A_{i,j} =\{\bm{x}:\{1,\dots,N\} \to X \mid \bm{x}(\pi(j)) \prec \bm{x}(\pi(i))\}
    \end{align*}
    is Borel, for each $i,j \in \{1,\dots,N\}$, being the preimage of the Borel set $\prec\, \subseteq X \times X$ under the continuous coordinate map $\bm{x} \mapsto (\bm{x}(\pi(j)),\bm{x}(\pi(i)))$ from $X^N$ to $X\times X$. Consequently, the complement, $A_{i,j}^{\mathtt{C}}$, is measurable, and
    \begin{align*}
        \mathscr{V}_{\pi} &= \{ \bm{x} \in \mathscr{T}(X) \mid N=\ell(\bm{x}) \text{ and } \bm{x}\circ\pi \in \mathscr{S}(X,\preceq)\} \\
        &= \{\bm{x} \in X^{N} \mid \forall i,j \in \{1,\dots, N\}: i \leq j \implies \neg(\bm{x}(\pi(j)) \prec \bm{x}(\pi(i)))\}\\
        &=\bigcap_{\substack{i,j\in \{1,\dots,N\}\\i \leq j}} \{\bm{x} \in X^{N} \mid \neg(\bm{x}(\pi(j)) \prec \bm{x}(\pi(i)))\}
        \\
        &=\bigcap_{\substack{i,j \in \{1,\dots,N\}: \\ i \leq j}} A_{i,j}^{\mathtt{C}}
    \end{align*}
    is therefore a finite intersection of measurable sets and hence measurable. 
\end{proof}

