\begin{prop}\label{prop:measurable-partition-sorting}
    Let $(X, \preceq, d)$ be a metric space endowed with a Borel partial order. Let $\varphi:\mathscr{P}\to \mathbb{N}$ be a bijection. Then, the sets 
    \begin{align*}
        \mathscr{U}_n = \mathscr{V}_{\varphi^{-1}(n)} \setminus\bigcup_{\substack{m \in \mathbb{N}:\\ m < n }} \mathscr{V}_{\varphi^{-1}(m)}
    \end{align*}
    form a measurable partition of $\mathscr{T}(X)$. 
\end{prop}

environments.statement:
\label{prop:measurable-partition-sorting}
    Let $(X, \preceq, d)$ be a metric space endowed with a Borel partial order. Let $\varphi:\mathscr{P}\to \mathbb{N}$ be a bijection. Then, the sets 
    \begin{align*}
        \mathscr{U}_n = \mathscr{V}_{\varphi^{-1}(n)} \setminus\bigcup_{\substack{m \in \mathbb{N}:\\ m < n }} \mathscr{V}_{\varphi^{-1}(m)}
    \end{align*}
    form a measurable partition of $\mathscr{T}(X)$.

proof.rawEnvironment:
\begin{proof}
    First, note that $\mathscr{P}$ is countably infinite, since it is countable by Proposition~\ref{prop:permutations-countable} and contains at least one permutation of each length $n\in\mathbb{N}_0$. Hence there exists a bijection $\varphi:\mathscr{P} \to \mathbb{N}$. Consequently, the associated sorting map defined in Proposition~\ref{prop:induced-sorting} is continuous when restricted to the sets $(\mathscr{U}_n)_{n\in\mathbb{N}}$ (as defined in Proposition~\ref{prop:measurable-partition-sorting}) by Corollary~\ref{cor:local-continuity-sorting}. Since $(\mathscr{U}_n)_{n\in\mathbb{N}}$ forms a measurable partition, and since the Borel $\sigma$-algebra of a subspace $A$ of a metric space $Y$ is the trace $\{B \cap A \mid B \in \mathcal{B}(Y)\}$, so that continuity on $\mathscr{U}_n$ gives measurability with respect to the trace $\sigma$-algebra, it follows by Theorem~\ref{thm:measurable-partition} that the associated sorting map is measurable.
\end{proof}

environments.rawEnvironment:
\begin{thm}\label{thm:measurable-sorting-exists}
    Let $(X, \preceq, d)$ be a metric space equipped with a Borel partial order. Let $(\mathscr{T}(X), \mathscr{d}_H)$ be the associated tuple Hausdorff space, and endow $\mathscr{S}(X,\preceq)$ with the Borel $\sigma$-algebra of its subspace topology. Then there exists a Borel measurable sorting map $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$. 
\end{thm}

proof.rawEnvironment:
\begin{proof}
    Following the proof of Theorem~\ref{thm:measurable-sorting-exists}, it is clear that for each bijection $\varphi : \mathscr{P} \to \mathbb{N}$, the associated sorting map is measurable. However, 
    \begin{align*}
        \Phi = \{\varphi:\mathscr{P} \to \mathbb{N} \mid \varphi \text{ is bijective}\}
    \end{align*}
    has the cardinality of the continuum; as $\mathscr{P}$ and $\mathbb{N}$ are equinumerous, $\Phi$ must have the same cardinality as the set of bijections between $\mathbb{N}$ and itself, which is well known to be that of the continuum.
\end{proof}

