    \end{align*}
    As $P$ and the $\pi_k$ vary, these sets form a finite measurable partition of $X^n$.

    On each set $\mathscr{E}(P,\pi_1,\dots,\pi_m)$, both the comparability components and the minimum sorting permutation within each component are fixed. Since $C_1,\dots,C_m$ partition $\{1,\dots,n\}$, we have $\pi_1\oplus\dots\oplus\pi_m \in \mathscr{P}_n$. Consequently, on this set the map $\varsigma_{\mathrm{min}}$ agrees with the fixed permutation map
    \begin{align*}
        \bm{x} \mapsto \bm{x}[\pi_1 \oplus \dots \oplus \pi_m].
    \end{align*}
By Proposition~\ref{prop:permuting-continuous}, this map is continuous, hence measurable. Therefore, by Theorem~\ref{thm:measurable-partition}, the restriction of $\varsigma_{\mathrm{min}}$ to $X^n$ is measurable.

    Since $n$ was arbitrary, another application of the \hyperref[thm:the-standard-machinery]{standard machinery} yields that $\varsigma_{\mathrm{min}}:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ is Borel measurable.

environments.rawEnvironment:
\begin{thm}\label{thm:minimal-sorting-measurable}
    Let $(X, \preceq, d)$ be a metric space equipped with a Borel partial order. Let $(\mathscr{T}(X), \mathscr{d}_H)$ be the associated tuple Hausdorff space, and endow $\mathscr{S}(X,\preceq)$ with its subspace Borel $\sigma$-algebra. Then, the minimum sorting map $\varsigma_{\mathrm{min}}:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ is Borel measurable.
\end{thm}

\begin{defn}[Concatenation]\label{defn:concat-tuple}\index{concatenation}
    Let $X$ be a non-empty set, and let $\mathscr{T}(X)$ be the associated tuple space. The binary operation $\oplus: \mathscr{T}(X)\times \mathscr{T}(X) \to \mathscr{T}(X)$ given by
    \begin{align*}
      \begin{aligned}
        &\bm{x} \oplus \bm{y}: \{1, \dots, \ell(\bm{x}) + \ell(\bm{y})\} \to X, \\
        &i \mapsto \begin{cases}
            \bm{x}(i) & i \in \mathrm{domain}(\bm{x}) \\
            \bm{y}(i - \ell(\bm{x})) & i \in \{j +\ell(\bm{x}) \mid j \in \mathrm{domain}(\bm{y})\}
        \end{cases}
      \end{aligned}
    \end{align*}
    is called the concatenation operator. 
\end{defn}

