environments.rawEnvironment:
\begin{rem}\label{rem:concat-empty-tuples}
    We remark that if both $\bm{x}$ and $\bm{y}$ are empty tuples, then $\bm{x} \oplus \bm{y}$ is the empty tuple as well. Specifically, we use the convention that $\{1, \dots, 0\} = \emptyset$.
\end{rem}

\begin{defn}[Sorted Tuple Addition]\label{defn:sorted-tuple-add}\index{sorted tuple addition}
    Let $(X, \preceq)$ be a non-empty partially ordered set, $\mathscr{S}(X, \preceq)$ be the sorted tuple space, and $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X, \preceq)$ be a fixed sorting map. The binary operation $+: \mathscr{T}(X)\times \mathscr{T}(X) \to \mathscr{S}(X, \preceq)$ given by 
    \begin{align*}
        \bm{x} + \bm{y} = \varsigma(\bm{x} \oplus \bm{y})
    \end{align*}
    is called the sorted addition operator.
\end{defn}

environments.statement:
\label{defn:sorted-tuple-add}\index{sorted tuple addition}
    Let $(X, \preceq)$ be a non-empty partially ordered set, $\mathscr{S}(X, \preceq)$ be the sorted tuple space, and $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X, \preceq)$ be a fixed sorting map. The binary operation $+: \mathscr{T}(X)\times \mathscr{T}(X) \to \mathscr{S}(X, \preceq)$ given by 
    \begin{align*}
        \bm{x} + \bm{y} = \varsigma(\bm{x} \oplus \bm{y})
    \end{align*}
    is called the sorted addition operator.

proof.rawEnvironment:
\begin{proof}
    We must show that, for all $\bm{x},\bm{x}^\prime, \bm{x}^\ast \in \mathscr{S}(X, \preceq)$, the operation satisfies
    \begin{enumerate}[(i)]
        \item $(\bm{x} + \bm{x}^\prime) + \bm{x}^\ast = \bm{x} + (\bm{x}^\prime + \bm{x}^\ast)$ (associativity). \label{property:associative}
        \item $\bm{x} + \bm{e} = \bm{x}$ (identity element).  \label{property:identity}
        \item $\bm{x} + \bm{x}^\prime = \bm{x}^\prime + \bm{x}$ (commutativity). \label{property:commutative}
        \item $\bm{x} + \bm{x}^\prime = \bm{x}^\ast + \bm{x}^\prime \text{ implies } \bm{x} = \bm{x}^\ast$ (right cancellation).  \label{property:right-cancel}
        \item $\bm{x}^\prime + \bm{x} = \bm{x}^\prime + \bm{x}^\ast \text{ implies } \bm{x} = \bm{x}^\ast$ (left cancellation).  \label{property:left-cancel}
    \end{enumerate}
    The identity property \eqref{property:identity} is immediate. Since $\bm{x}\oplus \bm{e} = \bm{x}$ and $\bm{x}$ is already sorted, idempotency of the sorting map on $\mathscr{S}(X,\preceq)$ yields $\bm{x} + \bm{e} = \bm{x}$.

    For each $a \in X$ and each tuple $\bm{z}\in \mathscr{T}(X)$ define the multiplicity
    \begin{align*}
        N_a(\bm{z}) = |\{i \in \mathrm{domain}(\bm{z}) \mid \bm{z}(i) = a\}|.
    \end{align*}
    Sorting does not change multiplicities, and concatenation adds them, i.e., for every $a \in X$ and $\bm{x},\bm{y} \in \mathscr{T}(X)$,
    \begin{align*}
        N_a(\bm{x}+\bm{y}) = N_a(\bm{x}) + N_a(\bm{y}).
    \end{align*}

    For \eqref{property:associative}, notice that both $(\bm{x} + \bm{x}^\prime) + \bm{x}^\ast=\varsigma(\varsigma(\bm{x} \oplus \bm{x}^\prime) \oplus \bm{x}^\ast)$ and $\bm{x} + (\bm{x}^\prime + \bm{x}^\ast)=\varsigma(\bm{x} \oplus \varsigma(\bm{x}^\prime \oplus \bm{x}^\ast))$ are sorted tuples containing every $a\in X$ exactly $N_a(\bm{x})+N_a(\bm{x}^\prime)+N_a(\bm{x}^\ast)$ times. Under a total order, a sorted tuple is non-decreasing (Proposition~\ref{prop:totally-ordered-tuple-sorted-iff-monotone}), so its $i^{\mathrm{th}}$ entry is the smallest of its entries $a$ with $\sum_{b\preceq a}N_b\geq i$; hence two sorted tuples with equal multiplicities coincide, and both expressions are the same tuple. The same argument proves \eqref{property:commutative}.

    From \eqref{property:commutative} it suffices to show \eqref{property:right-cancel}, as \eqref{property:left-cancel} then follows immediately. If $\bm{x} + \bm{x}^\prime = \bm{x}^\ast + \bm{x}^\prime$, then for every $a \in X$,
    \begin{align*}
        N_a(\bm{x}) + N_a(\bm{x}^\prime)
        = N_a(\bm{x}+\bm{x}^\prime)
        = N_a(\bm{x}^\ast+\bm{x}^\prime)
        = N_a(\bm{x}^\ast) + N_a(\bm{x}^\prime),
    \end{align*}
    and hence $N_a(\bm{x}) = N_a(\bm{x}^\ast)$. Since both $\bm{x}$ and $\bm{x}^\ast$ are sorted in the same total order, equality of all multiplicities implies $\bm{x} = \bm{x}^\ast$, as shown in the proof of \eqref{property:associative}. This proves right cancellation.
\end{proof}

