\begin{prop}[The Sorted Tuple Space Forms a Commutative Monoid]\label{prop:tuple-monoid}
    Let $(X, \preceq)$ be a totally ordered set. Then the restriction of $+$ from Definition~\ref{defn:sorted-tuple-add} to $\mathscr{S}(X, \preceq)\times \mathscr{S}(X, \preceq)$ makes $(\mathscr{S}(X, \preceq), +)$ into a commutative monoid with the cancellation\index{cancellation} property.
\end{prop}

\begin{defn}[Pairing]\label{defn:pairing}\index{pairing}
    Let $(X, \preceq)$ be a totally ordered set. Define for each $\xi \in \mathscr{F}(X)$ the associated tuple $\xi^\dagger : \{i \in \mathbb{N} \mid i \leq |\xi|\} \to X$ by the recursive expression
    \begin{align*}
        \xi^\dagger(i) = \min \{x \in \xi \mid x \notin \{\xi^\dagger(j) \mid j <i\}\},
    \end{align*}
    where the minimum is taken with respect to the total order, $\preceq$. 
\end{defn}

environments.statement:
\label{defn:pairing}\index{pairing}
    Let $(X, \preceq)$ be a totally ordered set. Define for each $\xi \in \mathscr{F}(X)$ the associated tuple $\xi^\dagger : \{i \in \mathbb{N} \mid i \leq |\xi|\} \to X$ by the recursive expression
    \begin{align*}
        \xi^\dagger(i) = \min \{x \in \xi \mid x \notin \{\xi^\dagger(j) \mid j <i\}\},
    \end{align*}
    where the minimum is taken with respect to the total order, $\preceq$.

proof.rawEnvironment:
\begin{proof}
    By Definition~\ref{defn:pairing}, $\xi^\dagger$ is strictly increasing, hence non-decreasing and therefore sorted by Proposition~\ref{prop:totally-ordered-tuple-sorted-iff-monotone}.
\end{proof}

environments.rawEnvironment:
\begin{cor}\label{cor:pairing-finite-set-is-sorted-tuple}
    Let $(X, \preceq)$ be a totally ordered set. Then for any $\xi \in \mathscr{F}(X)$ it holds that $\xi^\dagger \in \mathscr{S}(X,\preceq)$. In particular, $(\cdot)^\dagger:\mathscr{F}(X) \to \mathscr{S}(X,\preceq)$.
\end{cor}

\begin{defn}[Reindexing]\label{defn:reindex}\index{reindexing}
    Let $X$ be a non-empty set and let $\mathscr{T}(X)$ be the associated space of tuples. Moreover, let $\mathscr{F}(\mathbb{N})$ be the set of finite subsets of the natural numbers. Then, for any tuple $\bm{x}\in \mathscr{T}(X)$ and $\eta \in \mathscr{F}(\mathbb{N})$ we define 
    \begin{align*}
\bm{x}[\eta] : \{1,\dots,|\eta \cap \mathrm{domain}(\bm{x})|\}\to X,\qquad i \mapsto \bm{x}((\eta \cap \mathrm{domain}(\bm{x}))^\dagger(i)).
    \end{align*}
\end{defn}

environments.statement:
\label{defn:reindex}\index{reindexing}
    Let $X$ be a non-empty set and let $\mathscr{T}(X)$ be the associated space of tuples. Moreover, let $\mathscr{F}(\mathbb{N})$ be the set of finite subsets of the natural numbers. Then, for any tuple $\bm{x}\in \mathscr{T}(X)$ and $\eta \in \mathscr{F}(\mathbb{N})$ we define 
    \begin{align*}
\bm{x}[\eta] : \{1,\dots,|\eta \cap \mathrm{domain}(\bm{x})|\}\to X,\qquad i \mapsto \bm{x}((\eta \cap \mathrm{domain}(\bm{x}))^\dagger(i)).
    \end{align*}

environments.rawEnvironment:
\begin{rem}\label{rem:reindex-bracket-notation}
    Note that reindexing uses the same bracket notation as permuting, cf. Definition~\ref{defn:permutation-map}, because both operations precompose $\bm{x}$ with an index map, and here $\bm{x}[\eta]=\bm{x}\circ(\eta\cap\mathrm{domain}(\bm{x}))^\dagger$. Unlike a permutation, however, reindexing may discard indices; it keeps the relative order of the remaining ones and relabels them as $1,\dots,n$.
\end{rem}

\begin{defn}[Cancellation]\label{defn:cancel}
    Let $X$ be a non-empty set and $\mathscr{T}(X)$ be the associated tuple space. Let $\mathscr{F}(\mathbb{N})$ denote the set of finite subsets of $\mathbb{N}$. Define the operation $\ominus: \mathscr{T}(X)\times \mathscr{F}(\mathbb{N}) \to \mathscr{T}(X)$ by  
    \begin{align*}
        \bm{x} \ominus \eta = \bm{x}[\mathrm{domain}(\bm{x})\setminus\eta]. 
    \end{align*}
\end{defn}

