\begin{exmp}[Identifier Coordinates]\label{exmp:identifier-coordinates}\index{identifier}
    Let $(Y,d_Y)$ be a metric space and let $(I,\leq)$ be a countable, totally ordered set. On $X=Y\times I$, consider the metric
    \begin{align*}
        d\bigl((y,i),(y^\prime,j)\bigr)=\max\bigl(d_Y(y,y^\prime),d_I(i,j)\bigr),
        \qquad
        d_I(i,j)=\mathbbm{1}(i\neq j),
    \end{align*}
    and the projections $\mathrm{id} : X \to I$ defined by $\mathrm{id}(y,i)=i$ and $\varpi: X \to Y$ defined by $\varpi(y,i)=y$. We call $\mathrm{id}(x)$ the \emph{identifier} of $x\in X$. 

    Since $d_I\leq d$, the map $\mathrm{id}:X\to(I,d_I)$ is $1$-Lipschitz and hence locally constant. Since $(I,d_I)$ is countable and discrete, $X$ is Polish whenever $Y$ is. We write $\mathscr{T}_{\neq}(X) = \{\bm{x} \in \mathscr{T}(X) \mid\mathrm{id}\circ\bm{x} \text{ is injective}\}.$ 
\end{exmp}

