\begin{defn}[Identifier-Based Cancellation]\label{defn:identifier-cancel}\index{cancellation!identifier-based}
    Let $Y$ be a set, let $I$ be a countable, totally ordered set, let $X=Y\times I$ with $\mathrm{id}(y,i)=i$, and let $\mathscr{F}(I)$ denote the set of finite subsets of $I$. For $\bm{x}\in\mathscr{T}(X)$ and $J\in\mathscr{F}(I)$, let
    \begin{align*}
        \eta_J(\bm{x})=\{k\in\mathrm{domain}(\bm{x})\mid\mathrm{id}(\bm{x}(k))\in J\}
    \end{align*}
    be the indices of the entries whose identifiers lie in $J$. Define the operation $\ominus_I:\mathscr{T}(X)\times\mathscr{F}(I)\to\mathscr{T}(X)$ by
    \begin{align*}
        \bm{x}\ominus_I J=\bm{x}\ominus\eta_J(\bm{x}).
    \end{align*}
\end{defn}

environments.statement:
\label{defn:identifier-cancel}\index{cancellation!identifier-based}
    Let $Y$ be a set, let $I$ be a countable, totally ordered set, let $X=Y\times I$ with $\mathrm{id}(y,i)=i$, and let $\mathscr{F}(I)$ denote the set of finite subsets of $I$. For $\bm{x}\in\mathscr{T}(X)$ and $J\in\mathscr{F}(I)$, let
    \begin{align*}
        \eta_J(\bm{x})=\{k\in\mathrm{domain}(\bm{x})\mid\mathrm{id}(\bm{x}(k))\in J\}
    \end{align*}
    be the indices of the entries whose identifiers lie in $J$. Define the operation $\ominus_I:\mathscr{T}(X)\times\mathscr{F}(I)\to\mathscr{T}(X)$ by
    \begin{align*}
        \bm{x}\ominus_I J=\bm{x}\ominus\eta_J(\bm{x}).
    \end{align*}

environments.rawEnvironment:
\begin{rem}\label{rem:identifier-coordinates}
    Identifiers do not change when entries are removed. Unlike its index-based counterpart, identifier-based cancellation therefore composes, in the sense that for all $J,J^\prime\in\mathscr{F}(I)$,
    \begin{align*}
        (\bm{x}\ominus_I J)\ominus_I J^\prime=\bm{x}\ominus_I(J\cup J^\prime).
    \end{align*}
    In the metric setting of Example~\ref{exmp:identifier-coordinates}, the identifier carries no metric information beyond equality. Under the pseudometric $\bar{d}((y,i),(y^\prime,j))=d_Y(y,y^\prime)$, elements that differ only in their identifiers lie at distance $0$, and identifying such elements recovers $(Y,d_Y)$ through $\varpi$; the maps that disregard identifiers are precisely those that factor through $\varpi$. The metric $d$ instead separates distinct identifiers by $1$, which makes $\mathrm{id}$ continuous. Had we indexed a disjoint union $\bigsqcup_{i\in I}Y$ (Definition~\ref{defn:disjoint-union}) by the identifiers instead, elements with distinct identifiers would lie at distance $\infty$ (Definition~\ref{defn:disjoint-union-metrisation}) and be incomparable under the induced partial order (Proposition~\ref{prop:disjoint-partial-order}), so that no sorting could rank them against each other. In the product, identifiers can instead break ties (Proposition~\ref{prop:identifier-tie-breaking}).
\end{rem}

