\begin{defn}[Sorted Cancellation]\label{defn:sorted-cancel}
    Let $(X,\preceq)$ be a non-empty partially ordered set, let $\mathscr{T}(X)$ be the associated tuple space, and let $\mathscr{S}(X,\preceq)$ be the subspace of sorted tuples. Let $\varsigma :\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ be a fixed sorting map. Finally, let $\mathscr{F}(\mathbb{N})$ denote the set of finite subsets of $\mathbb{N}$. Define the operation $-:\mathscr{T}(X)\times \mathscr{F}(\mathbb{N}) \to \mathscr{S}(X, \preceq)$ by
    \begin{align*}
        \bm{x} - \eta = \varsigma(\bm{x} \ominus \eta).
    \end{align*}
\end{defn}

environments.statement:
\label{defn:sorted-cancel}
    Let $(X,\preceq)$ be a non-empty partially ordered set, let $\mathscr{T}(X)$ be the associated tuple space, and let $\mathscr{S}(X,\preceq)$ be the subspace of sorted tuples. Let $\varsigma :\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ be a fixed sorting map. Finally, let $\mathscr{F}(\mathbb{N})$ denote the set of finite subsets of $\mathbb{N}$. Define the operation $-:\mathscr{T}(X)\times \mathscr{F}(\mathbb{N}) \to \mathscr{S}(X, \preceq)$ by
    \begin{align*}
        \bm{x} - \eta = \varsigma(\bm{x} \ominus \eta).
    \end{align*}

proof.rawEnvironment:
\begin{proof}
    Deleting entries from a sorted tuple leaves the remaining entries sorted, so $\bm{x}\ominus\eta \in \mathscr{S}(X,\preceq)$. Under a total order the sorting map fixes sorted tuples (Corollary~\ref{cor:unique-sorting-map-total-order}), whence $\bm{x}-\eta=\varsigma(\bm{x}\ominus\eta)=\bm{x}\ominus\eta$.
\end{proof}

