\begin{cor}\label{cor:cancel-closure-sorted}
    Let $(X,\preceq)$ be a totally ordered set and $\mathscr{S}(X,\preceq)$ be the associated sorted tuple space. Then, 
    \begin{align*}
        \bm{x} - \eta = \bm{x}\ominus\eta
    \end{align*}
    for every $\bm{x} \in \mathscr{S}(X,\preceq)$ and $\eta \in \mathscr{F}(\mathbb{N})$.
\end{cor}

