\begin{prop}[Identifiers as Tie-Breakers]\label{prop:identifier-tie-breaking}
    Let $Y$ be a set, let $(I,\leq)$ be a countable, totally ordered set, let $X=Y\times I$ with $\mathrm{id}(y,i)=i$, and let $\mathscr{T}_{\neq}(X)=\{\bm{x}\in\mathscr{T}(X)\mid\mathrm{id}\circ\bm{x}\text{ is injective}\}$. Let $(K,<)$ be a strictly totally ordered set, let $h:Y\to K$ be a map, and let $H:X\to K\times I$ be given by $H(y,i)=(h(y),i)$. Let $\sqsubset$ be the strict lexicographic order on $K\times I$,
    \begin{align*}
        (a,i)\sqsubset(b,j)\iff a<b\ \lor\ \bigl(a=b\land i<j\bigr),
    \end{align*}
    and define the relation $\preceq_I$ on $X$ by
    \begin{align*}
        x\preceq_I x^\prime\iff x=x^\prime\ \lor\ H(x)\sqsubset H(x^\prime).
    \end{align*}
    Then
    \begin{enumerate}[(i)]
        \item $(X,\preceq_I)$ is a partially ordered set, and the restriction of $\preceq_I$ to the entries of any $\bm{x}\in\mathscr{T}_{\neq}(X)$ is total, and\label{property:tie-break-order}
        \item each $\bm{x}\in\mathscr{T}_{\neq}(X)$ has exactly one sorted rearrangement, so all sorting maps $\varsigma:\mathscr{T}(X)\to\mathscr{S}(X,\preceq_I)$ agree on $\mathscr{T}_{\neq}(X)$.\label{property:tie-break-unique}
    \end{enumerate}
\end{prop}

