\begin{prop}[Borel Tie-Breaking]\label{prop:identifier-tie-breaking-borel}
    Let $(Y,d_Y)$ be a metric space, let $(I,\leq)$ be a countable, totally ordered set, and let $X=Y\times I$ be endowed with the metric
    \begin{align*}
        d\bigl((y,i),(y^\prime,j)\bigr)=\max\bigl(d_Y(y,y^\prime),d_I(i,j)\bigr),
        \qquad
        d_I(i,j)=\mathbbm{1}(i\neq j).
    \end{align*}
    Let $(K,d_K)$ be a separable metric space with a strict total order $<$ such that ${<}\in\mathcal{B}(K\times K)$, and let $h:Y\to K$ be Borel measurable. Then the relation $\preceq_I$ of Proposition~\ref{prop:identifier-tie-breaking} is a Borel partial order on $X$, that is, ${\preceq_I}\in\mathcal{B}(X\times X)$.
\end{prop}

