\begin{defn}[Modification]\label{defn:modification}\index{modification}
    Let $X$ be a non-empty set, let $\mathscr{T}(X)$ be the associated set of tuples, and let $\mathscr{L}(X)$ be the set of labelled finite sets over $X$. Let $\circledast:\mathscr{T}(X) \times \mathscr{L}(X)\to \mathscr{T}(X)$ be the map defined by
    \begin{align*}
        \bm{x} \circledast \xi &: \mathrm{domain}(\bm{x}) \to X\\
        i &\mapsto \begin{cases}
            \bm{x}(i) & i \in \mathrm{domain}(\bm{x}) \text{ and } i \notin \{j \mid \exists z \in X: (j,z) \in \xi\}\\
            z & (i, z) \in \xi \text{ and } i \in \mathrm{domain}(\bm{x}).
        \end{cases}
    \end{align*}
    Moreover, if $(X, \preceq)$ is a partially ordered set, and $\mathscr{S}(X,\preceq)$ is the space of sorted tuples, and $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ is a fixed sorting map, then we define $\ast: \mathscr{T}(X)\times \mathscr{L}(X) \to \mathscr{S}(X,\preceq)$ by
    \begin{align*}
        \bm{x} \ast \xi = \varsigma(\bm{x} \circledast \xi).
    \end{align*}
\end{defn}

