environments.rawEnvironment:
\begin{rem}\label{rem:void-modification}
The modification operation implicitly defines void modifications, for which $\{i \in \mathbb{N} \mid \exists z \in X: (i,z) \in \xi\} \cap \mathrm{domain}(\bm{x}) = \emptyset$ and hence $\bm{x} \circledast \xi = \bm{x}$. For the sorted modification, the same void input gives $\bm{x} \ast \xi=\varsigma(\bm{x})$, which equals $\bm{x}$ whenever $\bm{x}$ is sorted and $\varsigma$ fixes sorted tuples.
\end{rem}

proof.rawEnvironment:
\begin{proof}
    Let $\varepsilon > 0$ and fix $\delta \in (0,\min(1,\varepsilon))$.

    For \eqref{property:concat-continuous}, suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), \mathscr{d}_H(\bm{y}, \bm{y}_0)) < \delta.
    \end{align*}
    Since $\delta < 1$, the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}) implies
    \begin{align*}
        m \overset{\mathrm{def}}{=} \ell(\bm{x}) = \ell(\bm{x}_0)
        \qquad \text{and} \qquad
        n \overset{\mathrm{def}}{=} \ell(\bm{y}) = \ell(\bm{y}_0),
    \end{align*}
    and, since $\min(\mathscr{d}_H,1)=\min(d_\infty,1)$ on each layer, where $d_\infty$ is the maximum pointwise metric, the two distances coincide on each layer whenever either is below $1$. If $m+n = 0$, then both outputs are empty tuples and there is nothing to show. Otherwise,
    \begin{align*}
        \mathscr{d}_H(\bm{x}\oplus\bm{y}, \bm{x}_0\oplus\bm{y}_0)
        = \max_{i \in \{1,\dots,m+n\}} d\big((\bm{x}\oplus\bm{y})(i),(\bm{x}_0\oplus\bm{y}_0)(i)\big)
        < \delta < \varepsilon.
    \end{align*}
    Hence $\oplus$ is continuous.

    For \eqref{property:cancel-continuous}, suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), d_H(\eta,\eta_0)) < \delta.
    \end{align*}
    Again, $\delta < 1$ implies $\ell(\bm{x}) = \ell(\bm{x}_0)$ and
    \begin{align*}
        d_H(\eta,\eta_0) < 1 \implies \eta = \eta_0
    \end{align*}
    because $(\mathbb{N},|\cdot|)$ is uniformly discrete and hence so is $(\mathscr{F}(\mathbb{N}),d_H)$ by Proposition~\ref{prop:finite-hausdorff-uniformly-discrete}. Let
    \begin{align*}
        I = \mathrm{domain}(\bm{x}_0)\setminus \eta_0.
    \end{align*}
    If $I = \emptyset$, then both $\bm{x}\ominus\eta$ and $\bm{x}_0\ominus\eta_0$ are empty tuples, so the distance is $0$. Otherwise, if
    \begin{align*}
        I = \{i_1 < \dots < i_k\},
    \end{align*}
    then reindexing simply produces the tuples
    \begin{align*}
        \bm{x}\ominus\eta &= r \mapsto \bm{x}(i_r),\\
        \bm{x}_0\ominus\eta_0 &= r \mapsto \bm{x}_0(i_r),
    \end{align*}
    and therefore
    \begin{align*}
        \mathscr{d}_H(\bm{x}\ominus\eta, \bm{x}_0\ominus\eta_0)
        &= \max_{r\in\{1,\dots,k\}} d(\bm{x}(i_r), \bm{x}_0(i_r))\\
        &\leq \max_{i \in \mathrm{domain}(\bm{x}_0)} d(\bm{x}(i), \bm{x}_0(i))\\
        &< \delta < \varepsilon.
    \end{align*}
    Hence $\ominus$ is continuous.

    Finally, consider \eqref{property:modification-continuous} and suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), d_H^\ast(\xi,\xi_0)) < \delta.
    \end{align*}
    Since $\delta < 1$, the tuple part gives $\ell(\bm{x}) = \ell(\bm{x}_0)$, and as $d_H^\ast(\xi,\xi_0)<1$, Lemma~\ref{lem:helpful-labelled} shows that $\xi$ and $\xi_0$ have exactly the same set of indices. Denote this common finite index set by
    \begin{align*}
        D = \{n\in\mathbb{N}\mid \exists z\in X:(n,z)\in\xi\} = \{n\in\mathbb{N}\mid \exists z\in X:(n,z)\in\xi_0\}.
    \end{align*}
    Moreover, for every $n \in D$ there are unique elements $\xi(n), \xi_0(n) \in X$ with
    \begin{align*}
        (n,\xi(n)) \in \xi
        \qquad \text{and} \qquad
        (n,\xi_0(n)) \in \xi_0,
    \end{align*}
    and they satisfy
    \begin{align*}
        d(\xi(n),\xi_0(n)) < \delta.
    \end{align*}

If $\ell(\bm{x}_0)=0$, then both $\bm{x}\circledast\xi$ and $\bm{x}_0\circledast\xi_0$ are empty tuples, so their tuple Hausdorff distance is $0$. We may therefore assume that $\ell(\bm{x}_0)>0$.
    Now let $m = \ell(\bm{x}_0) = \ell(\bm{x})$. For each $i \in \{1,\dots,m\}$ there are two cases. If $i \notin D$, then
    \begin{align*}
        (\bm{x}\circledast \xi)(i) = \bm{x}(i)
        \qquad \text{and} \qquad
        (\bm{x}_0\circledast \xi_0)(i) = \bm{x}_0(i).
    \end{align*}
    If $i \in D$, then
    \begin{align*}
        (\bm{x}\circledast \xi)(i) = \xi(i)
        \qquad \text{and} \qquad
        (\bm{x}_0\circledast \xi_0)(i) = \xi_0(i).
    \end{align*}
    Hence, for every $i \in \{1,\dots,m\}$,
    \begin{align*}
        d\big((\bm{x}\circledast \xi)(i), (\bm{x}_0\circledast \xi_0)(i)\big) < \delta.
    \end{align*}
    By the \hyperref[thm:the-standard-machinery]{standard machinery}, the output tuples lie on the same length layer, so
    \begin{align*}
        \mathscr{d}_H(\bm{x}\circledast \xi, \bm{x}_0\circledast \xi_0)
        = \max_{i\in\{1,\dots,m\}} d\big((\bm{x}\circledast \xi)(i), (\bm{x}_0\circledast \xi_0)(i)\big)
        < \delta < \varepsilon.
    \end{align*}
    Therefore, $\circledast$ is continuous.
\end{proof}

