\begin{thm}\label{thm:analytic-properties-actions}
    Let $(X,d)$ be a metric space, and let
    \begin{enumerate}[-]
        \item $(\mathscr{T}(X), \mathscr{d}_H)$ be the tuple space over $X$ endowed with the tuple Hausdorff distance, 
        \item $(\mathscr{F}(\mathbb{N}), d_H)$ be the set of finite subsets of the natural numbers, endowed with the Hausdorff distance induced by the Euclidean distance, and 
        \item $(\mathscr{L}(X), d_H^\ast)$ be the set of labelled finite sets over $X$, endowed with the index-augmented Hausdorff distance.
    \end{enumerate}
    If all product spaces are endowed with the product metrics, then 
    \begin{enumerate}[(i)]
        \item $\oplus:\mathscr{T}(X) \times \mathscr{T}(X) \to \mathscr{T}(X)$ as defined in Definition~\ref{defn:concat-tuple} is continuous\index{continuity!primitive actions},\label{property:concat-continuous}
        \item $\ominus:\mathscr{T}(X)\times \mathscr{F}(\mathbb{N})\to\mathscr{T}(X)$ as defined in Definition~\ref{defn:cancel} is continuous, and \label{property:cancel-continuous}
        \item $\circledast:\mathscr{T}(X) \times \mathscr{L}(X) \to \mathscr{T}(X)$ as defined in Definition~\ref{defn:modification} is continuous. \label{property:modification-continuous}
    \end{enumerate}
\end{thm}

