proof.rawEnvironment:
\begin{proof}
    We must show that the sorted operations $+ = \varsigma \circ \oplus$, $- = \varsigma \circ \ominus$, and $\ast = \varsigma \circ \circledast$ are Borel measurable with respect to the product Borel $\sigma$-algebras on their domains. Since $X$ is separable, $\mathscr{T}(X)$ and $\mathscr{L}(X)$ are separable metric spaces by Theorems~\ref{thm:tuple-space-properties} and~\ref{thm:labelled-properties}, and $\mathscr{F}(\mathbb{N})$ is countable and discrete. Consequently, the product Borel $\sigma$-algebra on each of $\mathscr{T}(X) \times \mathscr{T}(X)$, $\mathscr{T}(X) \times \mathscr{F}(\mathbb{N})$, and $\mathscr{T}(X) \times \mathscr{L}(X)$ coincides with the Borel $\sigma$-algebra induced by the corresponding product metric topology. By Theorem~\ref{thm:analytic-properties-actions}, the unsorted operations $\oplus$, $\ominus$, and $\circledast$ are continuous with respect to the product metrics and are therefore Borel measurable. Composing each of these Borel measurable maps with the Borel measurable sorting map $\varsigma : \mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ establishes (i)--(iii), as desired.
\end{proof}

\begin{proof}
    To prove \eqref{property:identifier-cancel-continuous}, we must show that for every $(\bm{x}_0, J_0) \in \mathscr{T}(X) \times \mathscr{F}(I)$ and every $\varepsilon > 0$, there exists a $\delta > 0$ such that
    \begin{align*}
        \max\bigl(\mathscr{d}_H(\bm{x}, \bm{x}_0), d_H(J, J_0)\bigr) < \delta \implies \mathscr{d}_H(\bm{x} \ominus_I J, \bm{x}_0 \ominus_I J_0) < \varepsilon.
    \end{align*}
    Fix $\varepsilon > 0$ and choose $\delta \in (0, \min(1, \varepsilon))$. Suppose that $\max(\mathscr{d}_H(\bm{x},\bm{x}_0),d_H(J,J_0))<\delta < 1$. By the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}), we have $\ell(\bm{x})=\ell(\bm{x}_0)$ and, whenever $\ell(\bm{x}_0) > 0$,
    \begin{align*}
        d(\bm{x}(k),\bm{x}_0(k)) < \delta < 1 \qquad \forall k \in \mathrm{domain}(\bm{x}_0).
    \end{align*}
    By the definition of $d$ and $d_I$, the inequality $d(\bm{x}(k),\bm{x}_0(k)) < 1$ implies $\mathrm{id}(\bm{x}(k))=\mathrm{id}(\bm{x}_0(k))$ for every $k \in \mathrm{domain}(\bm{x}_0)$. Furthermore, since $(I,d_I)$ is uniformly discrete with bound $1$, so is $(\mathscr{F}(I),d_H)$ by Proposition~\ref{prop:finite-hausdorff-uniformly-discrete}, whence $d_H(J, J_0) < 1$ implies $J=J_0$. Consequently, the index sets of matching identifiers coincide:
    \begin{align*}
        \eta_J(\bm{x}) &= \{k \in \mathrm{domain}(\bm{x}) \mid \mathrm{id}(\bm{x}(k)) \in J\}\\
        &= \{k \in \mathrm{domain}(\bm{x}_0) \mid \mathrm{id}(\bm{x}_0(k)) \in J_0\} = \eta_{J_0}(\bm{x}_0).
    \end{align*}
    On this neighbourhood, we therefore have $\bm{x}\ominus_I J=\bm{x}\ominus\eta_{J_0}(\bm{x}_0)$ and $\bm{x}_0 \ominus_I J_0 = \bm{x}_0 \ominus \eta_{J_0}(\bm{x}_0)$, so the proof of Theorem~\ref{thm:analytic-properties-actions}\eqref{property:cancel-continuous} yields
    \begin{align*}
        \mathscr{d}_H(\bm{x} \ominus_I J, \bm{x}_0 \ominus_I J_0) = \mathscr{d}_H\bigl(\bm{x} \ominus \eta_{J_0}(\bm{x}_0), \bm{x}_0 \ominus \eta_{J_0}(\bm{x}_0)\bigr) < \delta < \varepsilon,
    \end{align*}
    which proves that $\ominus_I$ is continuous.

    Next, we prove \eqref{property:identifier-distinct-clopen}. By the \hyperref[thm:the-standard-machinery]{standard machinery}, each fixed-length layer $X^n$ is clopen in $\mathscr{T}(X)$. For $n \in \{0, 1\}$, we have $\mathscr{T}_{\neq}(X) \cap X^n = X^n$, which is clopen. For $n \geq 2$, the intersection of $\mathscr{T}_{\neq}(X)$ with $X^n$ is given by
    \begin{align*}
        \mathscr{T}_{\neq}(X) \cap X^n = \bigcap_{1 \leq k < l \leq n} \bigl\{\bm{x} \in X^n \bigm| \mathrm{id}(\bm{x}(k)) \neq \mathrm{id}(\bm{x}(l))\bigr\}.
    \end{align*}
    Because $\mathrm{id}:X \to (I, d_I)$ is locally constant, each comparison set in the intersection is clopen in $X^n$, so $\mathscr{T}_{\neq}(X) \cap X^n$ is clopen in $X^n$ for every $n \in \mathbb{N}_0$, and hence $\mathscr{T}_{\neq}(X)$ is clopen in $\mathscr{T}(X)$. By the same argument on the clopen product layers $X^n \times X^m$, the set of pairs
    \begin{align*}
        \bigl\{(\bm{x}, \bm{y}) \in \mathscr{T}_{\neq}(X)^2 \bigm| \forall k \in \mathrm{domain}(\bm{x})\, \forall l \in \mathrm{domain}(\bm{y}) : \mathrm{id}(\bm{x}(k)) \neq \mathrm{id}(\bm{y}(l))\bigr\}
    \end{align*}
    is clopen in $\mathscr{T}_{\neq}(X)^2$, and concatenating any such pair via $\oplus$ yields a tuple with pairwise distinct identifiers, hence in $\mathscr{T}_{\neq}(X)$. Similarly, index-based cancellation $\ominus$ and identifier-based cancellation $\ominus_I$ compose $\mathrm{id} \circ \bm{x}$ with strictly increasing reindexing maps, and any sorting map $\varsigma$ composes $\mathrm{id} \circ \bm{x}$ with a bijection $\pi \in \mathscr{P}_{\ell(\bm{x})}$, so all three preserve injectivity of $\mathrm{id} \circ \bm{x}$. Finally, if $Y$ is Polish, then $X = Y \times I$ is Polish, so $\mathscr{T}(X)$ is Polish by Theorem~\ref{thm:tuple-space-properties}, and $\mathscr{T}_{\neq}(X)$, being a closed (and open) subset of a Polish space, is Polish.

    To prove \eqref{property:identifier-cancel-measurable}, note that since $Y$ is separable and $I$ is countable, both $X$ and $\mathscr{T}(X)$ are separable (Theorem~\ref{thm:tuple-space-properties}), while $\mathscr{F}(I)$ is countable and discrete. Thus the product Borel $\sigma$-algebra $\mathcal{B}(\mathscr{T}(X)) \otimes \mathcal{B}(\mathscr{F}(I))$ coincides with $\mathcal{B}(\mathscr{T}(X) \times \mathscr{F}(I))$. Since $\ominus_I$ is continuous by \eqref{property:identifier-cancel-continuous} and $\varsigma$ is Borel measurable by assumption, their composition $(\bm{x}, J) \mapsto \varsigma(\bm{x} \ominus_I J)$ is Borel measurable.

    Finally, to prove \eqref{property:identifier-forgetful}, we must show that $\varpi_* : \mathscr{T}(X) \to \mathscr{T}(Y)$ is continuous. Fix $\bm{x}_0 \in \mathscr{T}(X)$ and $\varepsilon > 0$, and choose $\delta \in (0, \min(1, \varepsilon))$. If $\mathscr{d}_H(\bm{x}, \bm{x}_0) < \delta < 1$, then $\ell(\bm{x}) = \ell(\bm{x}_0)$, and since $\varpi_*$ preserves tuple lengths, $\ell(\varpi_*(\bm{x})) = \ell(\varpi_*(\bm{x}_0))$. For $\ell(\bm{x}_0) = 0$, both images equal $\bm{e}$; for $\ell(\bm{x}_0) > 0$, the $1$-Lipschitz bound $d_Y(\varpi(x), \varpi(x^\prime)) \leq d(x, x^\prime)$ yields
    \begin{align*}
        \mathscr{d}_H\bigl(\varpi_*(\bm{x}), \varpi_*(\bm{x}_0)\bigr)
        &= \max_{k \in \mathrm{domain}(\bm{x}_0)} d_Y\bigl(\varpi(\bm{x}(k)), \varpi(\bm{x}_0(k))\bigr)\\
        &\leq \max_{k \in \mathrm{domain}(\bm{x}_0)} d\bigl(\bm{x}(k), \bm{x}_0(k)\bigr)
        < \delta < \varepsilon.
    \end{align*}
    Thus $\varpi_*$ is continuous, and composing any continuous or Borel measurable map $g$ on $\mathscr{T}(Y)$ with $\varpi_*$ preserves continuity or Borel measurability, as desired.
\end{proof}

