        \qquad
        d_I(i,j)=\mathbbm{1}(i\neq j),
    \end{align*}
    and with the projections $\mathrm{id}(y,i)=i$ and $\varpi(y,i)=y$. Moreover, let
    \begin{enumerate}[-]
        \item $(\mathscr{T}(X),\mathscr{d}_H)$ and $(\mathscr{T}(Y),\mathscr{d}_H)$ be the tuple spaces over $X$ and $Y$, endowed with the tuple Hausdorff distances,
        \item $\mathscr{T}_{\neq}(X)=\{\bm{x}\in\mathscr{T}(X)\mid\mathrm{id}\circ\bm{x}\text{ is injective}\}$ be the set of tuples with distinct identifiers, and
        \item $(\mathscr{F}(I),d_H)$ be the set of finite subsets of $I$, endowed with the Hausdorff distance induced by $d_I$.
    \end{enumerate}
    If all product spaces are endowed with the product metrics, then
    \begin{enumerate}[(i)]
        \item $\ominus_I:\mathscr{T}(X)\times\mathscr{F}(I)\to\mathscr{T}(X)$ as defined in Definition~\ref{defn:identifier-cancel} is continuous,\label{property:identifier-cancel-continuous}
        \item $\mathscr{T}_{\neq}(X)$ is clopen in $\mathscr{T}(X)$, Polish whenever $Y$ is, and closed under $\ominus$, $\ominus_I$, and every sorting map; moreover, the pairs in $\mathscr{T}_{\neq}(X)^2$ whose identifier sets are disjoint form a clopen set, which $\oplus$ maps into $\mathscr{T}_{\neq}(X)$,\label{property:identifier-distinct-clopen}
        \item if $Y$ is separable, $\preceq$ is a Borel partial order on $X$, such as $\preceq_I$ under the assumptions of Proposition~\ref{prop:identifier-tie-breaking-borel}, and $\varsigma:\mathscr{T}(X)\to\mathscr{S}(X,\preceq)$ is a measurable sorting map, where $\mathscr{S}(X,\preceq)$ carries its subspace Borel $\sigma$-algebra, then $(\bm{x},J)\mapsto\varsigma(\bm{x}\ominus_I J)$ is measurable, and\label{property:identifier-cancel-measurable}
        \item $\varpi_*:\mathscr{T}(X)\to\mathscr{T}(Y)$, $\bm{x}\mapsto\varpi\circ\bm{x}$, is continuous, so a map of the form $g\circ\varpi_*$ is continuous or Borel measurable whenever $g$ is.\label{property:identifier-forgetful}
    \end{enumerate}

environments.rawEnvironment:
\begin{defn}[Action Space and Application Map]\label{defn:actions}\index{action space}\index{application map}
    Let $X$ be a non-empty set and $\mathscr{T}(X)$ the associated tuple space. Let $A=\{\oplus, \ominus, \circledast\}$ denote the set containing the concatenation, cancellation, and modification operations as in Definitions~\ref{defn:concat-tuple}, \ref{defn:cancel}, and \ref{defn:modification}, respectively. Let 
    \begin{align*}
        F_\alpha = \begin{cases}
            \mathscr{T}(X) & \alpha = \oplus\\
            \mathscr{F}(\mathbb{N}) & \alpha = \ominus \\ 
            \mathscr{L}(X) &\alpha = \circledast.
        \end{cases}
    \end{align*}
    Then we call the set $\mathscr{A}(X) = \bigsqcup_{\alpha \in A} F_\alpha$ the action space. Moreover, we define the mapping $\lhd : \mathscr{T}(X) \times  \mathscr{A}(X) \to \mathscr{T}(X)$ by
    \begin{align*}
        \bm{x} \lhd (o, \alpha) = \alpha(\bm{x}, o),
    \end{align*}
    where $\bm{x} \in \mathscr{T}(X)$ and $(o,\alpha) \in \mathscr{A}(X)$. We call $\lhd$ the application map. 
\end{defn}

