\begin{defn}[Ordered Composite Actions]\label{defn:composite-actions}
    Let $X$ be a non-empty set, and let $\mathscr{A}(X)$ be the associated action space. Then, we call 
    \begin{align*}
        \mathscr{C}(X) = \mathscr{T}(\mathscr{A}(X))
    \end{align*}
    the set of composite actions. Moreover, the application map, $\lhd:\mathscr{T}(X) \times \mathscr{A}(X) \to \mathscr{T}(X)$, extends to a mapping $\lhd :\mathscr{T}(X) \times \mathscr{C}(X) \to \mathscr{T}(X)$ defined by  
    \begin{align*}
        \bm{x} \lhd \bm{c} = \begin{cases}
            \bm{x} &\bm{c}=\bm{e}\\ 
            \bm{x} \lhd \bm{c}(1) \lhd \dots \lhd \bm{c}(n) & \ell(\bm{c}) = n > 0,
        \end{cases}
    \end{align*}
    where $\lhd$ is evaluated from left to right, i.e.\ $\bm{x} \lhd \bm{c}(1) \lhd \dots \lhd \bm{c}(n)=(\cdots((\bm{x} \lhd \bm{c}(1)) \lhd \bm{c}(2))\cdots) \lhd \bm{c}(n)$.
\end{defn}

