\begin{cor}\label{cor:action-metrisation}
    Let $(X,d)$ be a metric space, and let
    \begin{enumerate}[-]
        \item $(\mathscr{T}(X),\mathscr{d}_H)$ be the tuple space over $X$ endowed with the tuple Hausdorff distance (Theorem~\ref{thm:tuple-space-metrisation}),
        \item $(\mathscr{F}(\mathbb{N}),d_H)$ be the set of finite subsets of the natural numbers, endowed with the Hausdorff distance induced by the Euclidean distance (Definition~\ref{defn:Hausdorff-distance}), and
        \item $(\mathscr{L}(X),d_H^\ast)$ be the set of labelled finite sets over $X$, endowed with the index-augmented Hausdorff distance (Theorem~\ref{thm:labelled-properties}).
    \end{enumerate}
    Let $A = \{\oplus, \ominus, \circledast\}$ be the set of operations defined in Definitions~\ref{defn:concat-tuple}, \ref{defn:cancel}, and \ref{defn:modification}, respectively. Let
    \begin{align*}
        F_\alpha = \begin{cases}
            \mathscr{T}(X) & \alpha = \oplus\\
            \mathscr{F}(\mathbb{N}) & \alpha = \ominus \\ 
            \mathscr{L}(X) &\alpha = \circledast
        \end{cases},\quad\quad d_\alpha = \begin{cases}
            \mathscr{d}_H & \alpha = \oplus\\
            d_H & \alpha = \ominus \\ 
            d_H^\ast &\alpha = \circledast
        \end{cases},
    \end{align*}
    and let $\mathscr{A}(X) = \bigsqcup_{\alpha \in A} F_\alpha$. Define $\Delta : \mathscr{A}(X)\times \mathscr{A}(X) \to [0,\infty]$ by 
    \begin{align*}
        \Delta((o,\alpha),(o^\prime,\alpha^\prime))=\begin{cases}
            d_\alpha(o,o^\prime)&\alpha = \alpha^\prime \\
            \infty &\alpha \neq \alpha^\prime.
        \end{cases}
    \end{align*}
    Then $(\mathscr{A}(X), \Delta)$ is a metric space. Moreover, if $(X,d)$ is complete, then so is $(\mathscr{A}(X), \Delta)$. Likewise, if $(X,d)$ is separable, then so is $(\mathscr{A}(X), \Delta)$.
\end{cor}

