\begin{thm}\label{thm:composite-action-metric}
    Let $(X,d)$ be a metric space and let $(\mathscr{A}(X), \Delta)$ denote the action space endowed with the metric as in Corollary~\ref{cor:action-metrisation}. Let 
    \begin{align*}
        \mathscr{C}(X)=\mathscr{T}(\mathscr{A}(X))
    \end{align*}
    denote the set of composite actions, and let $\Delta_H :\mathscr{C}(X)\times \mathscr{C}(X) \to [0,\infty]$ be the tuple Hausdorff distance induced by $\Delta$. Then, $(\mathscr{C}(X), \Delta_H)$ is a metric space. Moreover, if $(X,d)$ is complete, then so is $(\mathscr{C}(X),\Delta_H)$. Likewise, if $(X,d)$ is separable, then so is $(\mathscr{C}(X), \Delta_H)$.
\end{thm}

environments.statement:
\label{thm:composite-action-metric}
    Let $(X,d)$ be a metric space and let $(\mathscr{A}(X), \Delta)$ denote the action space endowed with the metric as in Corollary~\ref{cor:action-metrisation}. Let 
    \begin{align*}
        \mathscr{C}(X)=\mathscr{T}(\mathscr{A}(X))
    \end{align*}
    denote the set of composite actions, and let $\Delta_H :\mathscr{C}(X)\times \mathscr{C}(X) \to [0,\infty]$ be the tuple Hausdorff distance induced by $\Delta$. Then, $(\mathscr{C}(X), \Delta_H)$ is a metric space. Moreover, if $(X,d)$ is complete, then so is $(\mathscr{C}(X),\Delta_H)$. Likewise, if $(X,d)$ is separable, then so is $(\mathscr{C}(X), \Delta_H)$.

proof.rawEnvironment:
\begin{proof}
    For each $n \in \mathbb{N}_0$, let
    \begin{align*}
        \mathscr{C}_n(X) = \{\bm{c} \in \mathscr{C}(X) \mid \ell(\bm{c}) = n\}.
    \end{align*}
    By the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}), each layer $\mathscr{C}_n(X)$ is homeomorphic to the finite product $\mathscr{A}(X)^n$ endowed with the maximum product metric.

    Define maps
    \begin{align*}
        \Phi_0 &: \mathscr{T}(X) \to \mathscr{T}(X), \\ 
        \Phi_n &: \mathscr{T}(X) \times \mathscr{A}(X)^n \to \mathscr{T}(X)
    \end{align*}
    recursively by
    \begin{align*}
        \Phi_0(\bm{x}) &= \bm{x},\\
        \Phi_n(\bm{x}, a_1,\dots,a_n) &= \Phi_{n-1}(\bm{x}, a_1,\dots,a_{n-1}) \lhd a_n
    \end{align*}
    for $n \geq 1$. The map $\Phi_0$ is continuous, and if $\Phi_{n-1}$ is continuous, then $\Phi_n$ is continuous by Proposition~\ref{prop:application-continuous}. Hence $\Phi_n$ is continuous for every $n$.

    Under the identification of $\mathscr{C}_n(X)$ with $\mathscr{A}(X)^n$, the restriction of the extended application map
    \begin{align*}
        \lhd : \mathscr{T}(X)\times \mathscr{C}(X) \to \mathscr{T}(X)
    \end{align*}
    to $\mathscr{T}(X)\times \mathscr{C}_n(X)$ is exactly $\Phi_n$, by \eqref{eq:recursive-application}; for $n=0$, this uses the identification of $\mathscr{T}(X)\times\mathscr{C}_0(X)=\mathscr{T}(X)\times\{\bm{e}\}$ with $\mathscr{T}(X)$. Therefore, the restriction to each fixed-length layer is continuous.

    Finally, the composite-action space is the disjoint union of its length layers,
    \begin{align*}
        \mathscr{C}(X) = \bigsqcup_{n\in\mathbb{N}_0} \mathscr{C}_n(X),
    \end{align*}
    and the tuple metric is topologically equivalent to the corresponding disjoint-union metric by the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}). Taking the product with $\mathscr{T}(X)$ distributes over this disjoint union, with each product layer open. The continuity of the global map therefore follows from the pasting lemma for disjoint unions (Theorem~\ref{thm:pasting-lemma}).
\end{proof}

