\begin{thm}\label{thm:composite-application-continuous}
    Let $(X,d)$ be a metric space, $(\mathscr{T}(X), \mathscr{d}_H)$ be the associated tuple space endowed with the tuple Hausdorff distance, and let $(\mathscr{C}(X), \Delta_H)$ be the space of composite actions with the metric as defined in Theorem~\ref{thm:composite-action-metric}. Let the extended application map $\lhd :\mathscr{T}(X) \times \mathscr{C}(X)\to\mathscr{T}(X)$ be defined by $\bm{x} \lhd \bm{c} = \bm{x}$ if $\bm{c} = \bm{e}$, otherwise define $\bm{x}_0 = \bm{x}$ and define recursively
    \begin{align}\label{eq:recursive-application-composite}
        \bm{x}_i = \bm{x}_{i-1} \lhd \bm{c}(i)
    \end{align}
    for $i \in \{1,\dots, \ell(\bm{c})\}$, and subsequently define $\bm{x} \lhd \bm{c} = \bm{x}_{\ell(\bm{c})}$, where the application operation, $\lhd$, in \eqref{eq:recursive-application-composite} is the application map defined in Definition~\ref{defn:actions}. Then, $\lhd :\mathscr{T}(X) \times \mathscr{C}(X) \to \mathscr{T}(X)$ is continuous.
\end{thm}

environments.statement:
\label{thm:composite-application-continuous}
    Let $(X,d)$ be a metric space, $(\mathscr{T}(X), \mathscr{d}_H)$ be the associated tuple space endowed with the tuple Hausdorff distance, and let $(\mathscr{C}(X), \Delta_H)$ be the space of composite actions with the metric as defined in Theorem~\ref{thm:composite-action-metric}. Let the extended application map $\lhd :\mathscr{T}(X) \times \mathscr{C}(X)\to\mathscr{T}(X)$ be defined by $\bm{x} \lhd \bm{c} = \bm{x}$ if $\bm{c} = \bm{e}$, otherwise define $\bm{x}_0 = \bm{x}$ and define recursively
    \begin{align}\label{eq:recursive-application-composite}
        \bm{x}_i = \bm{x}_{i-1} \lhd \bm{c}(i)
    \end{align}
    for $i \in \{1,\dots, \ell(\bm{c})\}$, and subsequently define $\bm{x} \lhd \bm{c} = \bm{x}_{\ell(\bm{c})}$, where the application operation, $\lhd$, in \eqref{eq:recursive-application-composite} is the application map defined in Definition~\ref{defn:actions}. Then, $\lhd :\mathscr{T}(X) \times \mathscr{C}(X) \to \mathscr{T}(X)$ is continuous.

proof.rawEnvironment:
\begin{proof}
    Let $\varepsilon>0$ and fix $(\bm{x}_0,\eta_0)\in \mathscr{T}(X)\times\mathscr{F}(\mathbb{N})$. Choose $0<\delta<\min(1,\varepsilon)$. If
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x},\bm{x}_0),d_H(\eta,\eta_0))<\delta,
    \end{align*}
    then $\ell(\bm{x})=\ell(\bm{x}_0)$ by the \hyperref[thm:the-standard-machinery]{standard machinery}, and $\eta=\eta_0$ because $\mathbb{N}$ with the Euclidean distance is uniformly discrete, so that $(\mathscr{F}(\mathbb{N}),d_H)$ is uniformly discrete with the same bound by Proposition~\ref{prop:finite-hausdorff-uniformly-discrete}. Set
    \begin{align*}
        I=\eta_0\cap \mathrm{domain}(\bm{x}_0).
    \end{align*}
    If $I=\emptyset$, then both restricted tuples are empty. Otherwise, write $I=\{i_1, \dots, i_k\}$ for some $k \in \mathbb{N}$, listed in increasing order, $i_1 < \dots < i_k$. The reindexed tuples are
    \begin{align*}
        \bm{x}[\eta](r)=\bm{x}(i_r),
        \qquad
        \bm{x}_0[\eta_0](r)=\bm{x}_0(i_r),
        \qquad r=1,\dots,k,
    \end{align*}
    and, since on tuples of equal length at distance less than $1$ the tuple Hausdorff metric reduces to the maximum coordinate distance by the \hyperref[thm:the-standard-machinery]{standard machinery} and we obtain
    \begin{align*}
        \mathscr{d}_H(\bm{x}[\eta],\bm{x}_0[\eta_0])
        \leq
        \max_{i\in\mathrm{domain}(\bm{x}_0)}d(\bm{x}(i),\bm{x}_0(i))
        <\delta<\varepsilon.
    \end{align*}
    Thus, the reindexing map is continuous.
\end{proof}

