\begin{prop}\label{prop:composition-continuous}
    Let $(X,d)$ be a metric space, $(\mathscr{T}(X),\mathscr{d}_H)$ the tuple Hausdorff space, and let $(\mathscr{F}(\mathbb{N}), d_H)$ be the set of finite subsets of $\mathbb{N}$ endowed with the Hausdorff distance induced by the Euclidean distance. Then the mapping from $\mathscr{T}(X) \times \mathscr{F}(\mathbb{N})$ to $\mathscr{T}(X)$ defined by
    \begin{align*}
        (\bm{x}, \eta) \mapsto \bm{x}[\eta]
    \end{align*}
    is continuous whenever $\mathscr{T}(X) \times \mathscr{F}(\mathbb{N})$ is endowed with the product topology. 
\end{prop}

environments.statement:
\label{prop:composition-continuous}
    Let $(X,d)$ be a metric space, $(\mathscr{T}(X),\mathscr{d}_H)$ the tuple Hausdorff space, and let $(\mathscr{F}(\mathbb{N}), d_H)$ be the set of finite subsets of $\mathbb{N}$ endowed with the Hausdorff distance induced by the Euclidean distance. Then the mapping from $\mathscr{T}(X) \times \mathscr{F}(\mathbb{N})$ to $\mathscr{T}(X)$ defined by
    \begin{align*}
        (\bm{x}, \eta) \mapsto \bm{x}[\eta]
    \end{align*}
    is continuous whenever $\mathscr{T}(X) \times \mathscr{F}(\mathbb{N})$ is endowed with the product topology.

proof.rawEnvironment:
\begin{proof}
The map $\bm{x}\mapsto(\bm{x},F(\bm{x}))$ is measurable. Since $\mathscr{F}(\mathbb{N})$ is countable and discrete, every open subset of the product is a countable union $\bigcup_\eta U_\eta\times\{\eta\}$, which makes the Borel $\sigma$-algebra of the product equal to the product of the two Borel $\sigma$-algebras. Composing it with the continuous map $(\bm{x},\eta)\mapsto\bm{x}[\eta]$ proves the corollary.
\end{proof}

