\begin{cor}\label{cor:filter}
    Let $(X,d)$ be a metric space, $(\mathscr{T}(X),\mathscr{d}_H)$ the tuple Hausdorff space, and let $(\mathscr{F}(\mathbb{N}), d_H)$ be the set of finite subsets of $\mathbb{N}$ endowed with the Hausdorff distance induced by the Euclidean distance. Let $F:\mathscr{T}(X) \to \mathscr{F}(\mathbb{N})$ be a $\mathcal{B}(\mathscr{T}(X))/\mathcal{B}(\mathscr{F}(\mathbb{N}))$-measurable function. Then the mapping from $\mathscr{T}(X)$ to $\mathscr{T}(X)$ defined by
    \begin{align}
        \bm{x} \mapsto \bm{x}[F(\bm{x})]
    \end{align}
    is $\mathcal{B}(\mathscr{T}(X)) / \mathcal{B}(\mathscr{T}(X))$-measurable.
\end{cor}

environments.statement:
\label{cor:filter}
    Let $(X,d)$ be a metric space, $(\mathscr{T}(X),\mathscr{d}_H)$ the tuple Hausdorff space, and let $(\mathscr{F}(\mathbb{N}), d_H)$ be the set of finite subsets of $\mathbb{N}$ endowed with the Hausdorff distance induced by the Euclidean distance. Let $F:\mathscr{T}(X) \to \mathscr{F}(\mathbb{N})$ be a $\mathcal{B}(\mathscr{T}(X))/\mathcal{B}(\mathscr{F}(\mathbb{N}))$-measurable function. Then the mapping from $\mathscr{T}(X)$ to $\mathscr{T}(X)$ defined by
    \begin{align}
        \bm{x} \mapsto \bm{x}[F(\bm{x})]
    \end{align}
    is $\mathcal{B}(\mathscr{T}(X)) / \mathcal{B}(\mathscr{T}(X))$-measurable.

proof.rawEnvironment:
\begin{proof}
The tuple space is homeomorphic to $\bigsqcup_{n\in\mathbb{N}_0}X^n$, so Theorem~\ref{thm:pasting-lemma-measurable} reduces the proof to a single fixed-length layer. We equip $X^n$ with the Borel $\sigma$-algebra of its maximum-metric topology. For $n=0$, the map is constant with value $\emptyset$. Fix $n\geq1$ for the remaining argument.

    Since $\mathscr{F}(\mathbb{N})$ is countable and uniformly discrete under the Hausdorff distance induced by the Euclidean metric, its Borel $\sigma$-algebra is the power set. It therefore suffices to show that the preimage of each singleton is measurable. Fix $\eta\in\mathscr{F}(\mathbb{N})$. If $\eta\nsubseteq\{1,\dots,n\}$, then $\chi^{-1}(\{\eta\})\cap X^n$ is empty. If $\eta\subseteq\{1,\dots,n\}$, then
    \begin{align*}
        \chi^{-1}(\{\eta\})\cap X^n
        &= \bigcap_{i\in \eta} \{\bm{x} \in X^n \mid \chi_i(\bm{x}(i))=1\}\\
        &\quad\cap \bigcap_{i\in \{1,\dots,n\}\setminus \eta}\{\bm{x} \in X^n \mid \chi_i(\bm{x}(i)) = 0\},
    \end{align*}
    which is a finite intersection of measurable sets because each coordinate map and each $\chi_i$ is measurable.
\end{proof}

