\begin{defn}[Tuple Projections and Decomposition]\label{defn:tuple-projection}\index{tuple projections}
    Let $(X_\alpha)_{\alpha\in A}$ be a family of non-empty sets, $X = \prod_{\alpha\in A} X_\alpha$ and let $P_\alpha:X \to X_\alpha$ be the projection defined by $P_\alpha x = x_\alpha$ for $x = (x_\alpha)_{\alpha \in A} \in X$. The mappings 
    \begin{align*}
        \bm{P}_{\alpha} &: \mathscr{T}(X) \to \mathscr{T}(X_\alpha)\\
        \bm{x} &\mapsto P_\alpha \circ \bm{x},
    \end{align*}
    are called the tuple projections. Moreover, the mapping $\bm{P}:\mathscr{T}(X) \to \prod_{\alpha\in A}\mathscr{T}(X_\alpha)$ defined by 
    \begin{align*}
        \bm{P}\bm{x} =  (\bm{P}_\alpha\bm{x})_{\alpha \in A}
    \end{align*}
    is called the tuple decomposition.
\end{defn}

environments.statement:
\label{defn:tuple-projection}\index{tuple projections}
    Let $(X_\alpha)_{\alpha\in A}$ be a family of non-empty sets, $X = \prod_{\alpha\in A} X_\alpha$ and let $P_\alpha:X \to X_\alpha$ be the projection defined by $P_\alpha x = x_\alpha$ for $x = (x_\alpha)_{\alpha \in A} \in X$. The mappings 
    \begin{align*}
        \bm{P}_{\alpha} &: \mathscr{T}(X) \to \mathscr{T}(X_\alpha)\\
        \bm{x} &\mapsto P_\alpha \circ \bm{x},
    \end{align*}
    are called the tuple projections. Moreover, the mapping $\bm{P}:\mathscr{T}(X) \to \prod_{\alpha\in A}\mathscr{T}(X_\alpha)$ defined by 
    \begin{align*}
        \bm{P}\bm{x} =  (\bm{P}_\alpha\bm{x})_{\alpha \in A}
    \end{align*}
    is called the tuple decomposition.

environments.rawEnvironment:
\begin{rem}\label{rem:tuple-projection-operator-notation}
    Note that the tuple projections and tuple decomposition are denoted similarly to \emph{operators}, with the parentheses around the argument omitted. The tuple decomposition can also be seen as a mapping
    \begin{align*}
        \bm{P}\bm{x} =  \alpha \mapsto \bm{P}_\alpha\bm{x};
    \end{align*}
    a family indexed by $A$ and a function on $A$ are the same object, so we will use whichever representation is most natural in each application.
\end{rem}

environments.statement:
\label{rem:tuple-projection-operator-notation}
    Note that the tuple projections and tuple decomposition are denoted similarly to \emph{operators}, with the parentheses around the argument omitted. The tuple decomposition can also be seen as a mapping
    \begin{align*}
        \bm{P}\bm{x} =  \alpha \mapsto \bm{P}_\alpha\bm{x};
    \end{align*}
    a family indexed by $A$ and a function on $A$ are the same object, so we will use whichever representation is most natural in each application.

proof.rawEnvironment:
\begin{proof}
    First, we must show that for every $\varepsilon > 0$ and $\bm{x}_0 \in \mathscr{T}(X)$ there exists a $\delta >0$ such that 
    \begin{align*}
        \mathscr{d}_H(\bm{x},\bm{x}_0) < \delta \implies \mathscr{d}_{H,\alpha}(\bm{P}_\alpha\bm{x}, \bm{P}_\alpha\bm{x}_0) < \varepsilon,
    \end{align*}
    and since the graph map $(i,x)\mapsto(i,P_\alpha x)$ is $1$-Lipschitz for the maximum product metric, we have
    \begin{align*}
        \mathscr{d}_{H,\alpha}(\bm{P}_\alpha\bm{x}, \bm{P}_\alpha\bm{x}_0) \leq \mathscr{d}_H(\bm{x},\bm{x}_0),
    \end{align*}
    and so for a given $\varepsilon > 0$ one can choose $\delta = \varepsilon$. Note that the second assertion follows trivially from the first, as one uses the maximum metric to generate the product topology.

    It remains to show that $\bm{P}$ is injective. Let $\bm{x}, \bm{x}^\prime \in \mathscr{T}(X)$ and assume that 
    \begin{align*}
        \bm{P}\bm{x} = \bm{P}\bm{x}^\prime.
    \end{align*}
    Then $\bm{P}_\alpha \bm{x} = \bm{P}_\alpha \bm{x}^\prime$ for every $\alpha \in A$. Since $A$ is non-empty, fix $\alpha_0 \in A$. The equality $\bm{P}_{\alpha_0}\bm{x} = \bm{P}_{\alpha_0}\bm{x}^\prime$ implies that 
    \begin{align*}
        \mathrm{domain}(\bm{x}) = \mathrm{domain}(\bm{P}_{\alpha_0}\bm{x}) = \mathrm{domain}(\bm{P}_{\alpha_0}\bm{x}^\prime) = \mathrm{domain}(\bm{x}^\prime).
    \end{align*}
    Now let $i \in \mathrm{domain}(\bm{x}) = \mathrm{domain}(\bm{x}^\prime)$. Since $\bm{P}_\alpha \bm{x}(i) = \bm{P}_\alpha \bm{x}^\prime(i)$ for every $\alpha \in A$, we have 
    \begin{align*}
        P_\alpha(\bm{x}(i)) = P_\alpha(\bm{x}^\prime(i)) \quad \forall \alpha \in A.
    \end{align*}
    Hence $\bm{x}(i)=\bm{x}^\prime(i)$ in the Cartesian product $X=\prod_{\alpha \in A} X_\alpha$. As this holds for every index $i$, it follows that $\bm{x}=\bm{x}^\prime$. 
\end{proof}

