\begin{lem}\label{lem:tuple-space-measurable-2}
Let $k\in\mathbb{N}$ and $n_1,\dots,n_k \in \mathbb{N}_0$, let $L=\mathbb{R}^{n_1}\times\dots\times\mathbb{R}^{n_k}$ carry its usual topology, where $\mathbb{R}^0=\{\bm{e}\}$, and endow $\mathscr{T}(\mathbb{R})^k$ with the product of the tuple Hausdorff distances. Then for any Borel measurable\index{measurable sorting} set $A \in \mathcal{B}(L)$ one has $A \in \mathcal{B}(\mathscr{T}(\mathbb{R})^k)$. Conversely, if $A \in \mathcal{B}(\mathscr{T}(\mathbb{R})^k)$ then $A \cap L \in \mathcal{B}(L)$.
\end{lem}

