\begin{prop}\label{prop:minimal-sorting-measurable}
    For $\preceq \in \{\leq, \geq\}$, where $\{\leq, \geq\}$ are the usual order relations on $\mathbb{R}$, the $\preceq$-minimal permutation map is a Borel measurable map between $\mathscr{T}(\mathbb{R})$ and the set of finite permutations, $\mathscr{P}$, where both are endowed with the tuple Hausdorff distance induced by the Euclidean distance. 
\end{prop}

proof.rawEnvironment:
\begin{proof}
    On the empty tuple, $\bm{\Sigma}$ is the unique map from the singleton empty tuple to itself and is continuous. Note that for each $n \in \mathbb{N}$ the linear transformation $S_n:\mathbb{R}^n \to \mathbb{R}^n$ defined by the matrix
    \begin{align*}
        (S_n)_{i,j} = \begin{cases}
            1 & j \leq i\\ 
            0 & j > i
        \end{cases},
    \end{align*}
    is continuous. Since $\bm{\Sigma} \restriction_{[0,\infty)^n} =\allowbreak S_n \restriction_{[0,\infty)^n}$, by the \hyperref[thm:the-standard-machinery]{standard machinery}, the result follows.
\end{proof}

