proof.rawEnvironment:
\begin{proof}
    We must show that the maximum $\max_{p \in \mathbb{R}} \min(S(p), D(p))$ exists and is equal to $\mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b))$. First, note that because $\mathrm{domain}(\bm{p}^s)$ and $\mathrm{domain}(\bm{p}^b)$ are finite sets, the functions $p \mapsto S(p)$ and $p \mapsto D(p)$, and therefore $p \mapsto \min(S(p), D(p))$, take only finitely many values as $p$ ranges over $\mathbb{R}$. Consequently, $\max_{p \in \mathbb{R}} \min(S(p), D(p))$ exists.

    We first show that $\mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b)) \leq\allowbreak \max_{p \in \mathbb{R}} \min(S(p), D(p))$. If $\mathfrak{I}(\bm{p}^s, \bm{p}^b) = \emptyset$, then $\mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b)) = 0 \leq\allowbreak \max_{p \in \mathbb{R}} \min(S(p), D(p))$ because $S(p) \geq 0$ and $D(p) \geq 0$ for all $p \in \mathbb{R}$. Suppose therefore that $\mathfrak{I}(\bm{p}^s, \bm{p}^b) \neq \emptyset$, and let $(i, j) \in \mathfrak{I}(\bm{p}^s, \bm{p}^b)$ be arbitrary. By \eqref{eq:index-mapping}, we have $\bm{p}^s(i) \leq \bm{p}^b(j)$, so we may choose a price $p \in [\bm{p}^s(i), \bm{p}^b(j)]$. Since $\bm{p}^s \in \mathscr{S}(\mathbb{R}, \leq)$ is sorted in ascending order and $\bm{p}^b \in \mathscr{S}(\mathbb{R}, \geq)$ is sorted in descending order, every $r \in \{1, \dots, i\}$ satisfies $\bm{p}^s(r) \leq \bm{p}^s(i) \leq p$, and every $r \in \{1, \dots, j\}$ satisfies $\bm{p}^b(r) \geq \bm{p}^b(j) \geq p$. Because all order quantities are non-negative, it follows that
    \begin{align*}
        S(p) \geq \sum_{r=1}^{i} \bm{q}^s(r) = \bm{Q}^s(i)
        \qquad \text{and} \qquad
        D(p) \geq \sum_{r=1}^{j} \bm{q}^b(r) = \bm{Q}^b(j),
    \end{align*}
    and hence
    \begin{align*}
        \min(\bm{Q}^s(i), \bm{Q}^b(j)) \leq \min(S(p), D(p)) \leq \max_{p^\prime \in \mathbb{R}} \min(S(p^\prime), D(p^\prime)).
    \end{align*}
    Taking the maximum over $(i, j) \in \mathfrak{I}(\bm{p}^s, \bm{p}^b)$ yields $\mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b)) \leq\allowbreak \max_{p \in \mathbb{R}} \min(S(p), D(p))$.

    For the reverse inequality, fix $p \in \mathbb{R}$. If $\min(S(p), D(p)) = 0$, then $\min(S(p), D(p)) \leq\allowbreak \mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b))$ holds immediately. Suppose therefore that $\min(S(p), D(p)) > 0$. Then both $\{r \in \mathrm{domain}(\bm{p}^s) \mid \bm{p}^s(r) \leq p\}$ and $\{r \in \mathrm{domain}(\bm{p}^b) \mid\allowbreak \bm{p}^b(r) \geq p\}$ are non-empty finite sets; let $i$ and $j$ denote their respective maximum elements. Because $\bm{p}^s$ is non-decreasing and $\bm{p}^b$ is non-increasing, the index sets of qualifying orders are $\{1, \dots, i\}$ and $\{1, \dots, j\}$, which implies that
    \begin{align*}
        S(p) = \sum_{r=1}^{i} \bm{q}^s(r) = \bm{Q}^s(i)
        \qquad \text{and} \qquad
        D(p) = \sum_{r=1}^{j} \bm{q}^b(r) = \bm{Q}^b(j).
    \end{align*}
    Moreover, by construction we have $\bm{p}^s(i) \leq p \leq \bm{p}^b(j)$, so $(i, j) \in \mathfrak{I}(\bm{p}^s, \bm{p}^b)$, and consequently
    \begin{align*}
        \min\bigl(S(p), D(p)\bigr) = \min\bigl(\bm{Q}^s(i), \bm{Q}^b(j)\bigr) \leq \mathscr{Q}\bigl((\bm{Q}^s, \bm{p}^s), (\bm{Q}^b, \bm{p}^b)\bigr).
    \end{align*}
    Taking the maximum over $p \in \mathbb{R}$ establishes the reverse inequality, as desired.
\end{proof}

proof.text:
We must show that the maximum $\max_{p \in \mathbb{R}} \min(S(p), D(p))$ exists and is equal to $\mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b))$. First, note that because $\mathrm{domain}(\bm{p}^s)$ and $\mathrm{domain}(\bm{p}^b)$ are finite sets, the functions $p \mapsto S(p)$ and $p \mapsto D(p)$, and therefore $p \mapsto \min(S(p), D(p))$, take only finitely many values as $p$ ranges over $\mathbb{R}$. Consequently, $\max_{p \in \mathbb{R}} \min(S(p), D(p))$ exists.

    We first show that $\mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b)) \leq\allowbreak \max_{p \in \mathbb{R}} \min(S(p), D(p))$. If $\mathfrak{I}(\bm{p}^s, \bm{p}^b) = \emptyset$, then $\mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b)) = 0 \leq\allowbreak \max_{p \in \mathbb{R}} \min(S(p), D(p))$ because $S(p) \geq 0$ and $D(p) \geq 0$ for all $p \in \mathbb{R}$. Suppose therefore that $\mathfrak{I}(\bm{p}^s, \bm{p}^b) \neq \emptyset$, and let $(i, j) \in \mathfrak{I}(\bm{p}^s, \bm{p}^b)$ be arbitrary. By \eqref{eq:index-mapping}, we have $\bm{p}^s(i) \leq \bm{p}^b(j)$, so we may choose a price $p \in [\bm{p}^s(i), \bm{p}^b(j)]$. Since $\bm{p}^s \in \mathscr{S}(\mathbb{R}, \leq)$ is sorted in ascending order and $\bm{p}^b \in \mathscr{S}(\mathbb{R}, \geq)$ is sorted in descending order, every $r \in \{1, \dots, i\}$ satisfies $\bm{p}^s(r) \leq \bm{p}^s(i) \leq p$, and every $r \in \{1, \dots, j\}$ satisfies $\bm{p}^b(r) \geq \bm{p}^b(j) \geq p$. Because all order quantities are non-negative, it follows that
    \begin{align*}
        S(p) \geq \sum_{r=1}^{i} \bm{q}^s(r) = \bm{Q}^s(i)
        \qquad \text{and} \qquad
        D(p) \geq \sum_{r=1}^{j} \bm{q}^b(r) = \bm{Q}^b(j),
    \end{align*}
    and hence
    \begin{align*}
        \min(\bm{Q}^s(i), \bm{Q}^b(j)) \leq \min(S(p), D(p)) \leq \max_{p^\prime \in \mathbb{R}} \min(S(p^\prime), D(p^\prime)).
    \end{align*}
    Taking the maximum over $(i, j) \in \mathfrak{I}(\bm{p}^s, \bm{p}^b)$ yields $\mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b)) \leq\allowbreak \max_{p \in \mathbb{R}} \min(S(p), D(p))$.

    For the reverse inequality, fix $p \in \mathbb{R}$. If $\min(S(p), D(p)) = 0$, then $\min(S(p), D(p)) \leq\allowbreak \mathscr{Q}((\bm{Q}^s, \bm{p}^s),\allowbreak (\bm{Q}^b, \bm{p}^b))$ holds immediately. Suppose therefore that $\min(S(p), D(p)) > 0$. Then both $\{r \in \mathrm{domain}(\bm{p}^s) \mid \bm{p}^s(r) \leq p\}$ and $\{r \in \mathrm{domain}(\bm{p}^b) \mid\allowbreak \bm{p}^b(r) \geq p\}$ are non-empty finite sets; let $i$ and $j$ denote their respective maximum elements. Because $\bm{p}^s$ is non-decreasing and $\bm{p}^b$ is non-increasing, the index sets of qualifying orders are $\{1, \dots, i\}$ and $\{1, \dots, j\}$, which implies that
    \begin{align*}
        S(p) = \sum_{r=1}^{i} \bm{q}^s(r) = \bm{Q}^s(i)
        \qquad \text{and} \qquad
        D(p) = \sum_{r=1}^{j} \bm{q}^b(r) = \bm{Q}^b(j).
    \end{align*}
    Moreover, by construction we have $\bm{p}^s(i) \leq p \leq \bm{p}^b(j)$, so $(i, j) \in \mathfrak{I}(\bm{p}^s, \bm{p}^b)$, and consequently
    \begin{align*}
        \min\bigl(S(p), D(p)\bigr) = \min\bigl(\bm{Q}^s(i), \bm{Q}^b(j)\bigr) \leq \mathscr{Q}\bigl((\bm{Q}^s, \bm{p}^s), (\bm{Q}^b, \bm{p}^b)\bigr).
    \end{align*}
    Taking the maximum over $p \in \mathbb{R}$ establishes the reverse inequality, as desired.

