\begin{thm}\label{thm:index-measurable}
    The mapping $\mathfrak{I}:\mathscr{S}(\mathbb{R}, \leq) \times \mathscr{S}(\mathbb{R}, \geq) \to \mathscr{F}(\mathbb{N}^2)$ defined by
    \begin{align*}
        \mathfrak{I}(\bm{p}^s, \bm{p}^b) = \{(i,j) \in \mathrm{domain}(\bm{p}^s) \times \mathrm{domain}(\bm{p}^b)\mid \bm{p}^s(i) \leq \bm{p}^b(j)\}
    \end{align*}
    is measurable whenever $\mathscr{S}(\mathbb{R}, \leq) \times \mathscr{S}(\mathbb{R}, \geq)$ is endowed with the Borel $\sigma$-algebra induced by the product of the tuple Hausdorff distances, and $\mathscr{F}(\mathbb{N}^2)$ is endowed with its Borel $\sigma$-algebra induced by the Hausdorff distance.
\end{thm}

