\begin{thm}\label{thm:equilibrium-quantity-measurable}
    Let $\{\leq, \geq\}$ denote the usual order relations on $\mathbb{R}$, and 
    \begin{align*}
        \mathfrak{C}(R) = \{(\bm{x},\bm{y}) \in \mathscr{S}([0,\infty), \leq) \times \mathscr{S}(\mathbb{R}, R) \mid \ell(\bm{x}) = \ell(\bm{y})\} 
    \end{align*}
    for $R \in \{\leq, \geq\}$. Moreover, endow $\mathfrak{C}(R)$ with the product of the tuple Hausdorff metrics, and let $\mathfrak{I}(\bm{p},\bm{p}^\prime) = \{(i,j) \in \mathrm{domain}(\bm{p}) \times \mathrm{domain}(\bm{p}^\prime)\mid \bm{p}(i) \leq \bm{p}^\prime(j)\}$. Then the function $\mathscr{Q}:\mathfrak{C}(\leq)\times \mathfrak{C}(\geq) \to [0,\infty)$ defined by 
    \begin{align*}
        \mathscr{Q}((\bm{Q},\bm{p}), (\bm{Q}^\prime, \bm{p}^\prime)) =\begin{cases}
            0 & \mathfrak{I}(\bm{p},\bm{p}^\prime) =\emptyset\\ 
            \max \{\min(\bm{Q}(i),\bm{Q}^\prime(j)) \mid (i,j) \in \mathfrak{I}(\bm{p},\bm{p}^\prime)\} & \mathfrak{I}(\bm{p},\bm{p}^\prime) \neq \emptyset,
        \end{cases}
    \end{align*}
    is measurable.
\end{thm}

environments.statement:
\label{thm:equilibrium-quantity-measurable}
    Let $\{\leq, \geq\}$ denote the usual order relations on $\mathbb{R}$, and 
    \begin{align*}
        \mathfrak{C}(R) = \{(\bm{x},\bm{y}) \in \mathscr{S}([0,\infty), \leq) \times \mathscr{S}(\mathbb{R}, R) \mid \ell(\bm{x}) = \ell(\bm{y})\} 
    \end{align*}
    for $R \in \{\leq, \geq\}$. Moreover, endow $\mathfrak{C}(R)$ with the product of the tuple Hausdorff metrics, and let $\mathfrak{I}(\bm{p},\bm{p}^\prime) = \{(i,j) \in \mathrm{domain}(\bm{p}) \times \mathrm{domain}(\bm{p}^\prime)\mid \bm{p}(i) \leq \bm{p}^\prime(j)\}$. Then the function $\mathscr{Q}:\mathfrak{C}(\leq)\times \mathfrak{C}(\geq) \to [0,\infty)$ defined by 
    \begin{align*}
        \mathscr{Q}((\bm{Q},\bm{p}), (\bm{Q}^\prime, \bm{p}^\prime)) =\begin{cases}
            0 & \mathfrak{I}(\bm{p},\bm{p}^\prime) =\emptyset\\ 
            \max \{\min(\bm{Q}(i),\bm{Q}^\prime(j)) \mid (i,j) \in \mathfrak{I}(\bm{p},\bm{p}^\prime)\} & \mathfrak{I}(\bm{p},\bm{p}^\prime) \neq \emptyset,
        \end{cases}
    \end{align*}
    is measurable.

proof.rawEnvironment:
\begin{proof}
    To prove (i), we must show that for every $z=((\bm{Q},\bm{p}),(\bm{Q}^\prime,\bm{p}^\prime)) \in \mathfrak{C}(\leq) \times \mathfrak{C}(\geq)$ and every sequence $(z_k)_{k\in\mathbb{N}}$ in $\mathfrak{C}(\leq) \times \mathfrak{C}(\geq)$ converging to $z$, it holds that $\limsup_{k\to\infty} \mathscr{Q}(z_k) \leq \mathscr{Q}(z)$. Let $z_k=((\bm{Q}_k,\bm{p}_k),(\bm{Q}^\prime_k,\bm{p}^\prime_k))$, $k\in\mathbb{N}$, converge to $z$. By the \hyperref[thm:the-standard-machinery]{standard machinery}, the fixed-length layers are clopen and carry the usual Euclidean topology, so there exists $K\in\mathbb{N}$ such that, for all $k\geq K$, the tuples $\bm{p}_k$ and $\bm{p}^\prime_k$ have the constant lengths $n=\ell(\bm{p})$ and $m=\ell(\bm{p}^\prime)$, and the coordinates of $\bm{Q}_k$, $\bm{p}_k$, $\bm{Q}^\prime_k$, and $\bm{p}^\prime_k$ converge pointwise to those of $\bm{Q}$, $\bm{p}$, $\bm{Q}^\prime$, and $\bm{p}^\prime$. If a pair $(i,j)\in\{1,\dots,n\}\times\{1,\dots,m\}$ lies outside $\mathfrak{I}(\bm{p},\bm{p}^\prime)$, then $\bm{p}(i)>\bm{p}^\prime(j)$, and hence $\bm{p}_k(i)>\bm{p}^\prime_k(j)$ for all sufficiently large $k$. Because $\{1,\dots,n\}\times\{1,\dots,m\}$ is finite, we may enlarge $K$ so that
    \begin{align*}
        \mathfrak{I}(\bm{p}_k,\bm{p}^\prime_k)\subseteq\mathfrak{I}(\bm{p},\bm{p}^\prime)
        \qquad\text{for all } k\geq K.
    \end{align*}
    For each $k\geq K$, define
    \begin{align*}
        g_k = \begin{cases}
            0, & \mathfrak{I}(\bm{p},\bm{p}^\prime) = \emptyset,\\
            \max\bigl\{\min(\bm{Q}_k(i),\bm{Q}^\prime_k(j))\bigm| (i,j)\in\mathfrak{I}(\bm{p},\bm{p}^\prime)\bigr\}, & \mathfrak{I}(\bm{p},\bm{p}^\prime) \neq \emptyset.
        \end{cases}
    \end{align*}
    Since all cumulative quantities are non-negative, the inclusion $\mathfrak{I}(\bm{p}_k,\bm{p}^\prime_k)\subseteq\mathfrak{I}(\bm{p},\bm{p}^\prime)$ implies that $\mathscr{Q}(z_k)\leq g_k$ for all $k \geq K$. Moreover, because the maximum and minimum over a fixed finite index set are continuous, we have $\lim_{k\to\infty} g_k = \mathscr{Q}(z)$. Consequently,
    \begin{align*}
        \limsup_{k\to\infty}\mathscr{Q}(z_k) \leq \lim_{k\to\infty} g_k = \mathscr{Q}(z),
    \end{align*}
    which proves (i).

    To prove (ii), suppose in addition that $\bm{p}(i)\neq\bm{p}^\prime(j)$ for all $(i,j)\in\mathrm{domain}(\bm{p})\times\mathrm{domain}(\bm{p}^\prime)$. Then every $(i,j)\in\mathfrak{I}(\bm{p},\bm{p}^\prime)$ satisfies the strict inequality $\bm{p}(i)<\bm{p}^\prime(j)$, and hence $\bm{p}_k(i)<\bm{p}^\prime_k(j)$ for all sufficiently large $k$. Enlarging $K$ if necessary, we obtain $\mathfrak{I}(\bm{p}_k,\bm{p}^\prime_k) = \mathfrak{I}(\bm{p},\bm{p}^\prime)$ for all $k \geq K$, which yields
    \begin{align*}
        \lim_{k\to\infty} \mathscr{Q}(z_k) = \lim_{k\to\infty} g_k = \mathscr{Q}(z),
    \end{align*}
    establishing continuity at $z$.

    Finally, to prove (iii), let $z=((\bm{Q},\bm{p}),(\bm{Q}^\prime,\bm{p}^\prime))$ be the point specified in (iii), and for each $k \in \mathbb{N}$ define $z_k=((\bm{Q},\bm{p}_k),(\bm{Q}^\prime,\bm{p}^\prime))$, where $\ell(\bm{p}_k)=1$ and $\bm{p}_k(1)=1/k$. Then $z_k \to z$ as $k \to \infty$, but $\bm{p}_k(1) = 1/k > 0 = \bm{p}^\prime(1)$ for every $k \in \mathbb{N}$. Thus $\mathfrak{I}(\bm{p}_k,\bm{p}^\prime)=\emptyset$ and $\mathscr{Q}(z_k)=0$ for all $k \in \mathbb{N}$, whereas $\mathfrak{I}(\bm{p},\bm{p}^\prime)=\{(1,1)\}$ and $\mathscr{Q}(z)=\min(1,1)=1$, proving that $\mathscr{Q}$ is discontinuous at $z$, as desired.
\end{proof}

