\begin{cor}[Measurable Volume Composition]\label{cor:state-compatible-volume-measurable}
Let $O=\bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}}\mathbb{R}\times[0,\infty)$ carry the disjoint-union metric induced by the maximum product metric on $\mathbb{R}\times[0,\infty)$, and equip $\mathscr{T}(O)$ with its tuple Hausdorff Borel $\sigma$-algebra. For $\bm{m}\in\mathscr{T}(O)$, set
\begin{align*}
    \bm{b} &= \bm{\Pi}_{\mathrm{buy}}\bm{m},
    &\bm{s} &= \bm{\Pi}_{\mathrm{sell}}\bm{m},\\
    \bm{p}^{\bm{b}} &= \bm{P}_1\bm{b},
    &\bm{q}^{\bm{b}} &= \bm{P}_2\bm{b},\\
    \bm{p}^{\bm{s}} &= \bm{P}_1\bm{s},
    &\bm{q}^{\bm{s}} &= \bm{P}_2\bm{s},
\end{align*}
and define the sorted pairs by
\begin{align*}
    (\widehat{\bm{p}}^{\bm{b}},\widehat{\bm{q}}^{\bm{b}})
    &=\bigl(\bm{p}^{\bm{b}}[\pi^\geq(\bm{p}^{\bm{b}})],
    \bm{q}^{\bm{b}}[\pi^\geq(\bm{p}^{\bm{b}})]\bigr),\\
    (\widehat{\bm{p}}^{\bm{s}},\widehat{\bm{q}}^{\bm{s}})
    &=\bigl(\bm{p}^{\bm{s}}[\pi^\leq(\bm{p}^{\bm{s}})],
    \bm{q}^{\bm{s}}[\pi^\leq(\bm{p}^{\bm{s}})]\bigr),
\end{align*}
where $\pi^\preceq(\bm{e})$ is the unique empty permutation. Let
\begin{align*}
    \widehat{\bm{Q}}^{\bm{b}}=\bm{\Sigma}(\widehat{\bm{q}}^{\bm{b}}),
    \qquad
    \widehat{\bm{Q}}^{\bm{s}}=\bm{\Sigma}(\widehat{\bm{q}}^{\bm{s}}),
\end{align*}
and define
\begin{align*}
    \mathscr{Q}_{\mathrm{state}}(\bm{m})
    =\mathscr{Q}\bigl((\widehat{\bm{Q}}^{\bm{s}},\widehat{\bm{p}}^{\bm{s}}),
    (\widehat{\bm{Q}}^{\bm{b}},\widehat{\bm{p}}^{\bm{b}})\bigr).
\end{align*}
Then $\mathscr{Q}_{\mathrm{state}}:\mathscr{T}(O)\to[0,\infty)$ is Borel measurable.
\end{cor}

proof.rawEnvironment:
\begin{proof}
We must show that $\mathscr{P}_{\mathrm{state}}$ is well-defined on $\mathscr{T}(O)$ and that the paired map $(\mathscr{P}_{\mathrm{state}},\mathscr{Q}_{\mathrm{state}}) : \mathscr{T}(O) \to \mathbb{R} \times [0,\infty)$ is Borel measurable.

First, by Corollary~\ref{cor:state-compatible-volume-measurable}, the tuple maps $\widehat{\bm{p}}^{\bm{s}}$, $\widehat{\bm{p}}^{\bm{b}}$, $\widehat{\bm{Q}}^{\bm{s}}$, and $\widehat{\bm{Q}}^{\bm{b}}$, as well as the scalar functional $\mathscr{Q}_{\mathrm{state}}$, are Borel measurable. If $\mathscr{Q}_{\mathrm{state}}(\bm{m})>0$ and $(i^*,j^*) \in \mathfrak{I}(\widehat{\bm{p}}^{\bm{s}}, \widehat{\bm{p}}^{\bm{b}})$ attains the maximum in the definition of $\mathscr{Q}_{\mathrm{state}}(\bm{m})$, then $\mathscr{Q}_{\mathrm{state}}(\bm{m})=\min(\widehat{\bm{Q}}^{\bm{s}}(i^*),\widehat{\bm{Q}}^{\bm{b}}(j^*))$, so $\widehat{\bm{Q}}^{\bm{s}}(i^*)\geq\mathscr{Q}_{\mathrm{state}}(\bm{m})$ and $\widehat{\bm{Q}}^{\bm{b}}(j^*)\geq\mathscr{Q}_{\mathrm{state}}(\bm{m})$. Hence the minimal indices $\iota^{\bm{s}}(\bm{m})\leq i^*$ and $\iota^{\bm{b}}(\bm{m})\leq j^*$ exist in $\mathrm{domain}(\widehat{\bm{Q}}^{\bm{s}})$ and $\mathrm{domain}(\widehat{\bm{Q}}^{\bm{b}})$, respectively, and $\mathscr{P}_{\mathrm{state}}$ is well-defined. Moreover, since the sell prices are sorted in ascending order and the buy prices in descending order, we have
\begin{align*}
    \widehat{\bm{p}}^{\bm{s}}(\iota^{\bm{s}}(\bm{m}))\leq\widehat{\bm{p}}^{\bm{s}}(i^*)\leq\widehat{\bm{p}}^{\bm{b}}(j^*)\leq\widehat{\bm{p}}^{\bm{b}}(\iota^{\bm{b}}(\bm{m})),
\end{align*}
so the midpoint lies between two price-compatible marginal prices.

It remains to show that $\mathscr{P}_{\mathrm{state}} : \mathscr{T}(O) \to \mathbb{R}$ is Borel measurable. Set $A_0 = \{\bm{m} \in \mathscr{T}(O) \mid \mathscr{Q}_{\mathrm{state}}(\bm{m}) = 0\}$ and $A_+ = \{\bm{m} \in \mathscr{T}(O) \mid \mathscr{Q}_{\mathrm{state}}(\bm{m}) > 0\}$. Because $\mathscr{Q}_{\mathrm{state}}$ is Borel measurable by Corollary~\ref{cor:state-compatible-volume-measurable}, both $A_0$ and $A_+$ belong to $\mathcal{B}(\mathscr{T}(O))$. On $A_0$, the map $\mathscr{P}_{\mathrm{state}}$ is identically zero and hence measurable.

On $A_+$, we decompose the domain by the lengths of the separated sell and buy sub-tuples. For each pair $(n_s, n_b) \in \mathbb{N}^2$, define
\begin{align*}
    A_{n_s, n_b} = \bigl\{\bm{m} \in A_+ \;\big|\; \ell(\widehat{\bm{p}}^{\bm{s}}(\bm{m})) = n_s \;\land\; \ell(\widehat{\bm{p}}^{\bm{b}}(\bm{m})) = n_b\bigr\}.
\end{align*}
Since the fixed-length layers of $\mathscr{T}(\mathbb{R})$ are clopen by the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}) and the maps $\bm{m} \mapsto \widehat{\bm{p}}^{\bm{s}}(\bm{m})$ and $\bm{m} \mapsto \widehat{\bm{p}}^{\bm{b}}(\bm{m})$ are Borel measurable, the sets $(A_{n_s, n_b})_{(n_s, n_b) \in \mathbb{N}^2}$, together with $A_0$, form a countable measurable partition of $\mathscr{T}(O)$.

Fix $(n_s, n_b) \in \mathbb{N}^2$, and recall from the proof of Theorem~\ref{thm:equilibrium-quantity-measurable} the continuous coordinate evaluation maps $\mathrm{ev}_i : \mathscr{T}(\mathbb{R}) \to \mathbb{R}$, with $\mathrm{ev}_0 \equiv 0$. For each $i \in \{1, \dots, n_s\}$ and $j \in \{1, \dots, n_b\}$, define the subset
\begin{align*}
    B_{n_s, n_b}^{i, j} = \bigl\{\bm{m} \in A_{n_s, n_b} \;\big|\; \iota^{\bm{s}}(\bm{m}) = i \;\land\; \iota^{\bm{b}}(\bm{m}) = j\bigr\}.
\end{align*}
By the definition of the minimal index $\iota^a(\bm{m})$ and the monotonicity of $\widehat{\bm{Q}}^a(\bm{m})$, we have
\begin{align*}
    B_{n_s, n_b}^{i, j}
    &= \bigl\{\bm{m} \in A_{n_s, n_b} \;\big|\; \mathrm{ev}_{i-1}(\widehat{\bm{Q}}^{\bm{s}}(\bm{m})) < \mathscr{Q}_{\mathrm{state}}(\bm{m}) \leq \mathrm{ev}_i(\widehat{\bm{Q}}^{\bm{s}}(\bm{m}))\bigr\}\\
    &\quad \cap \bigl\{\bm{m} \in A_{n_s, n_b} \;\big|\; \mathrm{ev}_{j-1}(\widehat{\bm{Q}}^{\bm{b}}(\bm{m})) < \mathscr{Q}_{\mathrm{state}}(\bm{m}) \leq \mathrm{ev}_j(\widehat{\bm{Q}}^{\bm{b}}(\bm{m}))\bigr\},
\end{align*}
which is a finite intersection of Borel sets and therefore Borel measurable. Moreover, on each cell $B_{n_s, n_b}^{i, j}$, the map $\mathscr{P}_{\mathrm{state}}$ coincides with the fixed linear combination
\begin{align*}
    \bm{m} \mapsto \frac{1}{2}\Bigl(\mathrm{ev}_i\bigl(\widehat{\bm{p}}^{\bm{s}}(\bm{m})\bigr) + \mathrm{ev}_j\bigl(\widehat{\bm{p}}^{\bm{b}}(\bm{m})\bigr)\Bigr),
\end{align*}
which is a composition of Borel measurable maps and hence Borel measurable. Because the family $\{A_0\} \cup \{B_{n_s, n_b}^{i, j} \mid (n_s, n_b) \in \mathbb{N}^2, 1 \leq i \leq n_s, 1 \leq j \leq n_b\}$ is a countable measurable partition of $\mathscr{T}(O)$, Theorem~\ref{thm:measurable-partition} implies that $\mathscr{P}_{\mathrm{state}}$ is Borel measurable. Finally, since $\mathbb{R} \times [0, \infty)$ is separable, $\mathcal{B}(\mathbb{R} \times [0, \infty)) = \mathcal{B}(\mathbb{R}) \otimes \mathcal{B}([0, \infty))$, and componentwise measurability yields the joint Borel measurability of $(\mathscr{P}_{\mathrm{state}}, \mathscr{Q}_{\mathrm{state}})$, as desired.
\end{proof}

