\begin{cor}[Measurable Midpoint Price]\label{cor:state-midpoint-price-measurable}
Let $O=\bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}}\mathbb{R}\times[0,\infty)$ carry the disjoint-union metric induced by the maximum product metric on $\mathbb{R}\times[0,\infty)$, and equip $\mathscr{T}(O)$ with its tuple Hausdorff Borel $\sigma$-algebra. For $\bm{m}\in\mathscr{T}(O)$, let $\widehat{\bm{p}}^{\bm{s}}$, $\widehat{\bm{p}}^{\bm{b}}$, $\widehat{\bm{Q}}^{\bm{s}}$, $\widehat{\bm{Q}}^{\bm{b}}$, and $\mathscr{Q}_{\mathrm{state}}$ be the sorted price, cumulative-quantity, and maximum executable volume maps from Corollary~\ref{cor:state-compatible-volume-measurable}. For $a\in\{\bm{s},\bm{b}\}$ and $\mathscr{Q}_{\mathrm{state}}(\bm{m})>0$, let $\iota^a(\bm{m})$ be the least $i\in\mathrm{domain}(\widehat{\bm{Q}}^a)$ such that $\widehat{\bm{Q}}^a(i)\geq\mathscr{Q}_{\mathrm{state}}(\bm{m})$. Then the map $\mathscr{P}_{\mathrm{state}}:\mathscr{T}(O)\to\mathbb{R}$ given by
\begin{align*}
\mathscr{P}_{\mathrm{state}}(\bm{m})=
\begin{cases}
0,
&\mathscr{Q}_{\mathrm{state}}(\bm{m})=0,\\[2pt]
\dfrac{\widehat{\bm{p}}^{\bm{s}}(\iota^{\bm{s}}(\bm{m}))
+\widehat{\bm{p}}^{\bm{b}}(\iota^{\bm{b}}(\bm{m}))}{2},
&\mathscr{Q}_{\mathrm{state}}(\bm{m})>0,
\end{cases}
\end{align*}
is well-defined, and $(\mathscr{P}_{\mathrm{state}},\mathscr{Q}_{\mathrm{state}}):\mathscr{T}(O)\to\mathbb{R}\times[0,\infty)$ is Borel measurable for the product Borel $\sigma$-algebra.
\end{cor}

