\begin{lem}[Permutation Invariance]\label{lem:state-functionals-permutation-invariant}
    Let $O=\bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}}\mathbb{R}\times[0,\infty)$, and let $\mathscr{Q}_{\mathrm{state}}:\mathscr{T}(O)\to[0,\infty)$ and $\mathscr{P}_{\mathrm{state}}:\mathscr{T}(O)\to\mathbb{R}$ be as in Corollaries~\ref{cor:state-compatible-volume-measurable} and~\ref{cor:state-midpoint-price-measurable}. Then, for every $\bm{m}\in\mathscr{T}(O)$ and every bijection $\rho$ of $\mathrm{domain}(\bm{m})$,
    \begin{align*}
        \mathscr{Q}_{\mathrm{state}}(\bm{m}\circ\rho)=\mathscr{Q}_{\mathrm{state}}(\bm{m}),
        \qquad
        \mathscr{P}_{\mathrm{state}}(\bm{m}\circ\rho)=\mathscr{P}_{\mathrm{state}}(\bm{m}).
    \end{align*}
\end{lem}

