\begin{defn}[Weak Convergence; \citealp{daley2003introduction}]\label{defn:weak-convergence-finite-measures}\index{weak convergence}
    Let $(X,d)$ be a metric space and set $\Sigma=\mathcal{B}(X)$. Then, a sequence of finite measures $(\mu_n)_{n\in\mathbb{N}}$, with $\mu_n\in\mathcal{M}(X)$ for every $n$, is said to converge weakly to a measure $\mu \in \mathcal{M}(X)$ if $\int_X f \, \mathrm{d}\mu_n \to \int_X f \, \mathrm{d}\mu$ for all continuous and bounded functions $f \in C_b(X;\mathbb{R})$.
\end{defn}

\begin{thm}[Prokhorov Metric; \citealp{daley2003introduction,hirata2024formalization}]\label{thm:prokhorov-metric-weak-convergence-polish}
    Let $(X,d)$ be a complete and separable metric space, and let $\mathcal{M}(X)$ denote the family of finite measures on $(X,\mathcal{B}(X))$. Let $\rho:\mathcal{M}(X) \times \mathcal{M}(X) \to [0,\infty)$ be the function defined by 
    \begin{align*}
        \rho(\mu, \eta) = \inf \{ \varepsilon > 0 \mid \forall B \in \mathcal{B}(X): \mu(B) \leq \eta(B^\varepsilon) + \varepsilon \mathrm{~and~}\eta(B) \leq \mu(B^\varepsilon) + \varepsilon\}. 
    \end{align*}
    Then $(\mathcal{M}(X), \rho)$ is a metric space, and $\rho$ is called the Prokhorov metric. Moreover, 
    \begin{enumerate}[(i)]
        \item a sequence $(\mu_n)_{n\in\mathbb{N}} \subseteq \mathcal{M}(X)$ converges weakly to $\mu \in \mathcal{M}(X) $ if and only if $\lim_{n \to \infty}\rho(\mu_n,\mu) = 0$; 
        \item $(\mathcal{M}(X), \rho)$ is a complete and separable metric space; and  
        \item $(\mathcal{N}(X), \rho)$ is a complete and separable metric space.
    \end{enumerate}
\end{thm}

