\begin{thm}[Atomic Decomposition of Finite Integer-Valued Measures]\label{thm:sufficient-decomposition}
    Let $(X,\Sigma)$ be a standard Borel space. Then every $\xi \in \mathcal{N}(X)$ has the representation 
    \begin{align*}
        \xi = \sum_{k \leq \kappa} \beta_k \delta_{x_k},
    \end{align*}
    where $\kappa \in \mathbb{N}_0$ (the empty sum being $0$ when $\kappa=0$), $\beta_k\in\mathbb{N}$ for every $k\in\{1,\dots,\kappa\}$, the points $x_1,\dots,x_\kappa\in X$ are distinct, and $\delta_x$ is the Dirac measure at $x$. For $\kappa \leq 1$, the representation is unique; otherwise, it is unique up to permutations of $\{1, \dots, \kappa\}$.
\end{thm}

