\begin{lem}\label{lem:disintegration-lemma}
    Let $(X,d)$ be a complete and separable metric space, and let $(\mathcal{N}(X), \rho)$ be the associated Prokhorov space of finite integer-valued measures on $(X, \mathcal{B}(X))$. Let $\xi \in \mathcal{N}(X)$ be a non-zero measure with atomic decomposition 
    \begin{align*}
        \xi = \sum_{k\leq \kappa} \beta_k \delta_{x_k}.
    \end{align*}
    Let 
    \begin{align*}
        \gamma = \begin{cases}
            1, & \kappa = 1,\\
            \min\left(\frac{1}{2} \min_{\substack{k, k^\prime \leq \kappa \\ k \neq k^\prime}} d(x_k, x_{k^\prime}), 1 \right), & \kappa \geq 2,
        \end{cases}
    \end{align*}
    and $0 < \varepsilon < \gamma$. Let $\eta \in \mathcal{N}(X)$ be another measure with atomic decomposition 
    \begin{align*}
        \eta = \sum_{l\leq \lambda} \alpha_l \delta_{y_l}.
    \end{align*}
    If $\rho(\xi, \eta) < \varepsilon$, then $\eta\neq0$ by \eqref{eq:lem-helpful-point-process-3} of Lemma~\ref{lem:helpful-point-process}, and the sets $L_k = \{l\in\{1,\dots,\lambda\} \mid d(x_k,y_l)<\varepsilon\}$, $k\in\{1,\dots,\kappa\}$, satisfy:
    \begin{enumerate}[(i)]
        \item for every $k \in \{1,\dots,\kappa\}$, $\beta_k = \sum_{l \in L_k} \alpha_l$; 
        \item for all distinct $k, k^\prime \in \{1,\dots, \kappa\}$, $L_k \cap L_{k^\prime} = \emptyset$;
        \item for every $k \in \{1,\dots, \kappa\}$, it holds that $\max_{l \in L_k} d(x_k, y_l) < \varepsilon$; and 
        \item the sets $(L_k)_{k\leq \kappa}$ cover the atoms of $\eta$, i.e.
        \begin{align*}
            \bigcup_{k\leq \kappa} L_k = \{1,\dots,\lambda\}.
        \end{align*}
    \end{enumerate}
\end{lem}

