\begin{defn}[Permutative equality]\label{defn:permutative-equality}\index{permutative equality}
    Let $X$ be a set. Let $\overset{\pi}{\sim} \subseteq \mathscr{T}(X)\times \mathscr{T}(X)$ be the relation defined by 
    \begin{align*}
        \bm{x} \overset{\pi}{\sim} \bm{x}^\prime \iff \ell(\bm{x}) =\ell(\bm{x}^\prime) \land \exists \sigma \in \mathscr{P}_{\ell(\bm{x})} : \bm{x} = \bm{x}^\prime\circ\sigma.
    \end{align*}
    For any two elements $\bm{x} \overset{\pi}{\sim} \bm{x}^\prime$, we say that $\bm{x}$ and $\bm{x}^{\prime}$ are equal up to a permutation, and we call the property permutative equality.
\end{defn}

environments.statement:
\label{defn:permutative-equality}\index{permutative equality}
    Let $X$ be a set. Let $\overset{\pi}{\sim} \subseteq \mathscr{T}(X)\times \mathscr{T}(X)$ be the relation defined by 
    \begin{align*}
        \bm{x} \overset{\pi}{\sim} \bm{x}^\prime \iff \ell(\bm{x}) =\ell(\bm{x}^\prime) \land \exists \sigma \in \mathscr{P}_{\ell(\bm{x})} : \bm{x} = \bm{x}^\prime\circ\sigma.
    \end{align*}
    For any two elements $\bm{x} \overset{\pi}{\sim} \bm{x}^\prime$, we say that $\bm{x}$ and $\bm{x}^{\prime}$ are equal up to a permutation, and we call the property permutative equality.

proof.rawEnvironment:
\begin{proof}
    For any $\bm{x},\bm{x}^\prime, \bm{x}^\ast \in \mathscr{T}(X)$ we must show that 
    \begin{enumerate}
        \item $\bm{x} \overset{\pi}{\sim} \bm{x}$. \label{property:permutation-reflexive}
        \item $\bm{x} \overset{\pi}{\sim} \bm{x}^\prime$ if and only if $\bm{x}^\prime\overset{\pi}{\sim} \bm{x}$.\label{property:permutation-symmetry}
        \item If $\bm{x}\overset{\pi}{\sim} \bm{x}^\prime $ and $\bm{x}^\prime \overset{\pi}{\sim}  \bm{x}^\ast$, then $\bm{x} \overset{\pi}{\sim} \bm{x}^\ast$. \label{property:permutation-transitivity}
    \end{enumerate}
    For \eqref{property:permutation-reflexive}, notice that for any $\bm{x} \in \mathscr{T}(X)$ the mapping $\sigma:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x})$ defined by $\sigma(i) = i$ is a permutation, from which the result follows. 

    For \eqref{property:permutation-symmetry}, notice that if $\bm{x} \overset{\pi}{\sim} \bm{x}^\prime$, then there exists a $\sigma \in \mathscr{P}_{\ell(\bm{x})}$ such that $\bm{x} = \bm{x}^\prime \circ \sigma$. Since $\sigma$ is bijective, it is invertible, and $\bm{x} \circ \sigma^{-1} = \bm{x}^\prime \circ \sigma \circ \sigma^{-1} = \bm{x}^\prime$. Moreover, it is clear that $\sigma^{-1} \in \mathscr{P}_{\ell(\bm{x})} = \mathscr{P}_{\ell(\bm{x}^\prime)}$ as $\ell(\bm{x}) = \ell(\bm{x}^\prime)$ by assumption. Hence, the relation is symmetric. 

    Finally, notice that if $\bm{x}\overset{\pi}{\sim} \bm{x}^\prime $ and $\bm{x}^\prime \overset{\pi}{\sim}  \bm{x}^\ast$, then we immediately have $\ell(\bm{x}) =\ell(\bm{x}^\prime) =\ell(\bm{x}^\ast)$. There exist $\sigma,\sigma^\prime \in \mathscr{P}_{\ell(\bm{x})}$ such that
    \begin{align*}
        \bm{x} = \bm{x}^\prime \circ \sigma \quad \text{and}\quad \bm{x}^\prime = \bm{x}^\ast \circ \sigma^\prime.
    \end{align*}
    Then
    \begin{align*}
        \bm{x} = \bm{x}^\ast \circ \sigma^{\prime} \circ \sigma,
    \end{align*}
    and moreover $\sigma^{\prime}\circ \sigma \in \mathscr{P}_{\ell(\bm{x})}$ as desired. Hence, the relation is transitive. 
\end{proof}

