\begin{prop}[Permutative equality is an equivalence relation] \label{prop:perm-equal-equiv}
    For any set $X$, the permutative equality relation, $\overset{\pi}{\sim} \subseteq \mathscr{T}(X)\times \mathscr{T}(X)$, is an equivalence relation. 
\end{prop}

\begin{defn}\label{defn:permuted-tuple-quotient-space}
    For any set $X$ and tuple $\bm{x} \in \mathscr{T}(X)$, we define
    \begin{align*}
        \bm{x}^\pi = \{\bm{x}^\prime \in \mathscr{T}(X) \mid \bm{x} \overset{\pi}{\sim} \bm{x}^\prime\} 
    \end{align*}
     as the equivalence class induced by $\bm{x}$; any $\bm{x}^\prime \in \bm{x}^\pi$ is said to be equal to $\bm{x}$ up to a permutation. Moreover, we define 
     \begin{align*}
         \mathscr{T}^\pi(X) = \{\bm{x}^\pi \mid \bm{x} \in \mathscr{T}(X)\}
     \end{align*}
    as the quotient space\index{permuted tuple quotient space}, and call it the space of permuted tuples. 
\end{defn}

