\begin{proof}
    We must show that for every $\bm{y} \in \bm{x}^\pi$, the set of permutations
    \begin{align*}
        S(\bm{y}) = \{\sigma \in \mathscr{P}_n \mid \bm{x} \circ \sigma = \bm{y}\}
    \end{align*}
    has cardinality $|S(\bm{y})| = m_1! \cdots m_\kappa!$, and consequently that $|\bm{x}^\pi| = n! / (m_1! \cdots m_\kappa!)$. If $n = 0$, then $\bm{x} = \bm{e}$, $\mathscr{P}_0$ is a singleton, $\kappa = 0$, and the empty product equals $1$, so the claim holds immediately. Suppose therefore that $n > 0$, and let $a_1, \dots, a_\kappa \in X$ denote the distinct entries of $\bm{x}$. For each $j \in \{1, \dots, \kappa\}$, define the level set
    \begin{align*}
        I_j = \{i \in \{1, \dots, n\} \mid \bm{x}(i) = a_j\},
    \end{align*}
    which has cardinality $|I_j| = m_j$. A permutation $\sigma \in \mathscr{P}_n$ satisfies $\bm{x} \circ \sigma = \bm{x}$ if and only if $\bm{x}(\sigma(i)) = \bm{x}(i)$ for every $i \in \{1, \dots, n\}$, which holds if and only if $\sigma(I_j) = I_j$ for every $j \in \{1, \dots, \kappa\}$. Since the sets $I_1, \dots, I_\kappa$ partition $\{1, \dots, n\}$, choosing such a permutation $\sigma$ is equivalent to independently choosing a bijection of each $I_j$ onto itself. Therefore,
    \begin{align*}
        |S(\bm{x})| = m_1! \cdots m_\kappa!.
    \end{align*}

    Now let $\bm{y} \in \bm{x}^\pi$ be arbitrary. By Definition~\ref{defn:permutative-equality}, there exists a permutation $\sigma_0 \in \mathscr{P}_n$ such that $\bm{y} = \bm{x} \circ \sigma_0$. For any $\sigma \in \mathscr{P}_n$, we have
    \begin{align*}
        \bm{x} \circ \sigma = \bm{y} = \bm{x} \circ \sigma_0 \iff \bm{x} \circ (\sigma \circ \sigma_0^{-1}) = \bm{x} \iff \sigma \circ \sigma_0^{-1} \in S(\bm{x}).
    \end{align*}
    Because the right-multiplication map $\sigma \mapsto \sigma \circ \sigma_0^{-1}$ is a bijection from $\mathscr{P}_n$ onto itself, it restricts to a bijection from $S(\bm{y})$ onto $S(\bm{x})$, whence $|S(\bm{y})| = |S(\bm{x})| = m_1! \cdots m_\kappa!$. Finally, since the sets $(S(\bm{y}))_{\bm{y} \in \bm{x}^\pi}$ form a partition of $\mathscr{P}_n$ into $|\bm{x}^\pi|$ subsets of equal cardinality $m_1! \cdots m_\kappa!$, we obtain
    \begin{align*}
        n! = |\mathscr{P}_n| = \sum_{\bm{y} \in \bm{x}^\pi} |S(\bm{y})| = |\bm{x}^\pi|\, m_1! \cdots m_\kappa!,
    \end{align*}
    which yields $|\bm{x}^\pi| = n! / (m_1! \cdots m_\kappa!) \leq n!$, as desired.
\end{proof}

