\begin{defn}[Permuted-tuple matching distance]\label{defn:permuted-tuple-hausdorff-distance}
    Let $(X,d)$ be a metric space and put $\bar{d}(x,y)=\min\{d(x,y),1\}$. Define $\mathscr{d}_\pi : \mathscr{T}^\pi(X) \times \mathscr{T}^\pi(X) \to [0,1]$ by
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi,\bm{y}^\pi)
        =
        \begin{cases}
            1, & \ell(\bm{x})\neq\ell(\bm{y}),\\
            0, & \ell(\bm{x})=\ell(\bm{y})=0,\\
            \displaystyle\min_{\sigma\in\mathscr{P}_n}
            \max_{i\in\{1,\dots,n\}}
            \bar{d}\big(\bm{x}(i),\bm{y}(\sigma(i))\big),
            & \ell(\bm{x})=\ell(\bm{y})=n>0.
        \end{cases}
    \end{align*}
    We call $\mathscr{d}_\pi$ the permuted-tuple matching distance.
\end{defn}

