\label{defn:permuted-tuple-hausdorff-distance}
    Let $(X,d)$ be a metric space and put $\bar{d}(x,y)=\min\{d(x,y),1\}$. Define $\mathscr{d}_\pi : \mathscr{T}^\pi(X) \times \mathscr{T}^\pi(X) \to [0,1]$ by
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi,\bm{y}^\pi)
        =
        \begin{cases}
            1, & \ell(\bm{x})\neq\ell(\bm{y}),\\
            0, & \ell(\bm{x})=\ell(\bm{y})=0,\\
            \displaystyle\min_{\sigma\in\mathscr{P}_n}
            \max_{i\in\{1,\dots,n\}}
            \bar{d}\big(\bm{x}(i),\bm{y}(\sigma(i))\big),
            & \ell(\bm{x})=\ell(\bm{y})=n>0.
        \end{cases}
    \end{align*}
    We call $\mathscr{d}_\pi$ the permuted-tuple matching distance.

proof.rawEnvironment:
\begin{proof}
    First, we verify that $\mathscr{d}_\pi$ is well-defined on the quotient space $\mathscr{T}^\pi(X)$. Let $\bm{x}, \bm{x}^\prime \in \bm{x}^\pi$ and $\bm{y}, \bm{y}^\prime \in \bm{y}^\pi$ be representatives of two equivalence classes. If $\ell(\bm{x}) \neq \ell(\bm{y})$, then $\ell(\bm{x}^\prime) = \ell(\bm{x}) \neq \ell(\bm{y}) = \ell(\bm{y}^\prime)$, so both evaluations yield $1$. If $\ell(\bm{x}) = \ell(\bm{y}) = 0$, both evaluations yield $0$. Suppose therefore that $\ell(\bm{x}) = \ell(\bm{y}) = n > 0$. By Definition~\ref{defn:permutative-equality}, there exist permutations $\alpha, \beta \in \mathscr{P}_n$ such that $\bm{x}^\prime = \bm{x} \circ \alpha$ and $\bm{y}^\prime = \bm{y} \circ \beta$. For any candidate matching $\sigma \in \mathscr{P}_n$, reindexing $j = \alpha(i)$ yields
    \begin{align*}
        \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}^\prime(i), \bm{y}^\prime(\sigma(i))\big)
        &= \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(\alpha(i)), \bm{y}(\beta(\sigma(i)))\big)\\
        &= \max_{j \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(j), \bm{y}((\beta \circ \sigma \circ \alpha^{-1})(j))\big).
    \end{align*}
    Since $\sigma \mapsto \beta \circ \sigma \circ \alpha^{-1}$ is a bijection of $\mathscr{P}_n$ onto itself, taking the minimum over $\sigma \in \mathscr{P}_n$ yields the same value for $(\bm{x}^\prime, \bm{y}^\prime)$ as for $(\bm{x}, \bm{y})$. Thus $\mathscr{d}_\pi$ does not depend on the chosen representatives.

    Next, we must show that $\mathscr{d}_\pi : \mathscr{T}^\pi(X) \times \mathscr{T}^\pi(X) \to [0, 1]$ satisfies the three criteria of a metric for all $\bm{x}^\pi, \bm{y}^\pi, \bm{z}^\pi \in \mathscr{T}^\pi(X)$:
    \begin{enumerate}[(a)]
        \item $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = 0$ if and only if $\bm{x}^\pi = \bm{y}^\pi$.
        \item $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = \mathscr{d}_\pi(\bm{y}^\pi, \bm{x}^\pi)$.
        \item $\mathscr{d}_\pi(\bm{x}^\pi, \bm{z}^\pi) \leq \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) + \mathscr{d}_\pi(\bm{y}^\pi, \bm{z}^\pi)$.
    \end{enumerate}

    For (a), suppose first that $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = 0$. By definition of $\mathscr{d}_\pi$, we must have $\ell(\bm{x}) = \ell(\bm{y}) = n$ for some $n \in \mathbb{N}_0$, since otherwise $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = 1$. If $n = 0$, then $\bm{x} = \bm{e} = \bm{y}$, and hence $\bm{x}^\pi = \bm{y}^\pi$. If $n > 0$, then because $\mathscr{P}_n$ is finite, there exists a permutation $\sigma \in \mathscr{P}_n$ attaining the minimum, so that
    \begin{align*}
        \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i), \bm{y}(\sigma(i))\big) = 0.
    \end{align*}
    Since $\bar{d}$ is a metric on $X$, this implies that $\bm{x}(i) = \bm{y}(\sigma(i))$ for every $i \in \{1, \dots, n\}$, that is, $\bm{x} = \bm{y} \circ \sigma$. By Definition~\ref{defn:permutative-equality}, it follows that $\bm{x} \overset{\pi}{\sim} \bm{y}$, and hence $\bm{x}^\pi = \bm{y}^\pi$. Conversely, if $\bm{x}^\pi = \bm{y}^\pi$, we may choose the same representative $\bm{x}$ for both classes and take $\sigma = \mathrm{id}$ to obtain $\mathscr{d}_\pi(\bm{x}^\pi, \bm{x}^\pi) = 0$.

    For (b), the claim is immediate when $\ell(\bm{x}) \neq \ell(\bm{y})$ or $\ell(\bm{x}) = \ell(\bm{y}) = 0$. For $\ell(\bm{x}) = \ell(\bm{y}) = n > 0$, symmetry of $\bar{d}$ and the bijection $\sigma \mapsto \sigma^{-1}$ on $\mathscr{P}_n$ give
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi)
        &= \min_{\sigma \in \mathscr{P}_n} \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i), \bm{y}(\sigma(i))\big)\\
        &= \min_{\sigma \in \mathscr{P}_n} \max_{j \in \{1, \dots, n\}} \bar{d}\big(\bm{y}(j), \bm{x}(\sigma^{-1}(j))\big)
        = \mathscr{d}_\pi(\bm{y}^\pi, \bm{x}^\pi).
    \end{align*}

    For (c), if $\ell(\bm{x}) = \ell(\bm{y}) = \ell(\bm{z}) = n > 0$, let $\sigma, \sigma^\prime \in \mathscr{P}_n$ attain the minima defining $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi)$ and $\mathscr{d}_\pi(\bm{y}^\pi, \bm{z}^\pi)$, respectively. Since $\sigma^\prime \circ \sigma \in \mathscr{P}_n$, the triangle inequality for $\bar{d}$ yields
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi,\bm{z}^\pi)
        &\leq \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i),\bm{z}(\sigma^\prime(\sigma(i)))\big)\\
        &\leq \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i),\bm{y}(\sigma(i))\big) + \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{y}(\sigma(i)),\bm{z}(\sigma^\prime(\sigma(i)))\big)\\
        &= \mathscr{d}_\pi(\bm{x}^\pi,\bm{y}^\pi) + \mathscr{d}_\pi(\bm{y}^\pi,\bm{z}^\pi).
    \end{align*}
    If $\ell(\bm{x}) \neq \ell(\bm{z})$, then $\mathscr{d}_\pi(\bm{x}^\pi, \bm{z}^\pi) = 1$, while either $\ell(\bm{x}) \neq \ell(\bm{y})$ or $\ell(\bm{y}) \neq \ell(\bm{z})$, so at least one of $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi)$ or $\mathscr{d}_\pi(\bm{y}^\pi, \bm{z}^\pi)$ equals $1$. If $\ell(\bm{x}) = \ell(\bm{z})$ but $\ell(\bm{y}) \neq \ell(\bm{x})$, then $\mathscr{d}_\pi(\bm{x}^\pi, \bm{z}^\pi) \leq 1 < 2 = \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) + \mathscr{d}_\pi(\bm{y}^\pi, \bm{z}^\pi)$. Finally, if $\ell(\bm{x}) = \ell(\bm{y}) = \ell(\bm{z}) = 0$, all three distances are $0$. Therefore, $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is a metric space.

    To prove (1), suppose that $(X,d)$ is separable, and let $D\subseteq X$ be a countable dense subset. Define the subset
    \begin{align*}
        \mathscr{D}^\pi = \{\bm{q}^\pi \in \mathscr{T}^\pi(X) \mid \bm{q} \in \mathscr{T}(D)\}.
    \end{align*}
    Because $\mathscr{T}(D) = \bigcup_{n \in \mathbb{N}_0} D^n$ is a countable union of countable sets, $\mathscr{D}^\pi$ is countable. Moreover, for any $\bm{x}^\pi \in \mathscr{T}^\pi(X)$ and $\varepsilon > 0$, if $\ell(\bm{x}) = 0$, then $\bm{x}^\pi = \bm{e}^\pi \in \mathscr{D}^\pi$; if $\ell(\bm{x}) = n > 0$, density of $D$ in $X$ provides elements $q_1, \dots, q_n \in D$ such that $d(\bm{x}(i), q_i) < \varepsilon$ for every $i \in \{1, \dots, n\}$. Setting $\bm{q} = (q_1, \dots, q_n) \in \mathscr{T}(D)$ and taking $\sigma = \mathrm{id} \in \mathscr{P}_n$ gives
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi, \bm{q}^\pi) \leq \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i), \bm{q}(i)\big) < \varepsilon,
    \end{align*}
    which proves that $\mathscr{D}^\pi$ is dense in $\mathscr{T}^\pi(X)$ and hence that $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is separable.

    To prove (2), suppose that $(X,d)$ is complete, equivalently that $(X,\bar{d})$ is complete, and let $(\bm{x}_n^\pi)_{n\in\mathbb{N}}$ be a Cauchy sequence in $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$. Since $\mathscr{d}_\pi(\bm{u}^\pi, \bm{v}^\pi) = 1$ whenever $\ell(\bm{u}) \neq \ell(\bm{v})$, there exists an $N \in \mathbb{N}$ and a common length $r \in \mathbb{N}_0$ such that $\ell(\bm{x}_n) = r$ for all $n \geq N$. If $r = 0$, then $\bm{x}_n^\pi = \bm{e}^\pi$ for all $n \geq N$, and the sequence converges to $\bm{e}^\pi$. Assume therefore that $r > 0$. By passing to the tail $n \geq N$, we may extract a subsequence $(\bm{x}_{n_k}^\pi)_{k\in\mathbb{N}}$ such that
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi)<2^{-k} \qquad \forall k \in \mathbb{N}.
    \end{align*}
    Choose an arbitrary representative $\bm{y}_1\in\bm{x}_{n_1}^\pi$. Proceeding inductively for $k \in \mathbb{N}$, given $\bm{y}_k \in \bm{x}_{n_k}^\pi$ and an arbitrary initial representative $\widetilde{\bm{y}}_{k+1} \in \bm{x}_{n_{k+1}}^\pi$, let $\sigma_k \in \mathscr{P}_r$ attain the minimum in $\mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi)$ and set $\bm{y}_{k+1} = \widetilde{\bm{y}}_{k+1} \circ \sigma_k \in \bm{x}_{n_{k+1}}^\pi$. Then
    \begin{align*}
        \max_{i \in \{1, \dots, r\}}\bar{d}\big(\bm{y}_k(i),\bm{y}_{k+1}(i)\big) = \mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi) < 2^{-k}.
    \end{align*}
    Consequently, for each coordinate $i \in \{1, \dots, r\}$, the sequence $(\bm{y}_k(i))_{k\in\mathbb{N}}$ is Cauchy in $(X, \bar{d})$ and therefore converges to a limit $y(i)\in X$. Defining $\bm{y}=(y(1),\dots,y(r)) \in \mathscr{T}(X)$ and taking the identity permutation in Definition~\ref{defn:permuted-tuple-hausdorff-distance} yields
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}_{n_k}^\pi, \bm{y}^\pi) \leq \max_{i \in \{1, \dots, r\}} \bar{d}\big(\bm{y}_k(i), \bm{y}(i)\big) \xrightarrow{k \to \infty} 0.
    \end{align*}
    Because $(\bm{x}_n^\pi)_{n\in\mathbb{N}}$ is Cauchy and possesses a subsequence converging to $\bm{y}^\pi$, the entire sequence converges to $\bm{y}^\pi$. This proves that $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is complete, as desired.
\end{proof}

