\begin{defn}\label{defn:tuple-induced-integer-valued-measure}
    Let $X$ be a measurable space, $\mathscr{T}(X)$ be the tuple space over $X$, and $\mathcal{N}(X)$ be the finite integer-valued measures on $X$. Define the mapping $\mathfrak{m} :\mathscr{T}(X) \to \mathcal{N}(X)$ by 
    \begin{align*}
        \mathfrak{m}(\bm{x}) = B \mapsto \sum_{i \in \mathrm{domain}(\bm{x})} \delta_{\bm{x}(i)}(B).
    \end{align*}
    We call $\mathfrak{m}(\bm{x})$ the integer-valued measure, or simply measure, induced by\index{tuple-induced measure} $\bm{x}\in\mathscr{T}(X)$.
\end{defn}

environments.statement:
\label{defn:tuple-induced-integer-valued-measure}
    Let $X$ be a measurable space, $\mathscr{T}(X)$ be the tuple space over $X$, and $\mathcal{N}(X)$ be the finite integer-valued measures on $X$. Define the mapping $\mathfrak{m} :\mathscr{T}(X) \to \mathcal{N}(X)$ by 
    \begin{align*}
        \mathfrak{m}(\bm{x}) = B \mapsto \sum_{i \in \mathrm{domain}(\bm{x})} \delta_{\bm{x}(i)}(B).
    \end{align*}
    We call $\mathfrak{m}(\bm{x})$ the integer-valued measure, or simply measure, induced by\index{tuple-induced measure} $\bm{x}\in\mathscr{T}(X)$.

proof.rawEnvironment:
\begin{proof}
    We must show that for every $\varepsilon > 0$ and $\bm{x}_0$ there exists a $\theta > 0 $ such that
    \begin{align*}
        \mathscr{d}_H(\bm{x}, \bm{x}_0) < \theta \implies \rho(\mathfrak{m}(\bm{x}), \mathfrak{m}(\bm{x}_0)) < \varepsilon.
    \end{align*}
Choose $0<\theta < \min\{\varepsilon,1\}$. First, recall that by Theorem~\ref{thm:tuple-space-properties} we have that
    \begin{align*}
        \mathscr{d}_H(\bm{x}, \bm{x}_0) < \theta < 1
    \end{align*}
    implies that $\ell(\bm{x}) = \ell(\bm{x}_0)$. If $\bm{x}_0$ is the empty tuple, then $\bm{x}$ is also the empty tuple, and therefore
    \begin{align*}
        \rho(\mathfrak{m}(\bm{x}),\mathfrak{m}(\bm{x}_0)) = 0 < \varepsilon.
    \end{align*}
    Assume therefore that $\bm{x}_0 \neq \bm{e}$. Then, we additionally have 
    \begin{align*}
        \mathscr{d}_H(\bm{x},\bm{x}_0) = \max_{i \in \mathrm{domain}(\bm{x}_0)} d(\bm{x}(i), \bm{x}_0(i)) < \theta < 1.
    \end{align*}
    Consequently, for any Borel set $B$ and every index $i \in \mathrm{domain}(\bm{x}_0)$,
    \begin{align*}
        \bm{x}_0(i)\in B \implies \bm{x}(i)\in B^\theta.
    \end{align*}
    Therefore,
    \begin{align*}
        \mathfrak{m}(\bm{x}_0)(B) \leq \mathfrak{m}(\bm{x})(B^\theta).
    \end{align*}
    By symmetry,
    \begin{align*}
        \mathfrak{m}(\bm{x})(B) \leq \mathfrak{m}(\bm{x}_0)(B^\theta).
    \end{align*}
    Hence, by the definition of the Prokhorov metric,
    \begin{align*}
        \rho(\mathfrak{m}(\bm{x}), \mathfrak{m}(\bm{x}_0)) \leq \theta < \varepsilon,
    \end{align*}
    as desired.
\end{proof}

