\begin{prop}\label{prop:tuple-measure-surjective}
    Let $X$ be a standard Borel space, let $\mathscr{T}(X)$ be the associated tuple space, and let $\mathcal{N}(X)$ be the space of finite integer-valued measures on $X$. Then, the mapping $\mathfrak{m}:\mathscr{T}(X) \to \mathcal{N}(X)$ is surjective.
\end{prop}

proof.rawEnvironment:
\begin{proof}
    We must show that for every $\bm{x} \in \mathscr{T}(X)$, every $\bm{x}^\prime \in \bm{x}^\pi$, and every Borel set $B \in \mathcal{B}(X)$, it holds that $\mathfrak{m}(\bm{x}^\prime)(B) = \mathfrak{m}(\bm{x})(B)$. If $\bm{x} = \bm{e}$, then $\bm{x}^\pi = \{\bm{e}\}$ and the identity is immediate. Suppose therefore that $\ell(\bm{x}) > 0$. By Definition~\ref{defn:permutative-equality}, any $\bm{x}^\prime \in \bm{x}^\pi$ satisfies $\ell(\bm{x}^\prime) = \ell(\bm{x})$ and $\bm{x}^\prime = \bm{x} \circ \sigma$ for some permutation $\sigma \in \mathscr{P}_{\ell(\bm{x})}$. Reindexing the finite sum in Definition~\ref{defn:tuple-induced-integer-valued-measure} via $j = \sigma(i)$ yields, for every $B \in \mathcal{B}(X)$,
    \begin{align*}
        \mathfrak{m}(\bm{x}^\prime)(B)
        = \sum_{i \in \mathrm{domain}(\bm{x})} \delta_{\bm{x}(\sigma(i))}(B)
        = \sum_{j \in \mathrm{domain}(\bm{x})} \delta_{\bm{x}(j)}(B)
        = \mathfrak{m}(\bm{x})(B),
    \end{align*}
    which proves that $\mathfrak{m}(\bm{x}^\prime) = \mathfrak{m}(\bm{x})$, as desired.
\end{proof}

