environments.statement:
\label{prop:permuted-tuple-measure-map-bijective}
    Let $X$ be a standard Borel space, let $\mathscr{T}(X)$ be the associated tuple space, and let $\mathcal{N}(X)$ be the space of finite integer-valued measures on $X$. Then, the mapping $\mathfrak{m}^\pi:\mathscr{T}^\pi(X) \to \mathcal{N}(X)$ defined by 
    \begin{align*}
        \mathfrak{m}^\pi(\bm{x}^\pi) = \mathfrak{m}(\bm{x})
    \end{align*}
    is bijective.

proof.rawEnvironment:
\begin{proof}
    We must show that for every $\varepsilon > 0$ and every $\bm{x}^\pi \in \mathscr{T}^\pi(X)$, there exists a $\theta > 0$ such that
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) < \theta \implies \rho\bigl(\mathfrak{m}^\pi(\bm{x}^\pi), \mathfrak{m}^\pi(\bm{y}^\pi)\bigr) < \varepsilon.
    \end{align*}
    Fix $\varepsilon>0$ and choose $0<\theta<\min\{\varepsilon,1\}$. Suppose that $\bm{y}^\pi \in \mathscr{T}^\pi(X)$ satisfies $\mathscr{d}_\pi(\bm{x}^\pi,\bm{y}^\pi)<\theta < 1$. By Definition~\ref{defn:permuted-tuple-hausdorff-distance}, the representatives $\bm{x}$ and $\bm{y}$ must have the same length $\ell(\bm{x}) = \ell(\bm{y}) = n$. If $n = 0$, then $\bm{x}^\pi = \bm{e}^\pi = \bm{y}^\pi$, so $\rho(\mathfrak{m}^\pi(\bm{x}^\pi), \mathfrak{m}^\pi(\bm{y}^\pi)) = 0 < \varepsilon$. Assume therefore that $n > 0$. Because $\mathscr{P}_n$ is finite, the minimum in Definition~\ref{defn:permuted-tuple-hausdorff-distance} is attained by some permutation $\sigma \in \mathscr{P}_n$. Defining the permuted representative $\widetilde{\bm{y}} = \bm{y} \circ \sigma \in \bm{y}^\pi$, we have $\bar{d}(\bm{x}(i), \widetilde{\bm{y}}(i)) < \theta < 1$ for every $i \in \{1, \dots, n\}$. Since $\bar{d}$ and $d$ coincide at distances strictly below $1$ (Theorem~\ref{thm:the-standard-machinery}), it follows that
    \begin{align*}
        \mathscr{d}_H(\bm{x},\widetilde{\bm{y}})
        = \max_{i \in \{1, \dots, n\}} d\big(\bm{x}(i),\widetilde{\bm{y}}(i)\big)
        = \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) < \theta.
    \end{align*}
    By Corollary~\ref{cor:tuple-induced-measure-permutation-invariant}, we have $\mathfrak{m}^\pi(\bm{y}^\pi) = \mathfrak{m}(\bm{y}) = \mathfrak{m}(\widetilde{\bm{y}})$. Applying the proof of Proposition~\ref{prop:tuple-induced-measure-continuous} with every $\theta^\prime \in (\mathscr{d}_H(\bm{x},\widetilde{\bm{y}}), 1)$ in place of $\theta$ and taking the infimum over $\theta^\prime$ yields
    \begin{align*}
        \rho\bigl(\mathfrak{m}^\pi(\bm{x}^\pi),\mathfrak{m}^\pi(\bm{y}^\pi)\bigr)
        = \rho\bigl(\mathfrak{m}(\bm{x}),\mathfrak{m}(\widetilde{\bm{y}})\bigr)
        \leq \mathscr{d}_H(\bm{x},\widetilde{\bm{y}}) < \theta < \varepsilon,
    \end{align*}
    which proves that $\mathfrak{m}^\pi$ is continuous, as desired.
\end{proof}

proof.text:
We must show that for every $\varepsilon > 0$ and every $\bm{x}^\pi \in \mathscr{T}^\pi(X)$, there exists a $\theta > 0$ such that
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) < \theta \implies \rho\bigl(\mathfrak{m}^\pi(\bm{x}^\pi), \mathfrak{m}^\pi(\bm{y}^\pi)\bigr) < \varepsilon.
    \end{align*}
    Fix $\varepsilon>0$ and choose $0<\theta<\min\{\varepsilon,1\}$. Suppose that $\bm{y}^\pi \in \mathscr{T}^\pi(X)$ satisfies $\mathscr{d}_\pi(\bm{x}^\pi,\bm{y}^\pi)<\theta < 1$. By Definition~\ref{defn:permuted-tuple-hausdorff-distance}, the representatives $\bm{x}$ and $\bm{y}$ must have the same length $\ell(\bm{x}) = \ell(\bm{y}) = n$. If $n = 0$, then $\bm{x}^\pi = \bm{e}^\pi = \bm{y}^\pi$, so $\rho(\mathfrak{m}^\pi(\bm{x}^\pi), \mathfrak{m}^\pi(\bm{y}^\pi)) = 0 < \varepsilon$. Assume therefore that $n > 0$. Because $\mathscr{P}_n$ is finite, the minimum in Definition~\ref{defn:permuted-tuple-hausdorff-distance} is attained by some permutation $\sigma \in \mathscr{P}_n$. Defining the permuted representative $\widetilde{\bm{y}} = \bm{y} \circ \sigma \in \bm{y}^\pi$, we have $\bar{d}(\bm{x}(i), \widetilde{\bm{y}}(i)) < \theta < 1$ for every $i \in \{1, \dots, n\}$. Since $\bar{d}$ and $d$ coincide at distances strictly below $1$ (Theorem~\ref{thm:the-standard-machinery}), it follows that
    \begin{align*}
        \mathscr{d}_H(\bm{x},\widetilde{\bm{y}})
        = \max_{i \in \{1, \dots, n\}} d\big(\bm{x}(i),\widetilde{\bm{y}}(i)\big)
        = \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) < \theta.
    \end{align*}
    By Corollary~\ref{cor:tuple-induced-measure-permutation-invariant}, we have $\mathfrak{m}^\pi(\bm{y}^\pi) = \mathfrak{m}(\bm{y}) = \mathfrak{m}(\widetilde{\bm{y}})$. Applying the proof of Proposition~\ref{prop:tuple-induced-measure-continuous} with every $\theta^\prime \in (\mathscr{d}_H(\bm{x},\widetilde{\bm{y}}), 1)$ in place of $\theta$ and taking the infimum over $\theta^\prime$ yields
    \begin{align*}
        \rho\bigl(\mathfrak{m}^\pi(\bm{x}^\pi),\mathfrak{m}^\pi(\bm{y}^\pi)\bigr)
        = \rho\bigl(\mathfrak{m}(\bm{x}),\mathfrak{m}(\widetilde{\bm{y}})\bigr)
        \leq \mathscr{d}_H(\bm{x},\widetilde{\bm{y}}) < \theta < \varepsilon,
    \end{align*}
    which proves that $\mathfrak{m}^\pi$ is continuous, as desired.

