proof.rawEnvironment:
\begin{proof}
    We must show that for every $\varepsilon > 0$ and $\xi_0 \in \mathcal{N}(X)$ there exists a $\theta > 0$ such that
    \begin{align*}
        \rho(\xi, \xi_0) < \theta \implies \mathscr{d}_\pi((\mathfrak{m}^\pi)^{-1}(\xi), (\mathfrak{m}^\pi)^{-1}(\xi_0)) < \varepsilon.
    \end{align*}
    If $\xi_0 = 0$, choose $0<\theta < \min\{\varepsilon,1\}$. If $\rho(\xi,\xi_0)<\theta$, then Lemma~\ref{lem:helpful-point-process} gives
    \begin{align*}
        \xi(X)=\xi_0(X)=0,
    \end{align*}
    so $\xi=0$ and the conclusion is immediate. Therefore, assume that $\xi_0 \neq 0$.

    By Theorem~\ref{thm:sufficient-decomposition}, $\xi_0$ admits the decomposition
    \begin{align*}
        \xi_0 = \sum_{k \leq \kappa} \beta_k \delta_{x_k},
    \end{align*}
    with $(\beta_k)_{k \leq \kappa} \subseteq \mathbb{N}$ and distinct $(x_k)_{k \leq \kappa} \subseteq X$. Define
    \begin{align*}
        S_0 = 0, \qquad S_k = \sum_{r=1}^k \beta_r \quad \text{for } k \in \{1,\dots,\kappa\},
    \end{align*}
    and let $\bm{x}_0 \in \mathscr{T}(X)$ be the tuple defined by
    \begin{align*}
        \bm{x}_0(i) = x_k \quad \text{whenever } S_{k-1} < i \leq S_k.
    \end{align*}
    Then $\mathfrak{m}(\bm{x}_0)=\xi_0$, so $(\mathfrak{m}^\pi)^{-1}(\xi_0)=\bm{x}_0^\pi$.

    Let $\gamma$ be as in Lemma~\ref{lem:disintegration-lemma} for the atoms of $\xi_0$, that is,
    \begin{align*}
        \gamma = \begin{cases}
            1, & \kappa = 1,\\
            \min\left(\frac{1}{2} \min_{\substack{k,j \leq \kappa \\ k \neq j}} d(x_k, x_j), 1\right), & \kappa \geq 2,
        \end{cases}
    \end{align*}
    and choose $0<\theta < \min\{\varepsilon,\gamma\}$. Let $\xi \in \mathcal{N}(X)$ satisfy $\rho(\xi,\xi_0)<\theta$. By Theorem~\ref{thm:sufficient-decomposition}, $\xi$ admits the decomposition
    \begin{align*}
        \xi = \sum_{l \leq \lambda} \alpha_l \delta_{y_l},
    \end{align*}
    with $(\alpha_l)_{l \leq \lambda} \subseteq \mathbb{N}$ and distinct $(y_l)_{l \leq \lambda} \subseteq X$.

    Since $\rho(\xi,\xi_0)<\theta<1$, Lemma~\ref{lem:helpful-point-process} gives $\xi(X)=\xi_0(X)>0$, so $\xi\neq0$, and by Lemma~\ref{lem:disintegration-lemma}, applied with $\varepsilon=\theta$, there exist pairwise disjoint sets $L_k \subseteq \{1,\dots,\lambda\}$, $k \in \{1,\dots,\kappa\}$, covering $\{1,\dots,\lambda\}$ such that
    \begin{align*}
        \beta_k = \sum_{l\in L_k} \alpha_l
        \qquad \text{and} \qquad
        d(x_k,y_l) < \theta \quad \forall l \in L_k.
    \end{align*}
    Choose an enumeration $L_k = \{l_{k,1},\dots,l_{k,m_k}\}$ for each $k$, and define partial sums
    \begin{align*}
        M_{k,0} = 0, \qquad M_{k,r} = \sum_{s=1}^r \alpha_{l_{k,s}} \quad \text{for } r \in \{1,\dots,m_k\}.
    \end{align*}
    Define a tuple $\bm{x} \in \mathscr{T}(X)$ by declaring that, on the $k$-th block $S_{k-1} < i \leq S_k$, one has
    \begin{align*}
        \bm{x}(i) = y_{l_{k,r}} \quad \text{whenever } S_{k-1}+M_{k,r-1} < i \leq S_{k-1}+M_{k,r}.
    \end{align*}
    Since $\sum_{l\in L_k} \alpha_l = \beta_k$, this indeed fills the entire $k$-th block. Because the sets $L_k$ cover $\{1,\dots,\lambda\}$, every atom of $\xi$ is listed with its multiplicity, so $\mathfrak{m}(\bm{x})=\xi$, so $(\mathfrak{m}^\pi)^{-1}(\xi)=\bm{x}^\pi$.

    Finally, for every index $i$ in the $k$-th block we have $\bm{x}_0(i)=x_k$ and $\bm{x}(i)=y_l$ for some $l\in L_k$, hence
    \begin{align*}
        d(\bm{x}(i),\bm{x}_0(i)) < \theta.
    \end{align*}
    Therefore,
    \begin{align*}
        \mathscr{d}_H(\bm{x},\bm{x}_0) < \theta < \varepsilon,
    \end{align*}
    and consequently
    \begin{align*}
        \mathscr{d}_\pi((\mathfrak{m}^\pi)^{-1}(\xi),(\mathfrak{m}^\pi)^{-1}(\xi_0))
        = \mathscr{d}_\pi(\bm{x}^\pi,\bm{x}_0^\pi)
        \leq \mathscr{d}_H(\bm{x},\bm{x}_0)
        < \varepsilon.
    \end{align*}
    The inequality uses the identity matching in Definition~\ref{defn:permuted-tuple-hausdorff-distance} and $\bar{d}\leq d$. This proves continuity.
\end{proof}

