\begin{lem}[Measurable Enumeration; \citealp{DaleyVereJones2008PointProcessesVol2}]\label{lem:measurable-enumeration}\index{measurable enumeration}
    Let $(X,d)$ be a complete and separable metric space, and let $(\mathcal{N}(X), \rho)$ be the space of finite integer-valued measures on $X$ endowed with the Prokhorov distance. Then there exists a measurable mapping $\tau: \mathcal{N}(X) \to \mathscr{T}(X)$ such that, for every $\mu\in\mathcal{N}(X)$, $\tau(\mu) \in (\mathfrak{m}^\pi)^{-1}(\mu)$.
\end{lem}

\begin{rem}\label{rem:measurable-enumeration-adaptation}
    Note that in \citet[Definition~9.1.XI and Lemma~9.1.XIII]{DaleyVereJones2008PointProcessesVol2} the result is stated as a measurable enumeration of the points of a point process, and the lemma above adapts it to the variable-length tuple space. Given $\mu\in\mathcal{N}(X)$, we can enumerate the atoms of $\mu$ in a measurable way including their multiplicities. Such an enumeration corresponds naturally to a tuple $\tau(\mu)$ with $\mathfrak{m}(\tau(\mu))=\mu$. 
\end{rem}

