\begin{proof}
    We must show that 
    \begin{enumerate}
        \item $B \mapsto \mathsf{K}_{\mathrm{perm}}(\omega, B)$ is a probability measure for all $\omega \in \Omega$, and
        \item $\omega \mapsto \mathsf{K}_{\mathrm{perm}}(\omega, B)$ is $\mathcal{F}/\mathcal{B}([0,1])$-measurable for every $B\in\mathcal{B}(\mathscr{T}(X))$.
    \end{enumerate}
    For fixed $\omega$, let $n=N(\omega)$. Then
    \begin{align*}
        \mathsf{K}_{\mathrm{perm}}(\omega,\cdot) = \frac{1}{n!}\sum_{\sigma \in \mathscr{P}_n} \delta_{\tau(\xi(\omega))\circ \sigma},
    \end{align*}
    which is a finite convex combination of Dirac probability measures, hence a probability measure. Each $\tau(\xi(\omega))\circ\sigma$ induces $\xi(\omega)$ by Corollary~\ref{cor:tuple-induced-measure-permutation-invariant}, which gives the support statement. By Proposition~\ref{prop:finite-equivalence-classes}, every tuple in the class $(\mathfrak{m}^\pi)^{-1}(\xi(\omega))$ is produced by the same number of permutations, so the weights are uniform on the class.

    It remains to prove measurability in $\omega$. For $n \in \mathbb{N}_0$, define
    \begin{align*}
        A_n = \{\omega \in \Omega \mid N(\omega)=n\} = \{\omega \in \Omega \mid \xi(\omega)(X)=n\}.
    \end{align*}
    Since $\omega \mapsto \xi(\omega)(X)$ is measurable, each $A_n \in \mathcal{F}$. Now let $B \in \mathcal{B}(\mathscr{T}(X))$ be fixed. By measurability of $\tau \circ \xi$ (Lemma~\ref{lem:measurable-enumeration} and Remark~\ref{rem:point-process-measurability-equivalence}) and continuity of the permutation map $\bm{x}\mapsto\bm{x}[\sigma]$ of Definition~\ref{defn:permutation-map} (Proposition~\ref{prop:permuting-continuous}) for fixed $\sigma\in\mathscr{P}_n$, the map
    \begin{align*}
        \omega \mapsto \mathbbm{1}_{A_n}(\omega)\mathbbm{1}_{B}(\tau(\xi(\omega))[\sigma])
    \end{align*}
    is measurable for every $n$ and every $\sigma \in \mathscr{P}_n$.
    For $\omega\notin A_n$, the total permutation map returns the empty tuple, so the displayed expression is defined on all of $\Omega$. For $\omega\in A_n$, the defining property of $\tau$ gives $\ell(\tau(\xi(\omega)))=\xi(\omega)(X)=n$, and hence, including when $n=0$, $\tau(\xi(\omega))[\sigma]=\tau(\xi(\omega))\circ\sigma$.
    Therefore,
    \begin{align*}
        \omega \mapsto \frac{1}{n!}\sum_{\sigma \in \mathscr{P}_n}\mathbbm{1}_{A_n}(\omega)\mathbbm{1}_{B}(\tau(\xi(\omega))[\sigma])
    \end{align*}
    is measurable for each $n$. Finally,
    \begin{align*}
        \mathsf{K}_{\mathrm{perm}}(\omega,B)
        = \sum_{n=0}^\infty \frac{1}{n!}\sum_{\sigma \in \mathscr{P}_n}\mathbbm{1}_{A_n}(\omega)\mathbbm{1}_{B}(\tau(\xi(\omega))[\sigma]),
    \end{align*}
    and this is measurable because the sum is countable and, for each fixed $\omega$, at most one term in $n$ is non-zero. Hence $\omega \mapsto \mathsf{K}_{\mathrm{perm}}(\omega,B)$ is measurable, as desired.
\end{proof}

