\begin{thm}\label{thm:point-process-tuple}
    Let $(\Omega, \mathcal{F},\mathbb{P})$ be a probability space, and let $(X,d)$ be a complete and separable metric space. Let $\xi :\Omega \to \mathcal{N}(X)$ be a point process. Let $\tau:\mathcal{N}(X) \to \mathscr{T}(X)$ be a measurable enumeration as in Lemma~\ref{lem:measurable-enumeration}. Define the mapping $\mathsf{K}_{\mathrm{perm}} :\Omega \times \mathcal{B}(\mathscr{T}(X)) \to [0,1]$ by
    \begin{align*}
        \mathsf{K}_{\mathrm{perm}}(\omega, B) = \frac{1}{N(\omega)!} \sum_{\sigma \in \mathscr{P}_{N(\omega)}} \mathbbm{1}_B(\tau(\xi(\omega))\circ \sigma),
    \end{align*}
    where $N(\omega) = \xi(\omega)(X)$ is the total number of points of the realisation $\xi(\omega)$. Then, $\mathsf{K}_{\mathrm{perm}}$ is a Markov kernel from $(\Omega, \mathcal{F})$ to $(\mathscr{T}(X), \mathcal{B}(\mathscr{T}(X)))$. Moreover,
    \begin{align*}
        \mathsf{K}_{\mathrm{perm}}(\omega,\mathfrak{m}^{-1}(\{\xi(\omega)\}))=1,
    \end{align*}
    and $\mathsf{K}_{\mathrm{perm}}(\omega,\cdot)$ is the uniform distribution on the class $(\mathfrak{m}^\pi)^{-1}(\xi(\omega))$; in particular, it does not depend on the choice of $\tau$.
\end{thm}

