\begin{defn}[Functionals and Operators]\label{defn:functional-and-operator}
    Let $X$ be a non-empty set and let $\mathbb{K}$ be a field. Then any mapping $\varphi: X \to \mathbb{K}$ is called a $\mathbb{K}$-functional, or simply a functional. Similarly, let $V$ be a vector space over some field $\mathbb{K}$. Then any mapping $\varphi:X \to V$ is called a $V$-operator or simply an operator. 
\end{defn}

\begin{defn}[Weakly Linear Operator]\label{defn:weak-linear-operator}\index{weakly linear operators}
    Let $X$ be a non-empty set and let $V$ be a vector space over some field $\mathbb{K}$. Then, any operator $\varphi: X \to V$ is said to be weakly linear if, for every $\alpha , \beta\in \mathbb{K}$ and $x, x^\prime \in X$, there exists an $x^\ast \in X$ such that 
    \begin{align*}
        \varphi(x^\ast) = \alpha \varphi(x) + \beta \varphi(x^\prime). 
    \end{align*}
\end{defn}

