\begin{prop}\label{prop:phi-subspace}
    Let $X$ be a non-empty set, $V$ a vector space over some field $\mathbb{K}$, and $\varphi : X \to V$ an operator. Then, $\varphi$ is weakly linear if and only if $\varphi(X)$ is a subspace of $V$. Similarly, if $V$ is a real vector space, then $\varphi:X \to V$ is weakly convex if and only if $\varphi(X)$ is a convex cone in $V$. 
\end{prop}

\begin{prop}\label{prop:phi-extends}
    Let $X$ and $Y$ be non-empty sets and $\varphi : X \to Y$ be a function. Let $\overset{\varphi}{\sim}$ be a relation on $X$ defined by 
