\begin{defn}[Kernel Quotient of a Function]\label{defn:function-kernel-quotient-space}
    Let $X$ and $Y$ be non-empty sets and $\varphi : X \to Y$ a function. Endow $X$ with the equivalence relation $\overset{\varphi}{\sim} \subseteq X \times X$ defined by 
    \begin{align}
        x \overset{\varphi}{\sim} x^\prime \iff \varphi(x) = \varphi(x^\prime).
    \end{align}
    Then the quotient set $X_{\overset{\varphi}{\sim}} = \{[x]_{\overset{\varphi}{\sim}} \mid x \in X\}$ is called the kernel quotient of $\varphi$, and for simplicity, we denote it by $X_\varphi$. Likewise, we denote by $x_\varphi$ the equivalence class of $x$ under $\overset{\varphi}{\sim}$, i.e. $x_\varphi = [x]_{\overset{\varphi}{\sim}}$.
\end{defn}

