\begin{thm}[Weak Transport of Structure]\label{thm:weak-linear-transport-vector-space-structure}
    Let $X$ be a non-empty set, $V$ a vector space over some field $\mathbb{K}$, and $\varphi : X \to V$ a weakly linear operator. Then, $X_\varphi$ is a vector space over $\mathbb{K}$ when endowed with the operations $+:X_\varphi \times X_\varphi \to X_\varphi$ and $\cdot:\mathbb{K} \times X_\varphi  \to X_{\varphi}$ defined by
    \begin{align*}
        x_\varphi + x^\prime_\varphi = \Phi^{-1}(\Phi(x_\varphi) + \Phi(x^\prime_\varphi)),
    \end{align*}
    and 
    \begin{align*}
        \alpha \cdot x_\varphi = \Phi^{-1}(\alpha \Phi(x_\varphi)),
    \end{align*}
    for $x_\varphi, x^\prime_\varphi \in X_\varphi$ and $\alpha\in\mathbb{K}$, where $\Phi^{-1}$ denotes the inverse of the bijection $\Phi:X_\varphi\to\varphi(X)$.
\end{thm}

