\end{prop}

\begin{cor}[Transport of Hilbert Structure]\label{cor:bijective-weak-linear-transport-hilbert-structure}
    Let $X$ be a non-empty set, $(\mathcal{H}, \langle \cdot,\cdot\rangle)$ a Hilbert space, and $\varphi: X \to \mathcal{H}$ a weakly linear operator. Then, $(X_\varphi, \llangle \cdot, \cdot \rrangle)$ is a Hilbert space if $\varphi$ is surjective. 
\end{cor}

proof.rawEnvironment:
\begin{proof}
    Since $V$ is separable, every subset of $V$ endowed with the subspace topology is separable. In particular, $\varphi(X) \subseteq V$ is separable.

    By Proposition~\ref{prop:phi-subspace}, the image $\varphi(X)$ is a subspace of $V$, and by Proposition~\ref{prop:function-kernel-quotient-injective-extension} the map $\Phi:X_\varphi \to \varphi(X)$ is bijective. Moreover, for $x_\varphi, y_\varphi \in X_\varphi$, the transported inner product satisfies
    \begin{align*}
        \llangle x_\varphi, y_\varphi \rrangle = \langle \Phi(x_\varphi), \Phi(y_\varphi)\rangle.
    \end{align*}
    Hence $\Phi$ is an isometric linear isomorphism between $(X_\varphi,\llangle \cdot,\cdot \rrangle)$ and the separable inner product space $\varphi(X)$. Therefore $(X_\varphi,\llangle \cdot,\cdot \rrangle)$ is separable.
\end{proof}

