proof.rawEnvironment:
\begin{proof}
    For simplicity, we will write $x$ instead of $x_\varphi$ and $z$ instead of $z_\varphi$. First, we verify that $\sim$ is indeed an equivalence relation. For all $(x,z),(x^\prime,z^\prime), (x^\ast, z^\ast) \in X_\varphi \times X_\varphi$, we show that 
    \begin{enumerate}
        \item $(x,z) \sim (x,z)$; 
        \item $(x,z) \sim (x^\prime, z^\prime)$ if and only if $(x^\prime, z^\prime)\sim (x,z)$; and
        \item $(x, z) \sim (x^\prime, z^\prime)$ and $(x^\prime, z^\prime) \sim (x^\ast, z^\ast)$ implies $(x, z) \sim (x^\ast, z^\ast)$.
    \end{enumerate}

    First, for all $x,z \in X_\varphi$, 
    \begin{align*}
        x+z = x+z,
    \end{align*}
    and so $(x,z) \sim (x,z)$. Thus $\sim$ is reflexive.

    Next, suppose that $(x,z) \sim (x^\prime, z^\prime)$. Then, by definition,
    \begin{align*}
        x + z^\prime = x^\prime + z.
    \end{align*}
    By symmetry of equality, this gives
    \begin{align*}
        x^\prime + z = x + z^\prime.
    \end{align*}
    Therefore $(x^\prime,z^\prime)\sim (x,z)$. The converse follows analogously, and hence $\sim$ is symmetric.

    For the third criterion, we first note that $X_\varphi$ is cancellative. Indeed, the convex cone structure on $X_\varphi$ is obtained by transporting the cone structure of $\varphi(X)\subseteq V$ along the bijection
    \begin{align*}
        \Phi:X_\varphi \to \varphi(X)\subseteq V.
    \end{align*}
    Thus, for all $a,c \in X_\varphi$, the transported addition satisfies
    \begin{align*}
        \Phi(a+c)=\Phi(a)+\Phi(c).
    \end{align*}
    Now suppose that $a+c=b+c$ in $X_\varphi$. Applying $\Phi$ yields
    \begin{align*}
        \Phi(a+c)=\Phi(b+c).
    \end{align*}
    Using the compatibility of $\Phi$ with the transported addition, we obtain
    \begin{align*}
        \Phi(a)+\Phi(c)=\Phi(b)+\Phi(c).
    \end{align*}
    Since $V$ is a vector space, addition in $V$ is cancellative, and hence
    \begin{align*}
        \Phi(a)=\Phi(b).
    \end{align*}
    By injectivity of $\Phi$, it follows that
    \begin{align*}
        a=b.
    \end{align*}
    Therefore $X_\varphi$ is cancellative. Now suppose that $(x, z) \sim (x^\prime, z^\prime)$ and $(x^\prime, z^\prime) \sim (x^\ast, z^\ast)$. Then
    \begin{align}\label{eq:non-prime-and-prime}
        x + z^\prime = x^\prime + z,
    \end{align}
    and
    \begin{align}\label{eq:prime-and-ast}
        x^\prime + z^\ast = x^\ast + z^\prime.
    \end{align}
    Using associativity and commutativity of addition in $X_\varphi$, together with equations \eqref{eq:non-prime-and-prime} and \eqref{eq:prime-and-ast}, we have
    \begin{align*}
        (x+z^\ast)+z^\prime 
        &= (x+z^\prime)+z^\ast \\
        &= (x^\prime+z)+z^\ast \\
        &= z+(x^\prime+z^\ast) \\
        &= z+(x^\ast+z^\prime) \\
        &= (x^\ast+z)+z^\prime.
    \end{align*}
    Since $X_\varphi$ is cancellative, we may cancel the common term $z^\prime$, obtaining
    \begin{align*}
        x+z^\ast = x^\ast+z.
    \end{align*}
    Therefore $(x,z)\sim (x^\ast,z^\ast)$, from which it follows that $\sim$ is transitive. Hence $\sim$ is an equivalence relation on $X_\varphi \times X_\varphi$.

    Next, we show that addition and scalar multiplication are well-defined; for addition, suppose that $(x,y) \sim (x^\prime, y^\prime)$ and $(z,w) \sim (z^\prime, w^\prime)$. We will show that the choice of representatives from the equivalence classes is irrelevant. That is, we will show that 
    \begin{align*}
        [(x + z, y + w)] = [(x^\prime + z^\prime, y^\prime + w^\prime)].
    \end{align*}
    By definition of $\sim$, we have
    \begin{align*}
        x+y^\prime = x^\prime+y
    \end{align*}
    and
    \begin{align*}
        z+w^\prime = z^\prime+w.
    \end{align*}
    We must show that
    \begin{align*}
        (x+z,y+w)\sim(x^\prime+z^\prime,y^\prime+w^\prime).
    \end{align*}
    By definition of $\sim$, this is equivalent to showing that
    \begin{align*}
        (x+z)+(y^\prime+w^\prime)
        =
        (x^\prime+z^\prime)+(y+w).
    \end{align*}
    Using associativity and commutativity of addition in $X_\varphi$, we obtain
    \begin{align*}
        (x+z)+(y^\prime+w^\prime)
        &= (x+y^\prime)+(z+w^\prime) \\
        &= (x^\prime+y)+(z^\prime+w) \\
        &= (x^\prime+z^\prime)+(y+w).
    \end{align*}
    Therefore
    \begin{align*}
        (x+z,y+w)\sim(x^\prime+z^\prime,y^\prime+w^\prime).
    \end{align*}
    Hence
    \begin{align*}
        [(x+z,y+w)]
        =
        [(x^\prime+z^\prime,y^\prime+w^\prime)].
    \end{align*}
    Thus addition is independent of the representatives chosen. Next, we show that scalar multiplication is well-defined. Suppose that
    \begin{align*}
        (x,z)\sim(x^\prime,z^\prime).
    \end{align*}
    Then by definition of $\sim$, we have
    \begin{align*}
        x+z^\prime=x^\prime+z.
    \end{align*}
    Let $\alpha\in\mathbb{R}$. We must show that
    \begin{align*}
        \alpha[(x,z)]=\alpha[(x^\prime,z^\prime)].
    \end{align*}

