    \begin{align*}
        \alpha[(x,z)] = [(\alpha x,\alpha z)]
    \end{align*}
    and
    \begin{align*}
        \alpha[(x^\prime,z^\prime)] = [(\alpha x^\prime,\alpha z^\prime)].
    \end{align*}
    Thus, it suffices to show that
    \begin{align*}
        (\alpha x,\alpha z)\sim(\alpha x^\prime,\alpha z^\prime).
    \end{align*}
