    \begin{align*}
        (\alpha x,\alpha z) \sim (\alpha x^\prime,\alpha z^\prime),
    \end{align*}
    and hence
    \begin{align*}
        [(\alpha x,\alpha z)] = [(\alpha x^\prime,\alpha z^\prime)].
    \end{align*}
