    \begin{align*}
        \alpha[(x,z)] = [(\beta z,\beta x)]
    \end{align*}
    while
    \begin{align*}
        \alpha[(x^\prime,z^\prime)] = [(\beta z^\prime,\beta x^\prime)].
    \end{align*}
