    \begin{align*}
        \beta z^\prime+\beta x
        =
        \beta z+\beta x^\prime.
    \end{align*}
    By symmetry of equality,
    \begin{align*}
        \beta z+\beta x^\prime
        =
        \beta z^\prime+\beta x.
    \end{align*}
    Therefore
    \begin{align*}
        (\beta z,\beta x)\sim(\beta z^\prime,\beta x^\prime).
    \end{align*}
    Since $\beta=|\alpha|$, this means that
    \begin{align*}
        (|\alpha|z,|\alpha|x)\sim(|\alpha|z^\prime,|\alpha|x^\prime),
    \end{align*}
    and hence
    \begin{align*}
        [(\left|\alpha\right|z,\left|\alpha\right|x)]
        =
        [(\left|\alpha\right|z^\prime,\left|\alpha\right|x^\prime)].
    \end{align*}
    So scalar multiplication is independent of representatives when $\alpha<0$.

    We now proceed to show that $(\mathscr{V}(X, \varphi), +, \cdot)$ is a real vector space. To do so, we define the auxiliary map $T:\mathscr{V}(X, \varphi) \to \mathrm{span}~\varphi(X)$ by 
    \begin{align*}
        T([(x,z)]) \overset{\mathrm{def}}{=} \Phi(x) - \Phi(z).
    \end{align*}
    First, let us verify that $T$ is well-defined. Note that 
    \begin{align*}
        [(x,z)] &= \{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid x + z^\prime = z + x^\prime\}\\
        &=\{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid \Phi(x) + \Phi(z^\prime) = \Phi(z) + \Phi(x^\prime)\}\\
        &=\{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid \Phi(x) - \Phi(z) = \Phi(x^\prime) - \Phi(z^\prime)\}.
    \end{align*}
    Hence, $T$ is well-defined, as its value is constant on each equivalence class. Moreover, $\Phi(x)-\Phi(z)\in \mathrm{span}~\varphi(X)$ by construction. We now claim that $T$ is a bijection. Injectivity follows from the property that if
    \begin{align*}
        T([(x,z)]) = \Phi(x) - \Phi(z) = \Phi(x^\prime) - \Phi(z^\prime) = T([(x^\prime, z^\prime)]) 
    \end{align*}
    then $(x,z) \sim (x^\prime, z^\prime)$ and so $[(x,z)] = [(x^\prime,z^\prime)]$. For surjectivity, let $v \in \mathrm{span}\,\varphi(X)$ and write
    \begin{align*}
        v = \sum_{i=1}^n \alpha_i \varphi(u_i),
    \end{align*}
    for $(u_i)_{i=1}^n \subseteq X$ and $(\alpha_i)_{i=1}^n \subseteq \mathbb{R}$. Define 
    \begin{align*}
        \alpha^+_i =\max(\alpha_i, 0), \quad \alpha^-_i =-\min(\alpha_i, 0),
    \end{align*}
    and set 
    \begin{align*}
        v^+ = \sum_{i=1}^n \alpha^+_i \varphi(u_i), \quad v^- = \sum_{i=1}^n \alpha^-_i \varphi(u_i).
    \end{align*}
    Since $\varphi(X)$ is a convex cone, and hence, by induction on $n$, closed under non-negative combinations of $n$ elements, and $\Phi : X_\varphi \to \varphi(X)$ is bijective, there exist $x,z \in X_\varphi$ such that $\Phi(x)=v^+$ and $\Phi(z)=v^-$. By construction,
    \begin{align*}
        T([(x,z)]) = v^+ - v^- = v,
    \end{align*}
    so $T$ is surjective.

    We now claim that
    \begin{align*}
        T([(x,z)] + [(x^\prime, z^\prime)]) = T([(x,z)]) + T([(x^\prime, z^\prime)])
    \end{align*}
    and 
    \begin{align*}
        T(\alpha [(x, z)]) = \alpha T([(x,z)]).
    \end{align*}
    Indeed, 
    \begin{align*}
        T([(x,z)] + [(x^\prime, z^\prime)]) &= T([(x + x^\prime, z + z^\prime)])\\
        &= \Phi(x + x^\prime) - \Phi(z + z^\prime) \\ 
        &= \Phi(\Phi^{-1}(\Phi(x) + \Phi(x^\prime))) - \Phi(\Phi^{-1}(\Phi(z) + \Phi(z^\prime)))\\
        &= \Phi(x) - \Phi(z) + \Phi(x^\prime) - \Phi(z^\prime)\\
        &= T([(x,z)]) + T([(x^\prime, z^\prime)]),
    \end{align*}
    and 
    \begin{align*}
        T(\alpha [(x, z)]) = \begin{cases}
            T([(\alpha x, \alpha z)]) & \alpha \geq 0,\\ 
            T([(|\alpha| z, |\alpha| x)]) & \alpha < 0.
        \end{cases}
    \end{align*}
    For the case $\alpha \geq 0$ notice that 
    \begin{align*}
        T([(\alpha x, \alpha z)]) &= \Phi(\alpha x) - \Phi(\alpha z)\\
        &= \alpha \Phi(x) - \alpha \Phi(z) \\
        &= \alpha T([(x,z)]). 
    \end{align*}
    Likewise, the case $\alpha < 0$ yields 
    \begin{align*}
        T([(|\alpha| z, |\alpha| x)]) &= \Phi(|\alpha| z) - \Phi(|\alpha| x)\\
        &=|\alpha| \Phi(z) - |\alpha| \Phi(x)\\
        &=-\alpha \Phi(z) + \alpha \Phi(x)\\
        &=\alpha T([(x,z)]),
    \end{align*}
    by commutativity in $\mathrm{span}~\varphi(X)$. As $\mathrm{span} ~\varphi(X)$ is naturally a vector space, the claim follows via the bijection $T$ and the fact that $T$ preserves the algebraic structure.
\end{proof}

