        &= \beta(x^\prime+z) \\
        &= \beta x^\prime+\beta z.
    \end{align*}
    Using commutativity of addition in $X_\varphi$, this gives
    \begin{align*}
        \beta z^\prime+\beta x
        =
        \beta z+\beta x^\prime.
    \end{align*}
    By symmetry of equality,
    \begin{align*}
        \beta z+\beta x^\prime
        =
        \beta z^\prime+\beta x.
    \end{align*}
    Therefore
    \begin{align*}
        (\beta z,\beta x)\sim(\beta z^\prime,\beta x^\prime).
    \end{align*}
    Since $\beta=|\alpha|$, this means that
    \begin{align*}
        (|\alpha|z,|\alpha|x)\sim(|\alpha|z^\prime,|\alpha|x^\prime),
    \end{align*}
    and hence
    \begin{align*}
        [(\left|\alpha\right|z,\left|\alpha\right|x)]
        =
        [(\left|\alpha\right|z^\prime,\left|\alpha\right|x^\prime)].
    \end{align*}
    So scalar multiplication is independent of representatives when $\alpha<0$.

    We now proceed to show that $(\mathscr{V}(X, \varphi), +, \cdot)$ is a real vector space. To do so, we define the auxiliary map $T:\mathscr{V}(X, \varphi) \to \mathrm{span}~\varphi(X)$ by 
    \begin{align*}
