\label{thm:grothendieck-vector-space-from-convex-cone}\index{Grothendieck vectorisation}
    Let $X$ be a non-empty set, $V$ a real vector space, and $\varphi :X \to V$ a weakly convex operator. Endow $X_\varphi$ with the convex cone structure of Corollary~\ref{cor:weak-convex-transport-convex-cone-structure}. Define the relation $\sim$ on $X_\varphi \times X_\varphi$ by 
    \begin{align*}
        (x_\varphi, z_\varphi) \sim (x^\prime_\varphi, z^\prime_\varphi) \iff x_\varphi + z^\prime_\varphi = x^\prime_\varphi + z_\varphi,
    \end{align*}
    and let $\mathscr{V}(X, \varphi)$ denote the quotient set $(X_\varphi \times X_\varphi)/{\sim}$. Define addition $+:\mathscr{V}(X,\varphi) \times \mathscr{V}(X,\varphi) \to \mathscr{V}(X,\varphi)$ and scalar multiplication $\cdot : \mathbb{R} \times \mathscr{V}(X, \varphi) \to \mathscr{V}(X,\varphi)$ by 
    \begin{align*}
        [(x_\varphi,z_\varphi)] + [(x^\prime_\varphi, z^\prime_\varphi)] = [(x_\varphi + x^\prime_\varphi, z_\varphi + z^\prime_\varphi)],
    \end{align*}
    and 
    \begin{align*}
        \alpha [(x_\varphi,z_\varphi)] = \begin{cases}
            [(\alpha x_\varphi, \alpha z_\varphi)], & \text{if }\alpha \geq 0,\\ 
            [(|\alpha| z_\varphi, |\alpha| x_\varphi)], & \text{if }\alpha < 0.
        \end{cases}
    \end{align*}
    Then $(\mathscr{V}(X,\varphi), +, \cdot)$ is a real vector space.

