\begin{cor}\label{thm:grothendieck-vectorization-is-span}
    Let $X$ be a non-empty set, $V$ a real vector space, and $\varphi : X \to V$ a weakly convex operator. Then, 
    \begin{align*}
        \mathscr{V}(X, \varphi) \cong \mathrm{span}~\varphi(X).
    \end{align*}
    More precisely, the mapping 
    \begin{align*}
        T &: \mathscr{V}(X,\varphi) \to \mathrm{span}~\varphi(X)\\
        [(x_\varphi,z_\varphi)] & \mapsto \Phi(x_\varphi) - \Phi(z_\varphi)
    \end{align*}
    is a linear isomorphism. 
\end{cor}

