\begin{cor}\label{cor:grothendieck-vectorization-inner-product-space}
    Let $X$ be a non-empty set, $(V, \langle \cdot, \cdot \rangle)$ a real inner product space, and $\varphi : X \to V$ a weakly convex operator. Let $T:\mathscr{V}(X,\varphi) \to \mathrm{span}~\varphi(X)$ be the linear isomorphism 
    \begin{align*}
        T([(x_\varphi,z_\varphi)]) = \Phi(x_\varphi) - \Phi(z_\varphi).
    \end{align*}
    Endow $\mathscr{V}(X,\varphi)$ with the bilinear form $\llangle \cdot, \cdot \rrangle_{\mathscr{V}} :\mathscr{V}(X,\varphi) \times \mathscr{V}(X,\varphi) \to \mathbb{R}$ defined by
    \begin{align*}
        \llangle [(x_\varphi,z_\varphi)], [(x^\prime_\varphi, z^\prime_\varphi)] \rrangle_{\mathscr{V}} &= \langle T([(x_\varphi,z_\varphi)]), T([(x^\prime_\varphi, z^\prime_\varphi)])\rangle \\ &= \langle \Phi(x_\varphi) - \Phi(z_\varphi), \Phi(x^\prime_\varphi) - \Phi(z^\prime_\varphi) \rangle. 
    \end{align*}
    Then $(\mathscr{V}(X,\varphi), \llangle \cdot, \cdot \rrangle_{\mathscr{V}})$ is an inner product space, and $T$ is an isometric linear isomorphism. In addition,
    \begin{enumerate}
        \item The completion of $\mathscr{V}(X,\varphi)$ and the completion of $\mathrm{span}~\varphi(X)$ are isometrically isomorphic. 
        \item The operator $T$ extends to a linear isometric isomorphism between the completion of $\mathscr{V}(X,\varphi)$ and the completion of ${\mathrm{span}~\varphi(X)}$. 
        \item The map $x_\varphi\mapsto[(x_\varphi,0_\varphi)]$, where $0_\varphi$ denotes the cone zero induced by the transported cone structure, is an isometric embedding of the convex cone $X_\varphi$ into $\mathscr{V}(X,\varphi)$; here $X_\varphi$ carries the metric $(x_\varphi,x^\prime_\varphi)\mapsto\lVert\Phi(x_\varphi)-\Phi(x^\prime_\varphi)\rVert$ pulled back from $V$. The closure of the embedded image is a closed convex cone in the completion of $\mathscr{V}(X,\varphi)$.
        \item There is a unique metric projection from the completion of $\mathscr{V}(X,\varphi)$ onto the closure of the embedded cone.
    \end{enumerate}
\end{cor}

