\begin{defn}[Supply and Demand Curves of a Market State]\label{defn:supply-and-demand-curves}
    Let $\mathcal{P}=[-500,\overline{p}]\subset\mathbb{R}$ be a compact interval, let $O=\mathcal{P}\times[0,\infty)\times\{\mathrm{buy},\mathrm{sell}\}$, and let $\bm{m}\in\mathscr{T}(O)$ be a market state with sorted sell tuple $\bm{s}=(\bm{p}^{\bm{s}}(i),\bm{q}^{\bm{s}}(i))_{i=1}^{\ell(\bm{s})}$ and sorted buy tuple $\bm{b}=(\bm{p}^{\bm{b}}(j),\bm{q}^{\bm{b}}(j))_{j=1}^{\ell(\bm{b})}$. Set $\bm{p}^{\bm{s}}(0)=-500$, $\bm{p}^{\bm{b}}(0)=\overline{p}$, $\bm{Q}^{\bm{s}}(i)=\sum_{k=1}^i\bm{q}^{\bm{s}}(k)$ for $i\in\{0,\dots,\ell(\bm{s})\}$, $\bm{Q}^{\bm{b}}(j)=\sum_{k=1}^j\bm{q}^{\bm{b}}(k)$ for $j\in\{0,\dots,\ell(\bm{b})\}$, $s_*=\bm{Q}^{\bm{s}}(\ell(\bm{s}))$, and $b_*=\bm{Q}^{\bm{b}}(\ell(\bm{b}))$. If $\bm{s}$ is non-empty, the \emph{supply curve} $S^{\bm{m}}:[0,s_*]\to\mathcal{P}$ is defined by $S^{\bm{m}}(0)=-500$ and
    \begin{align*}
        S^{\bm{m}}(q) = \frac{(\bm{Q}^{\bm{s}}(i)-q)\,\bm{p}^{\bm{s}}(i-1)+(q-\bm{Q}^{\bm{s}}(i-1))\,\bm{p}^{\bm{s}}(i)}{\bm{Q}^{\bm{s}}(i)-\bm{Q}^{\bm{s}}(i-1)},
        \quad \bm{Q}^{\bm{s}}(i-1)<q\leq\bm{Q}^{\bm{s}}(i),
    \end{align*}
    for each $i\in\{1,\dots,\ell(\bm{s})\}$ with $\bm{q}^{\bm{s}}(i)>0$. Likewise, if $\bm{b}$ is non-empty, the \emph{demand curve} $D^{\bm{m}}:[0,b_*]\to\mathcal{P}$ is defined by $D^{\bm{m}}(0)=\overline{p}$ and
    \begin{align*}
        D^{\bm{m}}(q) = \frac{(\bm{Q}^{\bm{b}}(j)-q)\,\bm{p}^{\bm{b}}(j-1)+(q-\bm{Q}^{\bm{b}}(j-1))\,\bm{p}^{\bm{b}}(j)}{\bm{Q}^{\bm{b}}(j)-\bm{Q}^{\bm{b}}(j-1)},
        \quad \bm{Q}^{\bm{b}}(j-1)<q\leq\bm{Q}^{\bm{b}}(j),
    \end{align*}
    for each $j\in\{1,\dots,\ell(\bm{b})\}$ with $\bm{q}^{\bm{b}}(j)>0$.
\end{defn}

