\begin{defn}[Crossing Price, Equilibrium Quantity, and Equilibrium Operator]\label{defn:crossing-price-and-equilibrium-operator}
    Let $\bm{m}\in\mathscr{T}(O)$ be a market state with supply curve $S^{\bm{m}}:[0,s_*]\to\mathcal{P}$, demand curve $D^{\bm{m}}:[0,b_*]\to\mathcal{P}$, and level sets $J_{\bm{m}}(q)\subseteq\mathcal{P}$ for $q\in[-b_*,s_*]$. The \emph{crossing price} of $\bm{m}$ is defined by
    \begin{align*}
        P(\bm{m})=\frac{1}{2}\bigl(\min J_{\bm{m}}(0)+\max J_{\bm{m}}(0)\bigr),
    \end{align*}
    and the \emph{equilibrium quantity} of $\bm{m}$ is defined by
    \begin{align*}
        Q(\bm{m})=\max\bigl(\{0\}\cup\{q\in(0,\min(s_*,b_*)]\mid S^{\bm{m}}(q)\leq P(\bm{m})\leq D^{\bm{m}}(q)\}\bigr).
    \end{align*}
    The \emph{equilibrium operator} is the map
    \begin{align*}
        \mathcal{E} : \mathscr{T}(O) &\to \mathbb{R} \times [0,\infty)\\
        \bm{m} &\mapsto (P(\bm{m}), Q(\bm{m})).
    \end{align*}
\end{defn}

