\begin{prop}[Properties of the Price-Impact Curve]\label{prop:price-impact-curve-properties}
    Let $\bm{m}\in\mathscr{M}_+$ be a positively matched market state with total sell volume $s_*$, total buy volume $b_*$, available-depth interval $D_{\bm{m}}=[-b_*,s_*]$, and price-impact curve $P_{\bm{m}}:D_{\bm{m}}\to\mathcal{P}$. Then $P_{\bm{m}}$ has the following properties.
\begin{enumerate}[(i)]
    \item $\operatorname{domain}(P_{\bm{m}})=D_{\bm{m}}=[-b_*,s_*]$.\label{claim:compact-dom}
    \item The function $P_{\bm{m}}$ is piecewise affine over finitely many disjoint intervals, some of which may be singletons.\label{claim:pw-affine}
    \item The function $P_{\bm{m}}$ is increasing (that is, non-decreasing). \label{claim:increasing}
    \item $0 \in \mathrm{domain}(P_{\bm{m}})$. \label{claim:zero-is-contained}
\end{enumerate}
\end{prop}

