\begin{defn}[Space of Price Curves and Simple Price Curves]\label{defn:space-of-price-curves}
    The \emph{space of price curves} is defined by
    \begin{align*}
        \mathpzc{P}
        =
        \bigcup_{\substack{a,b \in \mathbb{R}\\ a\leq 0\leq b}}
        \{f:[a,b] \to \mathbb{R}\mid f\text{ is increasing and piecewise affine}\},
    \end{align*}
    where \emph{increasing} means non-decreasing, and \emph{piecewise affine} means affine on each of finitely many pairwise disjoint intervals, singletons included. A price curve $f\in\mathpzc{P}$ is called \emph{simple} if it is constant on each of these intervals.
\end{defn}

