\begin{defn}[Admissible Parametrisation Operator]\label{defn:admissible-price-curve-parametrisation}
    Let $\mathpzc{P}$ be the space of price curves of Definition~\ref{defn:space-of-price-curves}, and for each $f\in\mathpzc{P}$, let $\Gamma(f)=\{(x,f(x))\mid x\in\mathrm{domain}(f)\}\subseteq\mathbb{R}^2$ denote its graph. Let $\Theta$ be an operator from $\mathpzc{P}$ to $\mathcal{L}^2([-1,1]; \mathbb{R}^2)$ such that, for each $f \in \mathpzc{P}$,
    \begin{align*}
        \Theta f \equiv \Theta(f) : [-1, 1] \to \Gamma(f),
    \end{align*}
    and suppose that
    \begin{align*}
        \Theta f(t) = (\vartheta_f(t), (f \circ \vartheta_f)(t))
    \end{align*}
    for an increasing, continuous, and surjective function $\vartheta_f : [-1,1] \to \mathrm{domain}(f)$ satisfying $\vartheta_f(0) = 0$. We call $\Theta$ an \emph{admissible parametrisation operator} and $\vartheta_f$ the parametriser of $f$.
\end{defn}

