\begin{defn}[Linear Parametrisation Operator]\label{defn:linear-parametrisation-operator}
    Let $\mathpzc{P}$ be the space of price curves. For each $f\in\mathpzc{P}$ with $\mathrm{domain}(f)=[l_f,r_f]$, the \emph{volume-proportional (linear) parametrisation} $\lambda_f:[-1,1]\to[l_f,r_f]$ is defined by
    \begin{align*}
        \lambda_f(u)=
        \begin{cases}
            -l_f u & u\in[-1,0),\\
            \phantom{-}r_f u & u\in[0,1].
        \end{cases}
    \end{align*}
    The pointwise and Hilbert-valued \emph{linear parametrisation operators} $\Lambda:\mathpzc{P}\to\mathcal{L}^2([-1,1];\mathbb{R}^2)$ and $\overline{\Lambda}:\mathpzc{P}\to L^2([-1,1];\mathbb{R}^2)$ are defined for each $f\in\mathpzc{P}$ and $u\in[-1,1]$ by
    \begin{align*}
        \Lambda(f)(u)
        &=\bigl(\lambda_f(u),f(\lambda_f(u))\bigr),\\
        \overline{\Lambda}(f)
        &=[\Lambda(f)]\in L^2([-1,1];\mathbb{R}^2).
    \end{align*}
\end{defn}

