\begin{defn}[Sided Essential Decomposition and Inducing Knots]\label{defn:sided-essential-decomposition}\index{sided decomposition}
    Let $f\in\mathpzc{P}$ be a simple price curve with minimal representation \eqref{eq:minimal-representation} and cells and levels $(I_i,f_i)_{i=1}^n$. Define the negative-side and positive-side cell counts by
    \begin{align*}
        L_f
        &=\left|\left\{i\in\{1,\dots,n\}\mid I_i\cap(-\infty,0)\neq\emptyset\right\}\right|,\\
        U_f
        &=\left|\left\{i\in\{1,\dots,n\}\mid I_i\cap(0,\infty)\neq\emptyset\right\}\right|,
    \end{align*}
    and index the cells and levels relative to zero by setting
    \begin{align*}
        V_j&=
        \begin{cases}
            I_{j+L_f+1}\cap(-\infty,0) & j\in\{-L_f,\dots,-1\},\\
            \{0\} & j=0,\\
            I_{n-U_f+j}\cap(0,\infty) & j\in\{1,\dots,U_f\},
        \end{cases}\\
        g_j&=
        \begin{cases}
            f_{j+L_f+1} & j\in\{-L_f,\dots,-1\},\\
            f(0) & j=0,\\
            f_{n-U_f+j} & j\in\{1,\dots,U_f\}.
        \end{cases}
    \end{align*}
    The family $(V_j,g_j)_{j=-L_f}^{U_f}$, which satisfies
    \begin{align*}
        f(x)=\sum_{j=-L_f}^{U_f}g_j\mathbbm{1}_{V_j}(x),
    \end{align*}
    is called the \emph{sided essential decomposition} of $f$. The \emph{inducing knots} $(x_j,u_j)_{j=-L_f}^{U_f}$ are defined by
    \begin{align}\label{eq:inducing-points}
        x_j&=
        \begin{cases}
            \inf V_j & j<0,\\
            0 & j=0,\\
            \sup V_j & j>0,
        \end{cases}\\
        u_j&=
        \begin{cases}
            j/L_f & j\in\{-L_f,\dots,-1\},\\
            0 & j=0,\\
            j/U_f & j\in\{1,\dots,U_f\},
        \end{cases}
    \end{align}
    where the corresponding case involving division is understood to be empty when $L_f=0$ or $U_f=0$. Finally, the \emph{sided parametriser} $\psi_f:[-1,1]\to\mathrm{domain}(f)$ is the function that interpolates the knots $(u_j,x_j)$ linearly and vanishes on any side whose count is zero.
\end{defn}

