\begin{defn}[Family of Graph-Tracing Pairs]\label{defn:graph-tracing-pairs}
    The \emph{family of graph-tracing pairs}, denoted by $\mathcal{A}\subseteq\mathcal{L}^2([-1,1];\mathbb{R}^2)$, consists of all pairs $(q,p)\in\mathcal{L}^2([-1,1];\mathbb{R}^2)$ such that
    \begin{enumerate}
        \item $q$ is continuous, increasing, and piecewise affine, and satisfies $q(0)=0$;
        \item $p$ is increasing and piecewise affine;
        \item $q(u)=q(v)$ implies $p(u)=p(v)$ for all $u,v\in[-1,1]$; and
        \item $p$ is right-continuous on $[-1,1)$ and, writing $\tau_q=\inf q^{-1}(\{q(1)\})$, satisfies $p(\tau_q)=\lim_{u\uparrow\tau_q}p(u)$ whenever $\tau_q>-1$.
    \end{enumerate}
\end{defn}

environments.statement:
\label{defn:graph-tracing-pairs}
    The \emph{family of graph-tracing pairs}, denoted by $\mathcal{A}\subseteq\mathcal{L}^2([-1,1];\mathbb{R}^2)$, consists of all pairs $(q,p)\in\mathcal{L}^2([-1,1];\mathbb{R}^2)$ such that
    \begin{enumerate}
        \item $q$ is continuous, increasing, and piecewise affine, and satisfies $q(0)=0$;
        \item $p$ is increasing and piecewise affine;
        \item $q(u)=q(v)$ implies $p(u)=p(v)$ for all $u,v\in[-1,1]$; and
        \item $p$ is right-continuous on $[-1,1)$ and, writing $\tau_q=\inf q^{-1}(\{q(1)\})$, satisfies $p(\tau_q)=\lim_{u\uparrow\tau_q}p(u)$ whenever $\tau_q>-1$.
    \end{enumerate}

proof.rawEnvironment:
\begin{proof}
    We must show first that for all $(q_f,p_f),(q_g,p_g)\in\mathcal{A}$ and all $\alpha,\beta\geq0$, the linear combination $\alpha(q_f,p_f)+\beta(q_g,p_g)$ belongs to $\mathcal{A}$, and second that for every $(q,p)\in\mathcal{A}$, the formula \eqref{eq:graph-wise-decoder} defines a unique element $D(q,p)\in\mathpzc{P}$ on $\mathrm{image}(q)$.

    Let $(q_f,p_f),(q_g,p_g)\in\mathcal{A}$ and $\alpha,\beta\geq0$ be given, and set
    \begin{align*}
        q=\alpha q_f+\beta q_g,
        \qquad
        p=\alpha p_f+\beta p_g.
    \end{align*}
    Then $q$ is continuous and increasing with $q(0)=0$, the functions $q$ and $p$ are affine on the cells of a common finite partition of $[-1,1]$, and $p$ is increasing. Right-continuity on $[-1,1)$ is preserved under non-negative linear combinations. Moreover, the terminal plateau of $q$ begins at the latest terminal-plateau start among the components with a strictly positive coefficient. At that point, components with an earlier start are already constant and the remaining components satisfy their left-limit condition, so $p$ satisfies condition~(4) of Definition~\ref{defn:graph-tracing-pairs} as well. To verify condition~(3), suppose that $u,v\in[-1,1]$ satisfy $u<v$ and $q(u)=q(v)$. Then
    \begin{align*}
        0
        =q(v)-q(u)
        =\alpha\bigl(q_f(v)-q_f(u)\bigr)
        +\beta\bigl(q_g(v)-q_g(u)\bigr).
    \end{align*}
    As in the proof of Proposition~\ref{prop:linear-parametrisation-convex}, every component with a strictly positive coefficient is constant on $[u,v]$, and hence $p(u)=p(v)$. Consequently, $(q,p)\in\mathcal{A}$, which proves that $\mathcal{A}$ is a convex cone.

    For the second claim, let $(q,p)\in\mathcal{A}$ be given. Because $p$ takes the same value at every pair $u,v\in[-1,1]$ satisfying $q(u)=q(v)$, the rule \eqref{eq:graph-wise-decoder} is well-defined on $\mathrm{image}(q)$. Since $q$ and $p$ are increasing, the decoded function $D(q,p)$ is increasing. Furthermore, $D(q,p)$ is affine on the image of every cell on which $q$ is not constant, so it is piecewise affine, and it is simple whenever $p$ is simple. It inherits the one-sided continuity convention chosen at the start of this section from condition~(4) on $p$, and its graph is exactly $\mathrm{image}(u\mapsto(q(u),p(u)))$, which establishes uniqueness, as desired.
\end{proof}

environments.rawEnvironment:
\begin{prop}[Graph-wise Convexity]\label{prop:admissible-parametrisations-cone}
    Let $\mathcal{A}\subseteq\mathcal{L}^2([-1,1];\mathbb{R}^2)$ be the family of graph-tracing pairs of Definition~\ref{defn:graph-tracing-pairs}, and let $\mathpzc{P}$ be the space of price curves. Then $\mathcal{A}$ is a convex cone, and there is a well-defined \emph{graph-wise decoder} $D:\mathcal{A}\to\mathpzc{P}$ that assigns to each $(q,p)\in\mathcal{A}$ a unique curve $D(q,p)\in\mathpzc{P}$ on $\mathrm{image}(q)$ via
    \begin{align}\label{eq:graph-wise-decoder}
        D(q,p)(x)
        =p(u)\qquad\text{for any }u\in[-1,1]\text{ such that }q(u)=x.
    \end{align}
\end{prop}

environments.statement:
\label{prop:admissible-parametrisations-cone}
    Let $\mathcal{A}\subseteq\mathcal{L}^2([-1,1];\mathbb{R}^2)$ be the family of graph-tracing pairs of Definition~\ref{defn:graph-tracing-pairs}, and let $\mathpzc{P}$ be the space of price curves. Then $\mathcal{A}$ is a convex cone, and there is a well-defined \emph{graph-wise decoder} $D:\mathcal{A}\to\mathpzc{P}$ that assigns to each $(q,p)\in\mathcal{A}$ a unique curve $D(q,p)\in\mathpzc{P}$ on $\mathrm{image}(q)$ via
    \begin{align}\label{eq:graph-wise-decoder}
        D(q,p)(x)
        =p(u)\qquad\text{for any }u\in[-1,1]\text{ such that }q(u)=x.
    \end{align}

environments.rawEnvironment:
\begin{exmp}\label{exmp:sided-average-not-canonical}
    Consider the increasing simple curves
    \begin{align*}
        f:[0,2]&\to\mathbb{R},
        &f(x)&=
        \begin{cases}
            0 & 0\leq x<1,\\
            2 & 1\leq x\leq2,
        \end{cases}\\
        g:[0,3]&\to\mathbb{R},
        &g(x)&=
        \begin{cases}
            0 & 0\leq x<1,\\
            1 & 1\leq x<2,\\
            3 & 2\leq x\leq3.
        \end{cases}
    \end{align*}
    On $[0,1]$, the sided parametrising functions are $\psi_f(u)=2u$ and $\psi_g(u)=3u$. Hence the first component of the pointwise average
    \begin{align*}
        z=\frac{1}{2}\Psi(f)+\frac{1}{2}\Psi(g)
    \end{align*}
    is
    \begin{align*}
        q(u)=\frac{5}{2}u.
    \end{align*}
    The second component has four levels and changes at
    \begin{align*}
        u=\frac{1}{3},\qquad u=\frac{1}{2},\qquad u=\frac{2}{3}.
    \end{align*}
    The pair $z$ belongs to $\mathcal{A}$. Its decoded curve $h$ has four blocks on $[0,5/2]$, with endpoints
    \begin{align*}
        \frac{5}{6},\qquad \frac{5}{4},\qquad \frac{5}{3},\qquad \frac{5}{2}.
    \end{align*}
    Because $h$ has four positive-side blocks, its canonical sided parametrisation assigns its first endpoint $5/6$ to parameter value $1/4$. Consequently,
    \begin{align*}
        \psi_h\left(\frac{1}{4}\right)=\frac{5}{6},
        \qquad
        q\left(\frac{1}{4}\right)=\frac{5}{8}.
    \end{align*}
    Thus $\Psi(h)\neq z$. Since $z$ traces the graph of the uniquely decoded curve $h$, it cannot equal $\Psi(k)$ for any other $k\in\mathpzc{P}$. Therefore $z\notin\Psi(\mathpzc{P})$.

    We must also rule out equality after passage to $L^2$ equivalence classes. Suppose, to the contrary, that $\overline{\Psi}(k)=[z]$ for some $k\in\mathpzc{P}$. The first components $\psi_k$ and $q$ are continuous and equal almost everywhere, and are therefore equal everywhere. On $[0,1]$, the function $q$ is strictly increasing. Equality of the second components almost everywhere therefore implies that $k$ has the same four positive-length blocks and the same block endpoints as $h$. Its block-based sided parametriser must consequently satisfy
    \begin{align*}
        \psi_k\left(\frac{1}{4}\right)=\frac{5}{6}.
    \end{align*}
    This contradicts $\psi_k=q$ and $q(1/4)=5/8$. Hence $[z]\notin\overline{\Psi}(\mathpzc{P})$, so the Hilbert-valued image is not convex either.
\end{exmp}

