\begin{defn}[Expected Value; \citealp{hsing2015theoretical}]\label{defn:expected-hilbert}\index{expected value}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, and let $X : \Omega \to \mathcal{H}$ be a random element with $\mathbb{E}[\lVert X\rVert] < \infty$. Then the expected value of $X$ is given by the Bochner integral
    \begin{align*}
        \mathbb{E}[X] = \int_\Omega X \, \mathrm{d}\mathbb{P}.
    \end{align*}
\end{defn}

