\begin{defn}[Tensor Product; \citealp{hsing2015theoretical}]\label{defn:tensor-product}
    Let $(\mathcal{H}, \langle \cdot, \cdot \rangle)$ be a real separable Hilbert space. Define $\otimes:\mathcal{H} \times \mathcal{H} \to \mathcal{L}(\mathcal{H})$ by
    \begin{align*}
        (u \otimes v)(w) = \langle u, w\rangle v.
    \end{align*}
\end{defn}

