\begin{defn}[Covariance Operator; \citealp{hsing2015theoretical}]\label{defn:covariance-operator}\index{covariance operator}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, and let $X : \Omega \to \mathcal{H}$ be a random element for which $\mathbb{E}[\lVert X\rVert^2] < \infty$, with mean $\mu = \mathbb{E}[X]$. Then the covariance operator of $X$ is the Bochner integral in $\mathcal{L}(\mathcal{H})$ given by
    \begin{align*}
        \mathbb{E}[(X - \mu) \otimes (X - \mu)] = \int_\Omega (X - \mu) \otimes (X - \mu) \, \mathrm{d}\mathbb{P}.
    \end{align*}
\end{defn}

