\begin{thm}[Spectral Theorem]\label{thm:spectral-thm}
    Let $(\mathcal{H}, \langle \cdot, \cdot \rangle)$ be a real separable Hilbert space and let $A\in\mathcal{L}(\mathcal{H})$ be self-adjoint and compact. Then there exists a finite or countable orthonormal eigenbasis $(e_n)_{n \in I}$ for $\overline{\mathrm{image}(A)}$ such that
    \begin{align*}
        A = \sum_{n \in I} \lambda_n e_n \otimes e_n,
    \end{align*}
    with convergence in operator norm when $I$ is infinite. Each element $e_n$ is called an eigenvector of $A$, and the corresponding $\lambda_n \in \mathbb{R}$ is called the eigenvalue associated with $e_n$.
\end{thm}

environments.statement:
\label{thm:spectral-thm}
