\begin{thm}[Law of Large Numbers and Central Limit Theorem for the Mean; \citealp{hsing2015theoretical}]\label{thm:lln-clt-mean}\index{law of large numbers}\index{central limit theorem}
    Let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, and let $X:\Omega \to \mathcal{H}$ be a random element with $\mathbb{E}[\lVert X\rVert] < \infty$ and mean $\mu$. Moreover, let $(X_i)_{i \in \mathbb{N}}$ be independent copies of $X$. Then, as $n \to \infty$,
    \begin{align}
        \frac{1}{n} \sum_{i=1}^n X_i \overset{\text{a.s.}}{\to} \mu.
    \end{align}
    Further, if $\mathbb{E}[\lVert X\rVert^2] < \infty$, then as $n \to \infty$,
    \begin{align}
        \sqrt{n}\left(\frac{1}{n} \sum_{i=1}^n X_i - \mu\right) \overset{d}{\to} \xi,
    \end{align}
    where $\xi$ is an $\mathcal{H}$-valued Gaussian random element with mean $0$ and covariance operator $\Sigma=\mathbb{E}[(X - \mu) \otimes (X - \mu)]$; that is, $\langle\xi,u\rangle$ is normally distributed with mean $0$ and variance $\langle\Sigma u,u\rangle$ for every $u\in\mathcal{H}$.
\end{thm}

environments.statement:
\label{thm:lln-clt-mean}\index{law of large numbers}\index{central limit theorem}
    Let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, and let $X:\Omega \to \mathcal{H}$ be a random element with $\mathbb{E}[\lVert X\rVert] < \infty$ and mean $\mu$. Moreover, let $(X_i)_{i \in \mathbb{N}}$ be independent copies of $X$. Then, as $n \to \infty$,
    \begin{align}
        \frac{1}{n} \sum_{i=1}^n X_i \overset{\text{a.s.}}{\to} \mu.
    \end{align}
    Further, if $\mathbb{E}[\lVert X\rVert^2] < \infty$, then as $n \to \infty$,
    \begin{align}
        \sqrt{n}\left(\frac{1}{n} \sum_{i=1}^n X_i - \mu\right) \overset{d}{\to} \xi,
    \end{align}
    where $\xi$ is an $\mathcal{H}$-valued Gaussian random element with mean $0$ and covariance operator $\Sigma=\mathbb{E}[(X - \mu) \otimes (X - \mu)]$; that is, $\langle\xi,u\rangle$ is normally distributed with mean $0$ and variance $\langle\Sigma u,u\rangle$ for every $u\in\mathcal{H}$.

environments.rawEnvironment:
\begin{thm}[Law of Large Numbers for the Covariance; \citealp{hsing2015theoretical}]\label{thm:lln-covariance}
    Let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, let $X:\Omega \to \mathcal{H}$ be a random element with $\mathbb{E}[\lVert X\rVert^2] < \infty$, and let $(X_i)_{i \in \mathbb{N}}$ be independent copies of $X$. Write $\mu = \mathbb{E}[X]$ and, for $n\geq2$,
    \begin{align*}
        \bar{X}_n = \frac{1}{n} \sum_{i=1}^n X_i.
    \end{align*}
    Then, as $n \to \infty$,
    \begin{align}\label{eq:covariance-operator-estimate}
        \frac{1}{n-1}\sum_{i=1}^n (X_i - \bar{X}_n) \otimes (X_i - \bar{X}_n) \overset{\text{a.s.}}{\to}  \mathbb{E}[(X - \mu) \otimes (X - \mu)]
    \end{align}
    in operator norm.
\end{thm}

