\begin{thm}[Hilbert-Space Regression Theorem]\label{thm:regression-theorem}\index{Hilbert space regression}
    Let $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space, let $(\mathcal{H}, \langle \cdot, \cdot \rangle)$ be a real separable Hilbert space, and let $\mathcal{G} \subseteq \mathcal{F}$ be a sub-$\sigma$-algebra. For every random element $X:\Omega \to \mathcal{H}$ with $\mathbb{E}[\lVert X\rVert^2] < \infty$,
    \begin{align*}
        \mathbb{E}[X \mid \mathcal{G}] \in \argmin_{U \in L^2(\Omega, \mathcal{G}, \mathbb{P}; \mathcal{H})} \mathbb{E}[\lVert X - U\rVert^2],
    \end{align*}
    where the minimisation is over $L^2$ equivalence classes, and the minimiser is unique. If $Y:\Omega \to E$ is a random element taking values in a standard Borel space $(E, \mathcal{E})$, then there also exists a measurable function $g^\star:E\to\mathcal{H}$ such that
    \begin{align*}
        \mathbb{E}[X \mid Y] = \mathbb{E}[X \mid \sigma(Y)] = g^\star(Y)\qquad\text{almost surely},
    \end{align*}
    so the random element $g^\star(Y)$ minimises $\mathbb{E}[\lVert X-U\rVert^2]$ over $U\in L^2(\Omega,\sigma(Y),\mathbb{P};\mathcal{H})$.
\end{thm}

