\begin{defn}[Weak Stationarity]\label{defn:weak-stationarity}
    Let $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space, $(\mathcal{H}, \langle \cdot, \cdot\rangle)$ be a real separable Hilbert space, and $X = (X_t)_{t \in \mathbb{N}}$ be a sequence of $\mathcal{H}$-valued random elements with $\mathbb{E}[\lVert X_t\rVert^2] < \infty$ for all $t \in \mathbb{N}$. Then $X$ is said to be weakly stationary if there exist $\mu\in\mathcal{H}$ and $\Sigma(h)\in\mathcal{L}(\mathcal{H})$, $h\in\mathbb{N}_0$, such that
    \begin{align*}
        \mathbb{E}[X_t] = \mu,
    \end{align*}
    for all $t\in\mathbb{N}$, and
    \begin{align*}
        \mathbb{E}[(X_{t+h} - \mu) \otimes (X_t - \mu)] = \Sigma(h)
    \end{align*}
    for all $h \in \mathbb{N}_0$ and $t \in \mathbb{N}$.
\end{defn}

environments.statement:
\label{defn:weak-stationarity}
    Let $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space, $(\mathcal{H}, \langle \cdot, \cdot\rangle)$ be a real separable Hilbert space, and $X = (X_t)_{t \in \mathbb{N}}$ be a sequence of $\mathcal{H}$-valued random elements with $\mathbb{E}[\lVert X_t\rVert^2] < \infty$ for all $t \in \mathbb{N}$. Then $X$ is said to be weakly stationary if there exist $\mu\in\mathcal{H}$ and $\Sigma(h)\in\mathcal{L}(\mathcal{H})$, $h\in\mathbb{N}_0$, such that
    \begin{align*}
        \mathbb{E}[X_t] = \mu,
    \end{align*}
    for all $t\in\mathbb{N}$, and
    \begin{align*}
        \mathbb{E}[(X_{t+h} - \mu) \otimes (X_t - \mu)] = \Sigma(h)
    \end{align*}
    for all $h \in \mathbb{N}_0$ and $t \in \mathbb{N}$.

proof.rawEnvironment:
\begin{proof}
    We must show that $X=(X_t)_{t\in\mathbb{N}}$ satisfies Definition~\ref{defn:weak-stationarity} if and only if for all $n,m\in\mathbb{N}$, the coordinate mean $\mathbb{E}[\theta_{t,n}]$ is independent of $t\in\mathbb{N}$ and the cross-covariance $\mathbb{E}[(\theta_{t+h,n}-\mu_n)(\theta_{t,m}-\mu_m)]$ depends only on $h\in\mathbb{N}_0$.

    Suppose first that $X$ is weakly stationary, with constant mean $\mu\in\mathcal{H}$ and lag-$h$ covariance operators $\Sigma(h)\in\mathcal{L}(\mathcal{H})$. Then
    \begin{align*}
        \mathbb{E}[X_t] = \mu,\quad \forall t \in \mathbb{N}.
    \end{align*}
    Because the coordinate map
    \begin{align*}
        x \mapsto \langle x, e_n\rangle
    \end{align*}
    is a bounded linear functional on $\mathcal{H}$, it commutes with the Bochner expectation, and hence
    \begin{align*}
        \mathbb{E}[\theta_{t,n}] = \mathbb{E}[\langle X_t, e_n\rangle] = \langle \mathbb{E}[X_t], e_n\rangle = \langle \mu, e_n\rangle = \mu_n,
    \end{align*}
    which is independent of $t$. Similarly, since
    \begin{align*}
        \mathbb{E}[(X_{t+h} - \mu) \otimes (X_t - \mu)] = \Sigma(h)
    \end{align*}
    for all $t\in\mathbb{N}$ and $h\in\mathbb{N}_0$, Definition~\ref{defn:tensor-product} gives
    \begin{align*}
        \mathbb{E}[(\theta_{t+h,n} - \mu_n)(\theta_{t,m} - \mu_m)] &= \mathbb{E}[\langle X_{t+h} - \mu, e_n\rangle\langle X_t - \mu, e_m\rangle]\\ &= \langle \Sigma(h) e_n, e_m\rangle\\ &= \sigma_{n,m}(h),
    \end{align*}
    which depends only on $h$ for every $n,m\in\mathbb{N}$.

    Conversely, assume that for all $n,m\in\mathbb{N}$, the coordinate means $\mathbb{E}[\theta_{t,n}]=\mu_n$ are constant in time and the cross-covariances $\mathbb{E}[(\theta_{t+h,n}-\mu_n)(\theta_{t,m}-\mu_m)]=\sigma_{n,m}(h)$ depend only on $h\in\mathbb{N}_0$. Fix $t_0\in\mathbb{N}$ and set $\mu=\mathbb{E}[X_{t_0}]$. Then $\langle\mu,e_n\rangle=\mathbb{E}[\theta_{t_0,n}]=\mu_n$ for every $n\in\mathbb{N}$. For every $u = \sum_{n \in \mathbb{N}} u_n e_n \in \mathcal{H}$ and $t\in\mathbb{N}$, the partial sums $\sum_{n \leq N} u_n\theta_{t,n}$ converge to $\langle X_t, u\rangle$ in $L^2(\mathbb{P})$ by Parseval's identity and $\mathbb{E}[\lVert X_t\rVert^2]<\infty$, hence in $L^1(\mathbb{P})$, so that expectation and summation may be interchanged, and we obtain
    \begin{align*}
        \langle \mathbb{E}[X_t], u\rangle = \sum_{n \in \mathbb{N}} u_n \mathbb{E}[\theta_{t,n}]
        = \sum_{n \in \mathbb{N}} u_n \mu_n
        = \langle \mu, u\rangle,
    \end{align*}
    which implies that $\mathbb{E}[X_t]=\mu$ for every $t\in\mathbb{N}$. Next, for each $t\in\mathbb{N}$ and $h\in\mathbb{N}_0$, the operator
    \begin{align*}
        C_{t,h}=\mathbb{E}[(X_{t+h}-\mu)\otimes(X_t-\mu)]
        \in\mathcal{L}(\mathcal{H})
    \end{align*}
    is well-defined because the Cauchy--Schwarz inequality gives
    \begin{align*}
        \mathbb{E}[\lVert X_{t+h}-\mu\rVert\,\lVert X_t-\mu\rVert]<\infty.
    \end{align*}
    Its matrix coefficients with respect to $(e_n)_{n\in\mathbb{N}}$ satisfy
    \begin{align*}
        \langle C_{t,h}e_n,e_m\rangle
        =\mathbb{E}[(\theta_{t+h,n}-\mu_n)(\theta_{t,m}-\mu_m)]
        =\sigma_{n,m}(h),
    \end{align*}
    and therefore depend only on $h$. Since a bounded linear operator on $\mathcal{H}$ is uniquely determined by its matrix coefficients in an orthonormal basis, $C_{t,h}$ is independent of $t\in\mathbb{N}$ and may be written as $\Sigma(h)$. Consequently, $X$ is weakly stationary, as desired.
\end{proof}

