environments.rawEnvironment:
\begin{prop}\label{prop:weak-stationarity}
    Let $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space, $(\mathcal{H}, \langle \cdot, \cdot\rangle)$ be a real separable Hilbert space with an orthonormal basis $(e_n)_{n\in\mathbb{N}}$, and $X = (X_t)_{t \in \mathbb{N}}$ be a sequence of $\mathcal{H}$-valued random elements with $\mathbb{E}[\lVert X_t\rVert^2] < \infty$ for all $t \in \mathbb{N}$. Then $X$ is weakly stationary if and only if the score sequence
    \begin{align*}
        (\theta_t^\infty)_{t \in \mathbb{N}} = ((\theta_{t,n})_{n\in\mathbb{N}})_{t \in \mathbb{N}} = ((\langle X_t, e_n\rangle)_{n\in\mathbb{N}})_{t \in \mathbb{N}}
    \end{align*}
    has coordinate means and cross-covariances depending only on the lag. That is, for all $n,m \in \mathbb{N}$, the score process $(\theta_{t,n})_{t \in \mathbb{N}}$ has mean $\mu_n$ independent of $t$, and
    \begin{align*}
        \mathbb{E}[(\theta_{t+h,n} - \mu_n)(\theta_{t,m} - \mu_m)] = \sigma_{n,m}(h)
    \end{align*}
    depends only on $h \in \mathbb{N}_0$.
\end{prop}

environments.statement:
\label{prop:weak-stationarity}
    Let $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space, $(\mathcal{H}, \langle \cdot, \cdot\rangle)$ be a real separable Hilbert space with an orthonormal basis $(e_n)_{n\in\mathbb{N}}$, and $X = (X_t)_{t \in \mathbb{N}}$ be a sequence of $\mathcal{H}$-valued random elements with $\mathbb{E}[\lVert X_t\rVert^2] < \infty$ for all $t \in \mathbb{N}$. Then $X$ is weakly stationary if and only if the score sequence
    \begin{align*}
        (\theta_t^\infty)_{t \in \mathbb{N}} = ((\theta_{t,n})_{n\in\mathbb{N}})_{t \in \mathbb{N}} = ((\langle X_t, e_n\rangle)_{n\in\mathbb{N}})_{t \in \mathbb{N}}
    \end{align*}
    has coordinate means and cross-covariances depending only on the lag. That is, for all $n,m \in \mathbb{N}$, the score process $(\theta_{t,n})_{t \in \mathbb{N}}$ has mean $\mu_n$ independent of $t$, and
    \begin{align*}
        \mathbb{E}[(\theta_{t+h,n} - \mu_n)(\theta_{t,m} - \mu_m)] = \sigma_{n,m}(h)
