\begin{defn}[Rectangular Simple Functions]\label{defn:rectangular-simple-function}
Let $\mathcal{H}$ be a real separable Hilbert space, let $p\in\mathbb{N}$, and let $X\subseteq\mathbb{R}^p$. A \emph{rectangular simple function}\index{rectangular simple functions}, or \emph{axis-aligned simple function}, on $X$ with values in $\mathcal{H}$ is a function $r:X\to\mathcal{H}$ of the form
\begin{align*}
    r(x) = \sum_{k = 1}^K c_k \mathbbm{1}_{R_k}(x),
\end{align*}
where $K\in\mathbb{N}$, $c_1,\dots,c_K\in\mathcal{H}$, and each $R_k=(I_{k,1}\times\cdots\times I_{k,p})\cap X$ is an axis-aligned rectangle formed by the product of intervals $I_{k,j}\subseteq\mathbb{R}$.
\end{defn}

