\begin{defn}[Cell Impurity and Split Impurity Reduction]\label{defn:cell-impurity-split}
Let $\mathcal{H}$ be a real Hilbert space, let $p,n\in\mathbb{N}$, let $(y_i,\bm{x}_i)_{i=1}^n\subseteq\mathcal{H}\times\mathbb{R}^p$ be a finite family of observations, and let $S\subseteq\{1,\dots,n\}$ be a non-empty index set. The \emph{cell mean} on $S$ is defined by
\begin{align*}
    \hat{y}_S=\frac{1}{|S|}\sum_{i\in S}y_i,
\end{align*}
and the \emph{cell impurity} on $S$ under a loss function $\mathfrak{L}:\mathcal{H}\times\mathcal{H}\to[0,\infty)$ is defined by
\begin{align*}
    i(S)=\frac{1}{|S|}\sum_{i\in S}\mathfrak{L}(y_i,\hat{y}_S).
\end{align*}
Given a candidate split $s=(j,c)\in\{1,\dots,p\}\times\mathbb{R}$, let the left and right child index sets be
\begin{align*}
    S_L = \{i \in S \mid x_{i,j} \leq c\},\quad\quad S_R = \{i \in S \mid x_{i,j} > c\}.
\end{align*}
When $S_L$ and $S_R$ are both non-empty, $s$ is called \emph{admissible} on $S$, and the \emph{split impurity reduction} is defined by
\begin{align*}
    \Delta i (s, S) = i(S) - \frac{|S_L|}{|S|} i(S_L) - \frac{|S_R|}{|S|}i(S_R).
\end{align*}
\end{defn}

