\begin{lem}[Empirical Risk Minimiser on a Partition Cell]\label{lem:cell-risk-minimiser}
Let $\mathcal{H}$ be a real Hilbert space, let $n\in\mathbb{N}$, let $(y_i)_{i=1}^n\subseteq\mathcal{H}$, and let $S\subseteq\{1,\dots,n\}$ be non-empty, with cell mean $\hat{y}_S=\frac{1}{|S|}\sum_{i\in S}y_i$. For every $\hat{y}\in\mathcal{H}$,
\begin{align*}
    \sum_{i\in S}\lVert y_i-\hat{y}\rVert_{\mathcal{H}}^2
    =\sum_{i\in S}\lVert y_i-\hat{y}_S\rVert_{\mathcal{H}}^2
    +|S|\lVert\hat{y}-\hat{y}_S\rVert_{\mathcal{H}}^2.
\end{align*}
In particular, under the squared Hilbert loss $\mathfrak{L}(y,\hat{y})=\lVert y-\hat{y}\rVert_{\mathcal{H}}^2$, the cell mean $\hat{y}_S$ is the unique minimiser of $\sum_{i\in S}\mathfrak{L}(y_i,\hat{y})$ over $\hat{y}\in\mathcal{H}$.
\end{lem}

