\begin{prop}[Gram-Matrix Representation and Low-Rank Approximation Bound for Split Gains]\label{prop:gram-split-gain-bound}
Let $\mathcal{H}$ be a real Hilbert space, let $n\in\mathbb{N}$, and let $(y_i)_{i=1}^n\subseteq\mathcal{H}$ have Gram matrix $\bm{G}\in\mathbb{R}^{n\times n}$ given by $(\bm{G})_{i,j}=\langle y_i,y_j\rangle_{\mathcal{H}}$ for all $i,j\in\{1,\dots,n\}$. For any non-empty subset $A\subseteq\{1,\dots,n\}$, write $\hat{y}_A=\frac{1}{|A|}\sum_{i\in A}y_i$ and $i(A)=\frac{1}{|A|}\sum_{i\in A}\lVert y_i-\hat{y}_A\rVert_{\mathcal{H}}^2$. Then for any non-empty cell $S\subseteq\{1,\dots,n\}$ and any split $s$ partitioning $S$ into non-empty disjoint child sets $S_L$ and $S_R$, the cell impurity $i(S)$ and the split impurity reduction $\Delta i(s,S)=i(S)-\frac{|S_L|}{|S|}i(S_L)-\frac{|S_R|}{|S|}i(S_R)$ satisfy
\begin{align}\label{eq:compute-split-1}
    i(S) = \frac{1}{|S|}\sum_{i\in S}\lVert y_i\rVert_{\mathcal{H}}^2 - \left\lVert\hat{y}_S\right\rVert_{\mathcal{H}}^2
    = \frac{1}{2|S|^2}\sum_{i,j\in S} \lVert y_i -y_j\rVert_{\mathcal{H}}^2,
\end{align}
and
\begin{align}\label{eq:compute-split-2}
    \Delta i (s, S) = \frac{|S_L||S_R|}{|S|^2}\left\lVert\hat{y}_{S_L} - \hat{y}_{S_R}\right\rVert_{\mathcal{H}}^2.
\end{align}
In terms of $\bm{G}$ and the indicator vectors $\bm{1}_A\in\mathbb{R}^n$ with entries $(\bm{1}_A)_i=1$ for $i\in A$ and $0$ otherwise, these quantities take the form
\begin{align*}
    i(S) = \frac{1}{|S|} \underbrace{\sum_{i \in S} (\bm{G})_{i,i}}_{g_S^{\mathrm{diag}}} - \frac{1}{|S|^2}\underbrace{\bm{1}_S^\top \bm{G}\bm{1}_S}_{\vphantom{\sum_{i \in S} (\bm{G})_{i,i}}g_S^{\mathrm{all}}}
\end{align*}
and
\begin{align*}
    \Delta i(s,S)= \frac{|S_L||S_R|}{|S|^2}\left(\frac{g_{S_L}^{\mathrm{all}}}{|S_L|^2} + \frac{g_{S_R}^{\mathrm{all}}}{|S_R|^2} - \frac{2}{|S_L||S_R|} \bm{1}_{S_L}^\top \bm{G}\bm{1}_{S_R}\right).
\end{align*}
Furthermore, if $\bm{G}_r=\bm{U}_r\bm{\Lambda}_r\bm{U}_r^\top$ is the rank-$r$ spectral truncation of $\bm{G}$ retaining its $r$ largest eigenvalues $\lambda_1\geq\dots\geq\lambda_r\geq 0$ and $\Delta\tilde{i}(s,S)$ denotes the split gain evaluated with $\bm{G}_r$ in place of $\bm{G}$, then
\begin{align*}
    0 \leq \Delta i(s,S) - \Delta\tilde{i}(s,S) \leq \frac{\lambda_{r+1}}{|S|},
\end{align*}
where $\lambda_{r+1}$ is the $(r+1)$th eigenvalue of $\bm{G}$ (with $\lambda_{r+1}=0$ for $r\geq n$).
\end{prop}

