\begin{defn}[Hilbert-Valued Coalition Game, Marginal Contribution, and Shapley Value]\label{defn:hilbert-shapley-value}
Let $\mathcal{H}$ be a real separable Hilbert space, let $p\in\mathbb{N}$, and let $V:\wp(\{1,\dots,p\})\to\mathcal{H}$ be a map. For any subset $S\subseteq\{1,\dots,p\}$ and element $s\in\{1,\dots,p\}\setminus S$, the \emph{marginal contribution} of $s$ to $S$ is defined by
\begin{align*}
    \Delta V(S, s) = V(S \cup \{s\}) - V(S),
\end{align*}
and the \emph{Shapley value} of $s$ under $V$ is defined by
\begin{align}\label{eq:Shapley-value}
    \phi_s(V) = \sum_{S \in \wp(\{1,\dots,p\} \setminus \{s\}) } \frac{|S|!(p-|S|-1)!}{p!}\Delta V(S,s).
\end{align}
Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $f:\mathbb{R}^p\to\mathcal{H}$ be a Borel-measurable function, let $\bm{X}:\Omega\to\mathbb{R}^p$ be a random vector satisfying $\mathbb{E}[\lVert f(\bm{X})\rVert_{\mathcal{H}}]<\infty$, and for each $S\subseteq\{1,\dots,p\}$, let $\operatorname{pr}_S:\mathbb{R}^p\to\mathbb{R}^{|S|}$ denote the coordinate projection onto $S$, with $\bm{X}_S=\operatorname{pr}_S\bm{X}$ and $\bm{x}_S=\operatorname{pr}_S\bm{x}$ for $\bm{x}\in\mathbb{R}^p$. Given a chosen version of the conditional expectation and a point $\bm{x}\in\mathbb{R}^p$, the \emph{local coalition value} $V_{\bm{x}}:\wp(\{1,\dots,p\})\to\mathcal{H}$ is defined by
\begin{align*}
    V_{\bm{x}}(S)=\mathbb{E}[f(\bm{X})\mid\bm{X}_S=\bm{x}_S]
\end{align*}
for $S\subseteq\{1,\dots,p\}$, with marginal contribution
\begin{align}\label{eq:delta-shap}
    \Delta V_{\bm{x}}(S,s)=V_{\bm{x}}(S\cup\{s\})-V_{\bm{x}}(S)
\end{align}
for $s\in\{1,\dots,p\}\setminus S$, and local Shapley value $\phi_s(V_{\bm{x}})$ obtained by evaluating \eqref{eq:Shapley-value} at $V=V_{\bm{x}}$.
\end{defn}

