\begin{prop}[Non-Expansiveness of Bounded Monotone Decoding]\label{prop:monotone-decoding-nonexpansive}
Let $(\mathcal{H}_q,\lVert\cdot\rVert_{q,\mathrm{node}})$ and $(\mathcal{H}_p,\lVert\cdot\rVert_{p,\mathrm{num}})$ be finite-dimensional weighted Euclidean spaces of dimension $N_q$ and $N_p$, respectively, and let $-\infty < \underline{p} < \overline{p} < \infty$. Define the monotone subsets
\begin{align*}
    \mathcal{C}_q &= \{z\in\mathcal{H}_q \mid z_1 \leq z_2 \leq \dots \leq z_{N_q}\},\\
    \mathcal{C}_p &= \{p\in\mathcal{H}_p \mid \underline{p} \leq p_1 \leq p_2 \leq \dots \leq p_{N_p} \leq \overline{p}\}.
\end{align*}
Then $\mathcal{C}_q\subseteq\mathcal{H}_q$ and $\mathcal{C}_p\subseteq\mathcal{H}_p$ are non-empty, closed, and convex subsets, and for any $\sigma$-algebra $\mathcal{F}_d$ and any Bochner-integrable random element $W=(\operatorname{pr}_q W,\operatorname{pr}_p W)$ in $\mathcal{H}_q\times\mathcal{H}_p$, that is, $\mathbb{E}[\lVert W\rVert]<\infty$, taking values in $\mathcal{C}_q\times\mathcal{C}_p$ almost surely, the conditional expectation $\mathbb{E}[W\mid\mathcal{F}_d]$ takes values in $\mathcal{C}_q\times\mathcal{C}_p$ almost surely. Consequently, if $\widehat{Z}_{d+1,h}=(\operatorname{pr}_q\widehat{Z}_{d+1,h},\operatorname{pr}_p\widehat{Z}_{d+1,h})$ denotes the componentwise metric projection of $\widetilde{Z}_{d+1,h}\in\mathcal{H}_q\times\mathcal{H}_p$ onto $\mathcal{C}_q\times\mathcal{C}_p$, then for every $Y\in\mathcal{C}_q\times\mathcal{C}_p$,
\begin{align*}
    \left\lVert\operatorname{pr}_p\widehat{Z}_{d+1,h} - \operatorname{pr}_p Y\right\rVert_{p,\mathrm{num}}
    &\leq \left\lVert\operatorname{pr}_p\widetilde{Z}_{d+1,h} - \operatorname{pr}_p Y\right\rVert_{p,\mathrm{num}},\\
    \left\lVert\operatorname{pr}_q\widehat{Z}_{d+1,h} - \operatorname{pr}_q Y\right\rVert_{q,\mathrm{node}}
    &\leq \left\lVert\operatorname{pr}_q\widetilde{Z}_{d+1,h} - \operatorname{pr}_q Y\right\rVert_{q,\mathrm{node}}.
\end{align*}
\end{prop}

