\begin{defn}[Threshold Screen and Payoff Proxies]\label{defn:viability-screen-impact-cost}
Let $T$ be a finite index set, and for each $t\in T$, let $D_t\subseteq\mathbb{R}$ be an interval, let $P_t:D_t\to\mathbb{R}$ be a function, and let $Q_t,\widehat{Q}_t\in[0,\infty)$. Fix a threshold $c\in\mathbb{R}$, and let $T_{\mathrm{pair}}\subseteq\{t\in T \mid 0\in D_t,\ -\widehat{Q}_t\in D_t\}$. For each $t\in T_{\mathrm{pair}}$ and any $q\geq 0$ with $-q\in D_t$, the \emph{threshold screen} is the indicator function
\begin{align*}
    a_t(q)=\begin{cases}
        1,&P_t(-q)\geq c,\\
        0,&P_t(-q)<c.
    \end{cases}
\end{align*}
For each $t\in T_{\mathrm{pair}}$, the \emph{impact payoff proxy} and the \emph{zero-impact payoff proxy} are defined by
\begin{align}
    \mathsf{Payoff}_t
    &=a_t(\widehat{Q}_t)\widehat{Q}_tP_t(-\widehat{Q}_t),
    \label{eq:payoff-with-impact}\\
    \mathsf{Payoff}^0_t
    &=\widehat{Q}_tP_t(0)\mathbbm{1}(P_t(0)\geq c),
    \label{eq:payoff-without-impact}
\end{align}
the \emph{impact-cost proxy} over $T_{\mathrm{pair}}$ is the paired difference $\sum_{t\in T_{\mathrm{pair}}}(\mathsf{Payoff}^0_t-\mathsf{Payoff}_t)$, and the \emph{residual quantity} at index $t$ is
\begin{align*}
    \Delta Q_t=Q_t-a_t(\widehat{Q}_t)\widehat{Q}_t.
\end{align*}
\end{defn}

