\begin{defn}[Piecewise-Linear Conversion Map and Feasible Schedule Set]\label{defn:battery-schedule-set}
Let $\eta_{\mathrm{charge}}, \eta_{\mathrm{discharge}} \in (0,1]$. For $\Delta q\in\mathbb{R}$, the \emph{conversion map} $\tau:\mathbb{R}\to\mathbb{R}$ is defined by
\begin{align*}
    \tau(\Delta q) = \begin{cases}
        \eta_{\mathrm{discharge}} \Delta q, &  \Delta q < 0,\\
        \frac{\Delta q}{\eta_{\mathrm{charge}}}, & \Delta q \geq 0.
    \end{cases}
\end{align*}
Let $K > 0$ and $R_{\max} > 0$, let $\mathcal{G}\subseteq[0,K]$ and $\mathcal{R}\subseteq[-R_{\max},R_{\max}]$ be finite sets, let $\bm{P}=(P_h)_{h=1}^{24}$ be a $24$-tuple of functions $P_h:\operatorname{domain}(P_h)\to\mathbb{R}$ with $\operatorname{domain}(P_h)\subseteq\mathbb{R}$, and let $q_{\mathrm{start}},q_{\mathrm{stop}}\in\mathcal{G}$. The \emph{feasible schedule set} is defined by
\begin{align}\label{eq:finite-battery-action-set}
\begin{aligned}
\mathcal{A}_{\mathcal{G}}
&(q_{\mathrm{start}},q_{\mathrm{stop}};\bm{P})\\[-0.2em]
&=
\left\{\Delta\bm{q}\in\mathcal{R}^{24}\ \middle|\
\begin{aligned}
q_h
&=q_{\mathrm{start}}+\sum_{r=1}^h\Delta q_r\in\mathcal{G},
&&h=1,\dots,24,\\
q_{24}&=q_{\mathrm{stop}},\\
\tau(\Delta q_h)&\in\operatorname{domain}(P_h),
&&h=1,\dots,24
\end{aligned}
\right\}.
\end{aligned}
\end{align}
A pair $(q_{\mathrm{start}},q_{\mathrm{stop}})\in\mathcal{G}^2$ is called a \emph{transition}, and it is \emph{feasible} for $\bm{P}$ when $\mathcal{A}_{\mathcal{G}}(q_{\mathrm{start}},q_{\mathrm{stop}};\bm{P})$ is non-empty.
\end{defn}

