\begin{defn}[Plug-In and Realised Value Functions]\label{defn:battery-value-functions}
Let $\mathcal{G}$, $\mathcal{R}$, and $\tau$ be as in Definition~\ref{defn:battery-schedule-set}, and let $\lambda\geq 0$. For an index $d$, let $\widehat{\bm{P}}_d=(\widehat{P}_{d,h})_{h=1}^{24}$ and $\bm{P}_d=(P_{d,h})_{h=1}^{24}$ be $24$-tuples of functions on $\mathbb{R}$. For any transition $(q_{\mathrm{start}},q_{\mathrm{stop}})\in\mathcal{G}^2$ that is feasible for $\widehat{\bm{P}}_d$, the \emph{plug-in value function} is defined by
\begin{align}\label{eq:approximate-battery-problem}
\begin{gathered}
\widehat{V}_d(q_{\mathrm{start}},q_{\mathrm{stop}})=\\[-0.35em]
\max_{\substack{\Delta\bm{q}\in\mathcal{A}_{\mathcal{G}}
(q_{\mathrm{start}},q_{\mathrm{stop}};\widehat{\bm{P}}_d)}}
\sum_{h=1}^{24}
\left[-\tau(\Delta q_h)\widehat{P}_{d,h}(\tau(\Delta q_h))-\lambda|\Delta q_h|\right].
\end{gathered}
\end{align}
Let $\Delta\bm{q}^\star=\Delta\bm{q}^\star_d(q_{\mathrm{start}},q_{\mathrm{stop}})$ be the lexicographically first maximiser of \eqref{eq:approximate-battery-problem} with respect to the coordinate order on $\{1,\dots,24\}$ and the standard order on $\mathcal{R}$. Whenever $\Delta\bm{q}^\star\in\mathcal{A}_{\mathcal{G}}(q_{\mathrm{start}},q_{\mathrm{stop}};\bm{P}_d)$, the \emph{realised value} of the selected schedule is defined by
\begin{align}\label{eq:realised-battery-problem}
    V_d(q_{\mathrm{start}},q_{\mathrm{stop}})
    =\sum_{h=1}^{24}
    -\tau(\Delta q_h^\star)\,
    P_{d,h}(\tau(\Delta q_h^\star))
    -\lambda\sum_{h=1}^{24}|\Delta q_h^\star|,
\end{align}
with \emph{unpenalised value} $R_d(q_{\mathrm{start}},q_{\mathrm{stop}})=\sum_{h=1}^{24}-\tau(\Delta q_h^\star)P_{d,h}(\tau(\Delta q_h^\star))$, \emph{total variation} $T_d(q_{\mathrm{start}},q_{\mathrm{stop}})=\sum_{h=1}^{24}|\Delta q_h^\star|$, and \emph{transition value error}
\begin{align*}
    \varepsilon^{(d)}_{i,j} = V_d(q_i, q_j) - \widehat{V}_d(q_i,q_j),
    \qquad q_i,q_j\in\mathcal{G}.
\end{align*}
\end{defn}

