\begin{prop}[Exactness of Lagrangian Separation]\label{prop:everett-lagrangian-separation}
Let $\mathcal{X}$ be a non-empty set, and let $\mathcal{R}:\mathcal{X}\to\mathbb{R}$ and $\mathcal{T}:\mathcal{X}\to[0,\infty)$ be functions. If $\lambda\geq 0$ and $\bm{x}^\lambda\in\argmax_{\bm{x}\in\mathcal{X}}\{\mathcal{R}(\bm{x})-\lambda\mathcal{T}(\bm{x})\}$, then for every $\bm{x}\in\mathcal{X}$ satisfying $\mathcal{T}(\bm{x})\leq\mathcal{T}(\bm{x}^\lambda)$,
\begin{align*}
    \mathcal{R}(\bm{x})\leq\mathcal{R}(\bm{x}^\lambda).
\end{align*}
In particular, $\bm{x}^\lambda$ is a global maximiser of $\mathcal{R}(\bm{x})$ over $\{\bm{x}\in\mathcal{X} \mid \mathcal{T}(\bm{x})\leq\mathcal{T}(\bm{x}^\lambda)\}$.
\end{prop}

