\begin{defn}[Priority Relations and Order Metric]\label{defn:price-time-priority-metric}
    Let $U = [-9999,9999]\times(0,\infty)\times[0,1]$ and let $O = \bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}} U$. On $U$, the relations $\preceq^{\mathrm{buy}}$ and $\preceq^{\mathrm{sell}}$ are defined for $(p,q,t),(p^\prime,q^\prime,t^\prime)\in U$ by
    \begin{align*}
        (p, q, t) \preceq^{\mathrm{buy}} (p^\prime, q^\prime, t^\prime)
        &\iff (p,q,t)=(p^\prime,q^\prime,t^\prime) \lor (p > p^\prime)\\
        &\qquad\lor ((p = p^\prime) \land (t < t^\prime))
    \end{align*}
    and
    \begin{align*}
        (p, q, t) \preceq^{\mathrm{sell}} (p^\prime, q^\prime, t^\prime)
        &\iff (p,q,t)=(p^\prime,q^\prime,t^\prime) \lor (p < p^\prime)\\
        &\qquad\lor ((p = p^\prime) \land (t < t^\prime)).
    \end{align*}
    On $O$, the relation $\preceq$ is defined for $(o,\kappa),(o^\prime,\kappa^\prime)\in O$ by
    \begin{align}\label{eq:price-time-priority}
        (o, \kappa) \preceq (o^\prime, \kappa^\prime) \iff ((\kappa = \mathrm{buy}) \land (\kappa^\prime = \mathrm{sell})) \lor ((\kappa = \kappa^\prime) \land (o \preceq^{\kappa} o^\prime)).
    \end{align}
    Furthermore, the \emph{order metric} $d_O:O\times O\to[0,\infty]$ is defined by
    \begin{align*}
        d_O(((p,q,t),\kappa), ((p^\prime, q^\prime, t^\prime), \kappa^\prime)) = \begin{cases}
            \infty & \kappa \neq \kappa^\prime,\\
            \lvert p-p^\prime\rvert + \lvert\log(q) - \log(q^\prime)\rvert + \lvert t-t^\prime\rvert  & \kappa = \kappa^\prime.
        \end{cases}
    \end{align*}
\end{defn}

