\begin{defn}[Best-Price and Trade-Price Functionals]\label{defn:best-price-and-tradeprice}
    Let $U = [-9999,9999]\times\allowbreak (0,\infty) \times [0,1]$ and $O = \bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}} U$, let $\preceq$ be as in Definition~\ref{defn:price-time-priority-metric}, and let $\mathsf{price} : U \to [-9999,9999]$, $\mathsf{quantity} : U \to (0,\infty)$, and $\mathsf{time} : U \to [0,1]$ denote the first, second, and third coordinate projections on $U$, respectively. For each $\kappa \in \{\mathrm{buy}, \mathrm{sell}\}$, the \emph{best-price functional} $\mathsf{best}_\kappa:\mathscr{T}(U) \to [-10000, 10000]$ is defined by
    \begin{align*}
        \mathsf{best}_\kappa(\bm{x}) = \begin{cases}
            10000 & \bm{x} = \bm{e} \land \kappa = \mathrm{sell},\\
            -10000 & \bm{x} = \bm{e} \land \kappa = \mathrm{buy},\\
            \mathsf{price}(\bm{x}(1)) & \text{otherwise}.
        \end{cases}
    \end{align*}
    For any $\bm{m} \in \mathscr{S}(O, \preceq)$ with $\bm{b} = \bm{\Pi}_{\mathrm{buy}}(\bm{m})$ and $\bm{s} = \bm{\Pi}_{\mathrm{sell}}(\bm{m})$ satisfying
    \begin{align*}
        \mathsf{best}_{\mathrm{buy}}(\bm{b}) \geq \mathsf{best}_{\mathrm{sell}}(\bm{s}),
    \end{align*}
    the \emph{matched quantity} is $\min(\mathsf{quantity}(\bm{b}(1)), \mathsf{quantity}(\bm{s}(1)))$, and for $\kappa\in\{\mathrm{buy},\mathrm{sell}\}$, the \emph{transaction price} is defined by
    \begin{align*}
        \mathsf{tradeprice}(\bm{b},\bm{s};\kappa)
        =\begin{cases}
            \mathsf{price}(\bm{s}(1)) & \kappa=\mathrm{buy},\\
            \mathsf{price}(\bm{b}(1)) & \kappa=\mathrm{sell}.
        \end{cases}
    \end{align*}
\end{defn}

