\begin{prop}\label{prop:single-stage-execution}
    Let $U = [-9999,9999]\times(0,\infty)\times[0,1]$ and let $\Phi$ be as in Definition~\ref{defn:single-stage-clearing-map}. Then the single-stage clearing map
    \begin{align*}
        \Phi:
        \mathscr{S}(U,\preceq^{\mathrm{buy}})
        \times\mathscr{S}(U,\preceq^{\mathrm{sell}})
        \to
        \mathscr{S}(U,\preceq^{\mathrm{buy}})
        \times\mathscr{S}(U,\preceq^{\mathrm{sell}})
    \end{align*}
    is Borel measurable.
\end{prop}

\begin{defn}[Iterated Single-Stage Clearing Maps]\label{defn:iterated-single-stage-clearing}
    Let $U = [-9999,9999]\times(0,\infty)\times[0,1]$ and let $\Phi$ be as in Definition~\ref{defn:single-stage-clearing-map}. For each $i\in\mathbb{N}_0$, the \emph{$i$-fold iterated single-stage clearing map}
    \begin{align*}
        \Phi^{(i)} : \mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}}) \to \mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}})
    \end{align*}
    is defined recursively by
    \begin{align*}
        \Phi^{(0)} &= \mathrm{Id},\\
        \Phi^{(1)} &= \Phi, \\
        \Phi^{(i)} &= \Phi^{(i-1)} \circ \Phi, \qquad i > 1.
    \end{align*}
\end{defn}

environments.statement:
\label{defn:iterated-single-stage-clearing}
