    For every $i \in \mathbb{N}_0$, the iterated single-stage clearing map $\Phi^{(i)} : \mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}}) \to \mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}})$ of Definition~\ref{defn:iterated-single-stage-clearing} is Borel measurable.
\end{cor}

\begin{defn}[Retagging]\label{defn:retagging}
    Let $(X_\alpha)_{\alpha\in A}$ be a family of non-empty sets and let $X=\bigsqcup_{\alpha\in A}X_\alpha$. For each $\alpha\in A$, define the \emph{$\alpha$-retagging map}
    \begin{align*}
        \iota_\alpha:X_\alpha&\to X,\\
        x&\mapsto(x,\alpha),
    \end{align*}
    and its tuple-wise extension $\bm{\iota}_\alpha:\mathscr{T}(X_\alpha)\to\mathscr{T}(X)$ by
    \begin{align*}
        \bm{\iota}_\alpha\bm{x}=\iota_\alpha\circ\bm{x}.
    \end{align*}
\end{defn}

