\begin{defn}[Identifier-Tagged Space and Clearing Operator]\label{defn:identifier-clearing-operator}
    Let $O$ and $\preceq$ be as in Definition~\ref{defn:price-time-priority-metric}, let $O\times\mathbb{N}$ be endowed with the product metric of Example~\ref{exmp:identifier-coordinates}, and let $h:O\to\{0,1\}\times\mathbb{R}\times\mathbb{R}$ be the side--price--time key
    \begin{align*}
        h(((p,q,t),\mathrm{buy}))=(0,-p,t),
        \qquad h(((p,q,t),\mathrm{sell}))=(1,p,t),
    \end{align*}
    with strictly lexicographic comparison $<_{\mathrm{lex}}$, and let $\preceq_{\mathbb{N}}$ be the partial order on $O\times\mathbb{N}$ of Proposition~\ref{prop:identifier-tie-breaking} given by
    \begin{align*}
        (x, i) \preceq_{\mathbb{N}} (y, j)
        \iff (x,i)=(y,j)
        \ \lor\ h(x)<_{\mathrm{lex}}h(y)
        \ \lor\ \bigl(h(x)=h(y)\land i<j\bigr).
    \end{align*}
    This relation coincides with equality or strict lexicographic comparison of $(h(x),i)$, as in Proposition~\ref{prop:identifier-tie-breaking}; it is a partial order on the full product $O\times\mathbb{N}$ and restricts to a total order on the entries of any tuple with distinct identifiers.
    Let $\varpi:O\times\mathbb{N}\to O$, $(x,i)\mapsto x$, be the coordinate projection onto $O$, and let $\varpi_*:\mathscr{T}(O\times\mathbb{N})\to\mathscr{T}(O)$, $\varpi_*\bm{m}=\varpi\circ\bm{m}$, denote its tuple-wise extension. Identifying $O\times\mathbb{N}$ with $\bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}} (U\times\mathbb{N})$, let $\Phi_{\mathbb{N}}$ be the single-stage clearing map on $\mathscr{S}(U\times\mathbb{N},\preceq^{\mathrm{buy}}_{\mathbb{N}})\times\mathscr{S}(U\times\mathbb{N},\preceq^{\mathrm{sell}}_{\mathbb{N}})$ defined by replacing $((p_{\bm{x}},q_{\bm{x}},t_{\bm{x}}))$ in Definition~\ref{defn:single-stage-clearing-map} with $((p_{\bm{x}},q_{\bm{x}},t_{\bm{x}}), i_{\bm{x}})$ for $\bm{x}(1) = ((p_{\bm{x}},q_{\bm{x}},t_{\bm{x}}), i_{\bm{x}}) \in U\times\mathbb{N}$. The \emph{identifier-based clearing operator}
    \begin{align*}
        \mathsf{C}_{\mathbb{N}}: \mathscr{S}(O\times\mathbb{N},\preceq_{\mathbb{N}}) \to \mathscr{S}(O\times\mathbb{N},\preceq_{\mathbb{N}})
    \end{align*}
    is defined for $\bm{m}\in\mathscr{S}(O\times\mathbb{N},\preceq_{\mathbb{N}})$ by
    \begin{align*}
        (\bm{b}^\star,\bm{s}^\star)
        &=
        \Phi_{\mathbb{N}}^{(\max\{\ell(\bm{m})-1,0\})}
        \left(\bm{\Pi}_{\mathrm{buy}}\bm{m},
        \bm{\Pi}_{\mathrm{sell}}\bm{m}\right),\\
        \mathsf{C}_{\mathbb{N}}(\bm{m})
        &=(\bm{\iota}_{\mathrm{buy}}\bm{b}^\star)
        \oplus(\bm{\iota}_{\mathrm{sell}}\bm{s}^\star).
    \end{align*}
\end{defn}

