\begin{defn}[Visible Tuple Space and Projection]\label{defn:visible-order-book}
    Let $O$ and $\preceq$ be as in Definition~\ref{defn:price-time-priority-metric}, let $\bm{\Pi}_{\mathrm{buy}}$ and $\bm{\Pi}_{\mathrm{sell}}$ be the separation operators of Definition~\ref{defn:separation-operators}, and let $\bm{\iota}_{\mathrm{buy}}$ and $\bm{\iota}_{\mathrm{sell}}$ be the retagging maps of Definition~\ref{defn:retagging}. The \emph{visible tuple space} is the subset
    \begin{align*}
        \mathscr{B} = \{\bm{m} \in \mathscr{S}(O, \preceq) \mid \max(\ell(\bm{\Pi}_{\mathrm{buy}} \bm{m}), \ell(\bm{\Pi}_{\mathrm{sell}} \bm{m})) \leq 100\},
    \end{align*}
    and the \emph{visible projection} $\Pi^{\mathscr{B}} : \mathscr{S}(O, \preceq) \to \mathscr{B}$ is defined by
    \begin{align}\label{eq:intraday-visible-projection}
        \Pi^{\mathscr{B}}(\bm{m})
        &=
        \bm{\iota}_{\mathrm{buy}}\!\left((\bm{\Pi}_{\mathrm{buy}} \bm{m})[\{1, \dots, 100\}]\right)
        \notag\\
        &\qquad\oplus
        \bm{\iota}_{\mathrm{sell}}\!\left((\bm{\Pi}_{\mathrm{sell}} \bm{m})[\{1, \dots, 100\}]\right).
    \end{align}
\end{defn}

