\begin{defn}[Gaussian-Kernel Selection Probabilities]\label{defn:state-dependent-selection-probabilities}
    Let $\mathscr{S}$ be a state space and let $\chi:\mathscr{S}\to\mathbb{R}^d$ be a map into $d$-dimensional Euclidean space ($d\in\mathbb{N}_+$). Given a query state $\bm{m}^\ast\in\mathscr{S}$ and a collection of candidate states $(\bm{m}_k)_{k=1}^K\in\mathscr{S}^K$ ($K\in\mathbb{N}_+$), the \emph{Gaussian-kernel selection probabilities} on $\{1,\dots,K\}$ are defined by
    \begin{align*}
        \pi(k)=\frac{\exp\bigl(-\lVert\chi(\bm{m}^\ast)-\chi(\bm{m}_k)\rVert_2^2\bigr)}{\sum_{k^\prime=1}^{K}\exp\bigl(-\lVert\chi(\bm{m}^\ast)-\chi(\bm{m}_{k^\prime})\rVert_2^2\bigr)},\qquad k\in\{1,\dots,K\}.
    \end{align*}
\end{defn}

