\begin{prop}[Calibration Expectations of Ensemble Mid-Rank Coverage Fractions]\label{prop:midrank-coverage-expectations}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $\mathscr{X}$ be a measurable space, let $f:\mathscr{X}\to\mathbb{R}$ be a measurable functional, and let $(x_d,x_d^{(1)},\allowbreak\dots,\allowbreak x_d^{(B)})$ ($d\in\{1,\dots,D\}$, $D,B\in\mathbb{N}_+$) be $\mathscr{X}^{B+1}$-valued random elements. Suppose that for each $d\in\{1,\dots,D\}$, the real-valued random variables $\bigl(f(x_d), f(x^{(1)}_d),\allowbreak \dots,\allowbreak f(x^{(B)}_d)\bigr)$ are exchangeable and almost surely free of ties. Then, for every $\alpha\in(0,1)$, the coverage fractions of Definition~\ref{defn:ensemble-mid-rank-coverage} satisfy
    \begin{align*}
        \mathbb{E}[\mathsf{CF}(f,\alpha)] = c_B(\alpha)
        \qquad\text{and}\qquad
        \mathbb{E}[\mathsf{UF}(f,\alpha)] = \frac{\lfloor B(1-\alpha)\rfloor + 1}{B+1},
    \end{align*}
    and both expectations converge to $1-\alpha$ as $B\to\infty$.
\end{prop}

