\begin{defn}[Subproblem Value and Dynamic Recursion]\label{defn:parser-inner-outer-programs}
    Let $n,m,N,M\in\mathbb{N}_+$, let $\mathcal{I}=(I_k)_{k=1}^N$ be a partition of $\{1,\dots,n\}$ associated with strictly increasing scalars $\sigma_1<\cdots<\sigma_N$ in $\mathbb{R}$, and let $\mathcal{J}=(J_l)_{l=1}^M$ be a partition of $\{1,\dots,m\}$ associated with strictly increasing scalars $\tilde{\sigma}_1<\cdots<\tilde{\sigma}_M$ in $\mathbb{R}$. Let $\mathcal{A},\mathcal{R}\subseteq\{1,\dots,n\}$ be disjoint subsets, let $(p_i)_{i=1}^n\in\mathbb{R}^n$, $(\Delta q_i)_{i\in\mathcal{R}}\in(0,\infty)^{\mathcal{R}}$, and $(\kappa_i)_{i=1}^n\in\{+1,-1\}^n$, let $(\tilde{p}_j)_{j=1}^m\in\mathbb{R}^m$ and $(\tilde{q}_j)_{j=1}^m\in(0,\infty)^m$, and let $\varepsilon_p\ge 0$ and $\delta_t>0$. For any pair $(I_k,J_l)\in\mathcal{I}\times\mathcal{J}$ with $R=I_k\cap\mathcal{R}$, $A=I_k\cap\mathcal{A}$, and $\lvert\sigma_k-\tilde{\sigma}_l\rvert\le\delta_t$, the \emph{block-pair subproblem score} $\mathsf{Match}_{I_k,J_l}$ is the optimal value of the mixed-integer linear program
    \begin{align}\label{eq:intraday-inner-match-main}
        \mathsf{Match}_{I_k,J_l} &
        =\max_{x,y,\beta}
          \left\{\sum_{\substack{i\in R\\j\in J_l}}x_{i,j}\tilde{q}_j
          +\sum_{\substack{u\in A\\j\in J_l}}y_{u,j}\tilde{q}_j\right\}\\
        \text{s.t.}\quad
        & \sum_{i\in R}x_{i,j}\leq\beta_j
          \tag*{$\forall j\in J_l,$}\\
        & \sum_{u\in A}y_{u,j}\leq1-\beta_j
          \tag*{$\forall j\in J_l,$}\\
        & \sum_{j\in J_l}x_{i,j}\tilde{q}_j\leq\Delta q_i
          \tag*{$\forall i\in R,$}\\
        & x_{i,j}=0
          \tag*{$\forall i\in R,\ j\in J_l:\ \kappa_i=+1\land \tilde{p}_j>p_i+\varepsilon_p,$}\\
        & x_{i,j}=0
          \tag*{$\forall i\in R,\ j\in J_l:\ \kappa_i=-1\land \tilde{p}_j<p_i-\varepsilon_p,$}\\
        & y_{u,j}=0
          \tag*{$\forall u\in A,\ j\in J_l:\ \lvert\tilde{p}_j-p_u\rvert>\varepsilon_p,$}\\
        & x_{i,j}\in\{0,1\}
          \tag*{$\forall i\in R,\ j\in J_l,$}\\
        & y_{u,j}\in\{0,1\}
          \tag*{$\forall u\in A,\ j\in J_l,$}\\
        & \beta_j\in\{0,1\}
          \tag*{$\forall j\in J_l,$}
    \end{align}
    and $\mathsf{Match}_{I_k,J_l}=-\infty$ whenever $\lvert\sigma_k-\tilde{\sigma}_l\rvert>\delta_t$. The \emph{dynamic-programming value array} $(V_{k,l})_{0\le k\le N,\,0\le l\le M}$ is defined recursively by the boundary conditions $V_{0,0}=0$, $V_{0,l}=0$ for all $l\in\{1,\dots,M\}$, and $V_{k,0}=0$ for all $k\in\{1,\dots,N\}$, together with the Bellman recursion, for $k\in\{1,\dots,N\}$ and $l\in\{1,\dots,M\}$,
    \begin{align}\label{eq:intraday-outer-dp-main}
        V_{k,l}
        =\max\bigl\{V_{k-1,l},\;V_{k,l-1},\;V_{k-1,l-1}+\mathsf{Match}_{I_k,J_l}\bigr\}.
    \end{align}
\end{defn}

