\begin{prop}[Exactness of the Two-Level Block-Matching Decomposition]\label{prop:parser-two-level-exactness}
    Under the assumptions and notation of Definition~\ref{defn:parser-inner-outer-programs}, in the global integer program~\eqref{eq:intraday-global-matching-objective} and in the subproblem~\eqref{eq:intraday-inner-match-main}, the binary channel constraints $\sum_{i\in\mathcal{R}} x_{i,j}\le\beta_j$ and $\sum_{u\in\mathcal{A}} y_{u,j}\le 1-\beta_j$ for $\beta_j\in\{0,1\}$ are equivalent to the single assignment constraint $\sum_{i\in\mathcal{R}} x_{i,j} + \sum_{u\in\mathcal{A}} y_{u,j} \le 1$ for each $j\in\{1,\dots,m\}$. Furthermore, the terminal value $V_{N,M}$ of the recursion~\eqref{eq:intraday-outer-dp-main} equals the maximum objective value of the global integer program~\eqref{eq:intraday-global-matching-objective}.
\end{prop}

\begin{defn}[Single-Layer Self-Attention Encoder]\label{defn:aa-encoder}
    Let $M=41$ be the sequence length, let $h=64$ be the embedding dimension, let $W_{\mathrm{e}}\in\mathbb{R}^{64\times4}$, $W_{\mathrm{K}},W_{\mathrm{Q}},W_{\mathrm{V}}\in\mathbb{R}^{64\times64}$, $\bm{\pi}_1,\dots,\bm{\pi}_{41}\in\mathbb{R}^{64}$, $\bm{\omega}\in\mathbb{R}^{64}$, and $W_{\mathrm{o}}\in\mathbb{R}^{32\times 68}$, and let $F:\mathbb{R}^{64}\to\mathbb{R}^{128}\to\mathbb{R}^{64}$ be a two-layer position-wise network with a Gaussian error linear unit (GELU) activation. For an input tuple of vectors $(\varphi_1,\dots,\varphi_{41})\in(\mathbb{R}^4)^{41}$ and a scalar $m_w\in\mathbb{R}$, define the embedded vectors
    \begin{align*}
        \bm{z}_i=W_{\mathrm{e}}\varphi_i+\bm{\pi}_i,\qquad i=1,\dots,41,
    \end{align*}
    the self-attention updates
    \begin{align*}
        a_{ij}=\frac{\exp\bigl(\langle W_{\mathrm{K}}\bm{z}_j,W_{\mathrm{Q}}\bm{z}_i\rangle/\sqrt{h}\bigr)}{\sum_{l=1}^{41}\exp\bigl(\langle W_{\mathrm{K}}\bm{z}_l,W_{\mathrm{Q}}\bm{z}_i\rangle/\sqrt{h}\bigr)},\qquad
        \bm{z}_i'=\mathrm{LN}\Bigl(\bm{z}_i+\sum_{j=1}^{41}a_{ij}W_{\mathrm{V}}\bm{z}_j\Bigr),
    \end{align*}
