    \end{align}

proof.rawEnvironment:
\begin{proof}
    Expanding the squared Euclidean norm in the score $s_w(e)$ of~\eqref{eq:aa-score} gives
    \begin{align*}
        -\lVert\bm{e}_w-\bm{k}_e\rVert_2^2 = 2\langle\bm{e}_w,\bm{k}_e\rangle - \lVert\bm{e}_w\rVert_2^2 - \lVert\bm{k}_e\rVert_2^2.
    \end{align*}
    Substituting this identity into~\eqref{eq:aa-policy} and factoring $\exp(-\lVert\bm{e}_w\rVert_2^2)$ out of both the numerator and the denominator, since $\lVert\bm{e}_w\rVert_2^2$ is independent of the index $e\in\mathcal{C}_{d,w}$, yields the stated attention expression.
\end{proof}

