\begin{prop}[Equivalence of Biased Euclidean Softmax Policy and Biased Dot-Product Attention]\label{prop:aa-attention-equivalence}
    Under the assumptions and notation of Definition~\ref{defn:aa-retrieval-policy}, for any query vector $\bm{e}_w\in\mathbb{R}^{32}$ and candidate keys $(\bm{k}_e)_{e\in\mathcal{C}_{d,w}}$ in $\mathbb{R}^{32}$, the probability distribution $\pi_w$ of~\eqref{eq:aa-policy} coincides with the softmax weights of single-head dot-product attention with query $\bm{e}_w$, keys $\bm{k}_e$, temperature $\tau = 1/2$, and additive key bias $-\lVert\bm{k}_e\rVert_2^2 + b^{\mathrm{win}}_{w_e-w} + b^{\mathrm{age}}_{a(d-d_e)}$:
    \begin{align*}
        \pi_w(e) = \frac{\exp\bigl(\langle\bm{e}_w,\bm{k}_e\rangle / (1/2) - \lVert\bm{k}_e\rVert_2^2 + b^{\mathrm{win}}_{w_e-w} + b^{\mathrm{age}}_{a(d-d_e)}\bigr)}{\sum_{e'\in\mathcal{C}_{d,w}}\exp\bigl(\langle\bm{e}_w,\bm{k}_{e'}\rangle / (1/2) - \lVert\bm{k}_{e'}\rVert_2^2 + b^{\mathrm{win}}_{w_{e'}-w} + b^{\mathrm{age}}_{a(d-d_{e'})}\bigr)}.
    \end{align*}
\end{prop}

