\begin{defn}[Discrete Mixture Energy Score]\label{defn:aa-training-energy-score}
    Let $\mathcal{C}$ be a non-empty finite index set, let $(\bm{y}_e)_{e\in\mathcal{C}}$ in $\mathbb{R}^{33}$ be a family of outcome vectors, let $\bm{y}_q\in\mathbb{R}^{33}$ be a target outcome vector, and let $\pi\in\Delta(\mathcal{C})=\{\pi'\in[0,1]^{\mathcal{C}} \mid \sum_{e\in\mathcal{C}}\pi'(e)=1\}$ be a discrete probability distribution on $\mathcal{C}$. The \emph{discrete mixture energy score} of $\pi$ at $\bm{y}_q$ is defined by
    \begin{align}\label{eq:aa-es-mixture}
        \mathsf{ES}(\pi;\bm{y}_q)=\sum_{e\in\mathcal{C}}\pi(e)\,\lVert\bm{y}_e-\bm{y}_q\rVert_2-\frac{1}{2}\sum_{e,e'\in\mathcal{C}}\pi(e)\pi(e')\,\lVert\bm{y}_e-\bm{y}_{e'}\rVert_2.
    \end{align}
\end{defn}

environments.statement:
\label{defn:aa-training-energy-score}
    Let $\mathcal{C}$ be a non-empty finite index set, let $(\bm{y}_e)_{e\in\mathcal{C}}$ in $\mathbb{R}^{33}$ be a family of outcome vectors, let $\bm{y}_q\in\mathbb{R}^{33}$ be a target outcome vector, and let $\pi\in\Delta(\mathcal{C})=\{\pi'\in[0,1]^{\mathcal{C}} \mid \sum_{e\in\mathcal{C}}\pi'(e)=1\}$ be a discrete probability distribution on $\mathcal{C}$. The \emph{discrete mixture energy score} of $\pi$ at $\bm{y}_q$ is defined by
    \begin{align}\label{eq:aa-es-mixture}
        \mathsf{ES}(\pi;\bm{y}_q)=\sum_{e\in\mathcal{C}}\pi(e)\,\lVert\bm{y}_e-\bm{y}_q\rVert_2-\frac{1}{2}\sum_{e,e'\in\mathcal{C}}\pi(e)\pi(e')\,\lVert\bm{y}_e-\bm{y}_{e'}\rVert_2.
    \end{align}

proof.rawEnvironment:
\begin{proof}
    Let $D\in\mathbb{R}^{\mathcal{C}\times\mathcal{C}}$ be the pairwise Euclidean distance matrix with entries $D_{e,e'} = \lVert\bm{y}_e - \bm{y}_{e'}\rVert_2$, and let $\bm{d}\in\mathbb{R}^{\mathcal{C}}$ be the vector with entries $d_e = \lVert\bm{y}_e - \bm{y}_q\rVert_2$, so that $\mathsf{ES}(\pi;\bm{y}_q) = \bm{d}^{\top}\pi - \frac{1}{2}\pi^{\top} D \pi$. By Schoenberg's theorem on metric embeddings of Euclidean spaces~\citep{gneiting2007strictly}, the Euclidean distance matrix $D$ is conditionally negative definite: for every vector $\bm{v}\in\mathbb{R}^{\mathcal{C}}$ satisfying $\sum_{e\in\mathcal{C}} v_e = 0$, we have $\bm{v}^{\top} D \bm{v} \le 0$. For any two distributions $\pi,\pi'\in\Delta(\mathcal{C})$, their difference $\bm{v}=\pi-\pi'$ satisfies $\sum_{e\in\mathcal{C}} v_e = 0$, and hence the quadratic form $-\frac{1}{2}\bm{v}^{\top} D \bm{v} \ge 0$ is positive semi-definite along the tangent space of the simplex $\Delta(\mathcal{C})$. Consequently, $\pi\mapsto\mathsf{ES}(\pi;\bm{y}_q)$ is convex on $\Delta(\mathcal{C})$.
\end{proof}

environments.rawEnvironment:
\begin{prop}[Convexity of the Discrete Mixture Energy Score on the Simplex]\label{prop:aa-es-convex-simplex}
    Let $\mathcal{C}$ be a non-empty finite index set. For any fixed family of vectors $(\bm{y}_e)_{e\in\mathcal{C}}$ in $\mathbb{R}^{33}$ and target vector $\bm{y}_q\in\mathbb{R}^{33}$, the map $\pi \mapsto \mathsf{ES}(\pi;\bm{y}_q)$ of Definition~\ref{defn:aa-training-energy-score} is a convex quadratic function on the probability simplex $\Delta(\mathcal{C}) = \{\pi\in[0,1]^{\mathcal{C}} \mid \sum_{e\in\mathcal{C}}\pi(e)=1\}$.
\end{prop}

\begin{defn}[Finite-Ensemble Energy Score and CRPS Estimators]\label{defn:intraday-ensemble-energy-score}
    Let $d,B\in\mathbb{N}_+$, let $\bm{y}_t\in\mathbb{R}^d$ be an observation vector, and let $\bm{y}_t^{(1)},\dots,\bm{y}_t^{(B)}\in\mathbb{R}^d$ be an ensemble of size $B$. For $B\ge 2$, the \emph{finite-ensemble energy score estimator} is defined by
    \begin{align}\label{eq:intraday-energy-score}
        \mathsf{ES}_t
        =\frac{1}{B}\sum_{p=1}^{B}\lVert\bm{y}_t^{(p)}-\bm{y}_t\rVert_2
        -\frac{1}{2B(B-1)}\sum_{\substack{p,p'=1\\p\ne p'}}^{B}
            \lVert\bm{y}_t^{(p)}-\bm{y}_t^{(p')}\rVert_2,
    \end{align}
    and for $B=1$, the second term is set to zero, so that $\mathsf{ES}_t=\lVert\bm{y}_t^{(1)}-\bm{y}_t\rVert_2$. In the scalar case $d=1$, for $m_t\in\mathbb{R}$ and $m_t^{(1)},\dots,m_t^{(B)}\in\mathbb{R}$, the \emph{finite-ensemble continuous ranked probability score (CRPS) estimator} is defined by~\eqref{eq:intraday-energy-score} with $\lvert m_t^{(p)}-m_t\rvert$ and $\lvert m_t^{(p)}-m_t^{(p')}\rvert$ in place of the Euclidean norms.
\end{defn}

