\begin{axiom}[{Axiom of Union \citep[Axiom~5]{kunen2014set}}]\label{axiom:union}\index{axioms!union}
    For any family $F$ of sets, there is a set whose elements are exactly the elements of members of $F$. That is,
    \begin{align*}
        \forall F \exists U \forall x(x \in U \iff \exists X(X \in F \land x \in X)).
    \end{align*}
