\begin{axiom}[{Axiom Scheme of Replacement \citep[Axiom~6]{kunen2014set}}]\label{axiom:replacement}\index{axioms!replacement}
    For any formula $\phi \equiv \phi(x, y, X, w_1, \dots, w_n)$ whose free variables are among $x,y, X, w_1,\dots, w_n$, the corresponding axiom is
