\begin{defn}[{Relation \citep[Chapter~I, §6]{kunen2014set}}]\label{defn:relation}
    Let $X$ and $Y$ be sets. We call any $R \subseteq X \times Y$ a relation and for any $(x,y) \in R$ we say that $x$ is $R$-related to $y$ and we write $x R y$. Moreover, we define the \emph{domain} of $R$ by
    \begin{align*}
        \mathrm{domain}(R) = \{x \in X \mid \exists y \in Y: (x,y) \in R\},
    \end{align*}
    and the \emph{image}, or range, of $R$ by
    \begin{align*}
        \mathrm{image}(R) = \{y \in Y \mid \exists x \in X: (x,y) \in R\}.
    \end{align*}
\end{defn}

