\begin{defn}[Equivalence Relation]\label{defn:equivalence-relation}
    Let $X$ be a set, and let $\sim \subseteq X \times X$ be a relation that satisfies
    \begin{enumerate}[(i)]
        \item (reflexivity) $x \sim x$ for all $x \in X$,
        \item (symmetry) for all $x,x^\prime\in X$, $x \sim x^\prime$ if and only if $x^\prime \sim x$, and
        \item (transitivity) for all $x,x^\prime,x^\ast\in X$, $x \sim x^\prime$ and $x^\prime \sim x^\ast$ implies $x \sim x^\ast$.
    \end{enumerate}
    Then, $\sim$ is called an equivalence relation.
\end{defn}

\begin{defn}[Equivalence Class and Quotient Set]\label{defn:equivalence-class}
    Let $X$ be a set and let $\sim\subseteq X\times X$ be an equivalence relation. For each $x \in X$ define
    \begin{align*}
        [x]_{\sim} =\{x^\prime \in X \mid x^\prime \sim x\}.
    \end{align*}
The set $[x]_{\sim}$ is called an equivalence class\index{equivalence class} of $X$ with respect to $\sim$; we write $[x]$ when $\sim$ is clear from context. Moreover, we denote the quotient set of $X$ by $\sim$, the set of all equivalence classes, by
    \begin{align*}
        X_\sim = \{[x] \mid x \in X\}.
    \end{align*}
\end{defn}

