\begin{defn}[{Function \citep[Chapter~I, §6]{kunen2014set}}]\label{defn:function}
    Let $X$ and $Y$ be sets and let $f \subseteq X\times Y$ be a relation. Then $f$ is said to be a function if for every $x \in X$ there is exactly one $y\in Y$ such that $(x,y) \in f$, and we write $f(x)$ for the unique $y$. In addition, we say that $f$ maps $X$ to $Y$, we also call $f$ a map, and we write $f:X\to Y$.
\end{defn}

\begin{defn}[Graph]\label{defn:graph}
    Let $X$ and $Y$ be sets and let $f:X \to Y$ be a function. Then, the set
    \begin{align*}
        \Gamma(f) = \{(x,f(x)) \mid x \in X\}
    \end{align*}
    is called the graph of $f$.
\end{defn}

