\begin{defn}[{Injective, Surjective, and Bijective Maps \citep[Chapter~I, §6]{kunen2014set}}]\label{defn:bijection}\index{bijection}\index{injective map}\index{surjective map}
    Let $X$ and $Y$ be sets and let $f:X\to Y$ be a function. Then $f$ is said to be
    \begin{enumerate}[(i)]
        \item injective if $f(x)=f(x^\prime)$ implies $x=x^\prime$ for all $x,x^\prime\in X$,
        \item surjective if $\mathrm{image}(f)=Y$, and
        \item bijective, or a bijection, if $f$ is injective and surjective.
    \end{enumerate}
    We write $X\cong Y$ if there is a bijection from $X$ onto $Y$.
\end{defn}

\begin{rem}[Bijections and transported structure]\label{rem:bijection-not-homeomorphism}
    A bijection gives only set-theoretic equivalence. To preserve a topology, metric, order, measure, or algebraic operation, we prove the relevant preservation property or explicitly transport the structure along the bijection. Likewise, we cannot infer that a family is pairwise disjoint merely from the existence of some bijection between its ordinary union and the tagged disjoint union (Definition~\ref{defn:disjoint-union}). Pairwise disjointness does, however, make the tag-forgetting map $(x,\alpha)\mapsto x$ bijective; we use this canonical map in Chapter~\ref{chap:tuple-market-states}.
\end{rem}

\begin{defn}[Cartesian Product of a Family]\label{defn:arbitrary-product-space}
     Let $(X_\alpha)_{\alpha \in A}$ be a family of sets indexed by a set $A$. Define
    \begin{align*}
        \prod_{\alpha \in A} X_\alpha = \left\{x:A \to \bigcup_{\alpha \in A}X_\alpha ~\middle\lvert~\forall \alpha \in A:x(\alpha) \in X_\alpha \right\}.
    \end{align*}
    We call $\prod_{\alpha \in A} X_\alpha$ the Cartesian product of $(X_\alpha)_{\alpha \in A}$.
\end{defn}

