\begin{prop}[Binary Cartesian Products]\label{prop:binary-product-space}
    Let $X_1$ and $X_2$ be sets. Then the map $(x_1,x_2)\mapsto\{(1,x_1),(2,x_2)\}$ is a bijection from the Cartesian product of Definition~\ref{defn:product-space} onto the Cartesian product of the family $(X_i)_{i\in\{1,2\}}$ of Definition~\ref{defn:arbitrary-product-space}; that is,
    \begin{align*}
        X_1 \times X_2 \cong \prod_{i=1}^2 X_i.
    \end{align*}
\end{prop}

