    Let $S\subseteq\mathbb{N}_0$ be a set such that $0\in S$ and $n+1\in S$ for every $n\in S$. Then $S=\mathbb{N}_0$.
\end{prop}

\begin{thm}[{Recursion Theorem \citep[Chapter~I, §9]{kunen2014set}}]\label{thm:recursion}\index{recursion}
    Let $X$ be a set and let $G:\bigcup_{n\in\mathbb{N}_0}X^n\to X$ be a function. Then there is a unique function $f:\mathbb{N}\to X$ such that
    \begin{align*}
        f(n)=G\bigl(f\restriction_{\{1,\dots,n-1\}}\bigr)\quad\text{for all }n\in\mathbb{N},
    \end{align*}
    where $\{1,\dots,0\}=\emptyset$.
\end{thm}

