\begin{defn}[{Cardinality; \citealp[Chapter~I, Definitions~10.1 and~10.8]{kunen2014set}}]\label{defn:cardinality}\index{cardinality}
    Let $X$ and $Y$ be sets. We write $|X|\leq|Y|$ if there is an injective function from $X$ to $Y$, and we write $|X|=|Y|$ and call $X$ and $Y$ equinumerous if $X\cong Y$. The set $X$ is called
    \begin{enumerate}[(i)]
        \item finite if $|X|=|\{1,\dots,n\}|$ for some $n\in\mathbb{N}_0$, in which case we write $|X|=n$ and $|X|<\infty$, and infinite otherwise, and
        \item countable if $|X|\leq|\mathbb{N}|$, countably infinite if $|X|=|\mathbb{N}|$, and uncountable if it is not countable.
    \end{enumerate}
    Finally, $X$ has the cardinality of the continuum if $|X|=|\mathbb{R}|$.
\end{defn}

\begin{thm}[{Cantor--Schr\"oder--Bernstein \citep[Chapter~I, Theorem~10.2]{kunen2014set}}]\label{thm:cantor-schroeder-bernstein}\index{Cantor-Schroeder-Bernstein theorem@Cantor--\allowbreak Schr\"oder--\allowbreak Bernstein theorem}
    Let $X$ and $Y$ be sets such that $|X|\leq|Y|$ and $|Y|\leq|X|$. Then $|X|=|Y|$.
\end{thm}

\begin{defn}[$X$-sequence]\label{defn:sequence}
 Let $X$ be a set. Then any map $x:\mathbb{N} \to X$ is called an $X$-sequence, and we write
    \begin{align*}
        x_n := x(n),
    \end{align*}
    for all $n \in \mathbb{N}$. Moreover, we usually denote the sequence by $(x_n)_{n\in\mathbb{N}}$ rather than by $x$. Finally, we write $X^{\mathbb{N}}$ for the set of all $X$-sequences.
\end{defn}

