\begin{defn}[{Monoid \citep[Chapter~I, §1]{lang2012algebra}}] \label{defn:monoid}\index{monoid}
    Let $X$ be a set, and let $+:X\times X \to X$ be a binary operation that satisfies
    \begin{enumerate}[(i)]
        \item $(x + x^\prime) + x^\ast = x + (x^\prime + x^\ast)$ for all $x, x^\prime, x^\ast \in X$.
        \item There exists an element $e \in X$ such that $x + e = e + x = x$ for all $x \in X$; such an $e$ is called the identity element.
    \end{enumerate}
    Then $(X, +)$ is said to be a monoid.
\end{defn}

