\begin{prop}\label{prop:grothendieck-relation}
    Let $(X,+)$ be a cancellative abelian monoid, and define the relation $\sim$ on $X\times X$ by
    \begin{align*}
        (x,y) \sim (x^\prime, y^\prime) \iff x+y^\prime = x^\prime + y.
    \end{align*}
    Then $\sim$ is an equivalence relation, and $(x,y)\sim(x^\prime,y^\prime)$ and $(u,v)\sim(u^\prime,v^\prime)$ imply $(x+u,y+v)\sim(x^\prime+u^\prime,y^\prime+v^\prime)$.
\end{prop}

