\begin{prop}[Universal Property of the Grothendieck Group]\label{prop:grothendieck-universal}
    Let $(X,+)$ be a cancellative abelian monoid with identity element $e$, and let $G(X)$ and $\iota$ be as in Definition~\ref{defn:grothendieck-group}. Then
    \begin{enumerate}[(i)]
        \item $(G(X),+)$ is an abelian group with identity element $[(e,e)]$, and $-[(x,y)]=[(y,x)]$ for all $x,y\in X$;
        \item $\iota$ is an injective monoid homomorphism, and $[(x,y)]=\iota(x)-\iota(y)$ for all $x,y\in X$;
        \item for every abelian group $(H,+)$ and every monoid homomorphism $\psi:X\to H$, there is a unique monoid homomorphism $\bar{\psi}:G(X)\to H$ such that $\bar{\psi}\circ\iota=\psi$, namely $\bar{\psi}([(x,y)])=\psi(x)-\psi(y)$.
    \end{enumerate}
\end{prop}

