\begin{defn}[Topology, \cite{munkres2000topology}]
    Let $X$ be a set. A topology on $X$ is a set $\mathcal{T} \subseteq \wp(X)$ satisfying the following conditions:
    \begin{enumerate}[(i)]
        \item $\emptyset \in \mathcal{T}$ and $X \in \mathcal{T}$; \label{itm:top-1}
        \item $\bigcap_{u \in U} u \in \mathcal{T}$ for all non-empty finite sets $U \subseteq \mathcal{T}$; \label{itm:top-2}
        \item $\bigcup_{o \in O} o \in \mathcal{T}$ for all sets $O \subseteq \mathcal{T}$. \label{itm:top-3}
    \end{enumerate}
    The elements of $\mathcal{T}$ are called open sets, and the pair $(X,\mathcal{T})$ is called a topological space.
\end{defn}

