\begin{defn}[Topological base, \cite{munkres2000topology}]\index{topological base}
    Let $X$ be a set. A family $\mathcal{B}$ of subsets of $X$ is called a topological base if
    \begin{enumerate}[(i)]
        \item for every $x \in X$ there exists $B \in \mathcal{B}$ such that $x \in B$;
        \item for every $B, B^\prime \in \mathcal{B}$ and $x \in B \cap B^\prime$ there exists $B^\ast \in \mathcal{B}$ such that $x \in B^\ast \subseteq B \cap B^\prime$.
    \end{enumerate}
\end{defn}

