\begin{prop}[Topology generated by a base, \cite{munkres2000topology}] \label{prop:topology-base}
    Let $X$ be a set and let $\mathcal{B}$ be a topological base on $X$. Define
    \begin{align*}
        \mathcal{T}_{\mathcal{B}} = \left\{\bigcup_{B \in \mathcal{U}} B \,\middle|\, \mathcal{U} \subseteq \mathcal{B}\right\}.
    \end{align*}
    Then $(X,\mathcal{T}_{\mathcal{B}})$ is a topological space, and $\mathcal{T}_{\mathcal{B}}$ is called the topology generated by $\mathcal{B}$.
\end{prop}

