\begin{defn}[Second countability, \cite{munkres2000topology}] \label{defn:second-countable}\index{second countability}
    Let $(X,\mathcal{T})$ be a topological space. If there exists a countable topological base $\mathcal{B} = \{B_n\}_{n \in \mathbb{N}} \subseteq \mathcal{T}$ for $X$ with $\mathcal{T}=\mathcal{T}_{\mathcal{B}}$ (Proposition~\ref{prop:topology-base}), then $(X,\mathcal{T})$ is called second-countable.
\end{defn}

\begin{defn}[Subspace topology, \cite{munkres2000topology}]
    Let $(X,\mathcal{T})$ be a topological space and let $Y \subseteq X$. The subspace topology on $Y$ is
    \begin{align*}
        \mathcal{T}|_Y = \{Y \cap O \mid O \in \mathcal{T}\}.
    \end{align*}
\end{defn}

