\begin{defn}[Open cover and subcover, \cite{munkres2000topology}]
    Let $(X,\mathcal{T})$ be a topological space. A family $\mathcal{U} \subseteq \mathcal{T}$ is called an open cover of $X$ if
    \begin{align*}
        X = \bigcup_{O \in \mathcal{U}} O.
    \end{align*}
    If $\mathcal{V} \subseteq \mathcal{U}$ is also an open cover of $X$, then $\mathcal{V}$ is called a subcover.
\end{defn}

