environments.rawEnvironment:
\begin{defn}[Compact set, \cite{munkres2000topology}]
    Let $(X,\mathcal{T})$ be a topological space. The space $X$ is called compact if every open cover of $X$ has a finite subcover. A subset $K \subseteq X$ is called compact if it is compact with respect to the subspace topology.
\end{defn}

\begin{defn}[Metric, \cite{burago2001course}] \label{defn:metric}
    Let $X$ be a set, and let $d:X \times X \to [0,\infty]$ be a function such that for every $x,x^\prime,x^\ast \in X$:
    \begin{enumerate}[(i)]
        \item $d(x,x^\prime) = 0$ if and only if $x = x^\prime$; \label{eq:metric-1}
        \item $d(x,x^\prime) = d(x^\prime,x)$; \label{eq:metric-2}
        \item $d(x,x^\prime) \leq d(x,x^\ast) + d(x^\ast,x^\prime)$. \label{eq:metric-3}
    \end{enumerate}
    Then $d$ is called a metric, and $(X,d)$ is called a metric space.
\end{defn}

