\begin{defn}[Pseudometric] \label{defn:pseudometric}\index{pseudometric}
    Let $X$ be a set, and let $d:X \times X \to [0,\infty]$ be a function such that for every $x,x^\prime,x^\ast \in X$:
    \begin{enumerate}[(i)]
        \item $d(x,x) = 0$; \label{eq:pseudometric-1}
        \item $d(x,x^\prime) = d(x^\prime,x)$; \label{eq:pseudometric-2}
        \item $d(x,x^\prime) \leq d(x,x^\ast) + d(x^\ast,x^\prime)$. \label{eq:pseudometric-3}
    \end{enumerate}
    Then $d$ is called a pseudometric, and $(X,d)$ is called a pseudometric space.
\end{defn}

