\begin{cor} \label{cor:pseudometric-metric-relation}
    Let $X$ be a set and let $d,\rho:X \times X \to [0,\infty]$ be a metric and a pseudometric on $X$, respectively. Then:
    \begin{enumerate}[(i)]
        \item $(X,d)$ is a pseudometric space;
        \item $(X,\rho)$ is a metric space if and only if $\rho(x,x^\prime) = 0$ implies $x = x^\prime$ for all $x,x^\prime \in X$.
    \end{enumerate}
\end{cor}

