\begin{prop} \label{prop:topology-extended-pseudometric}
    Let $(X,d)$ be a pseudometric space. For each $x \in X$ and $\varepsilon > 0$, define the open ball
    \begin{align*}
        B_\varepsilon(x) = \{x^\prime \in X \mid d(x,x^\prime) < \varepsilon\}.
    \end{align*}
    Then the family
    \begin{align*}
        \mathcal{B}_d = \{B_\varepsilon(x) \mid x \in X,\ \varepsilon > 0\}
    \end{align*}
    is a topological base. We call $\mathcal{T}_{\mathcal{B}_d}$ the topology induced by $d$.
\end{prop}

