\begin{defn}[Distance from a point to a set] \label{defn:distance-to-set}\index{distance!point to set}
    Let $(X,d)$ be a pseudometric space, let $x\in X$, and let $B \subseteq X$. We define
    \begin{align*}
        d(x,B) = \inf_{x^\prime \in B} d(x,x^\prime),
    \end{align*}
    with the convention that $d(x,\emptyset) = \infty$.
\end{defn}

