\begin{prop}[Hausdorff distance is a pseudometric, \cite{burago2001course}] \label{prop:hausdorff-distance}
    Let $(X,d)$ be a metric space. Then $(\wp(X), d_H)$ is a pseudometric space.
\end{prop}

proof.rawEnvironment:
\begin{proof}
    First, suppose that $d(x,x^\ast)=0$ implies $x=x^\ast$. Let $x \neq x^\ast$. Then $d(x,x^\ast)>0$. Set $\varepsilon = \frac{1}{2}\min\{d(x,x^\ast),1\}$, which is a finite positive real number. We claim that
    \begin{align*}
        B_\varepsilon(x) \cap B_\varepsilon(x^\ast) = \emptyset.
    \end{align*}
    Indeed, if $y$ belonged to the intersection, then the triangle inequality would give
    \begin{align*}
        d(x,x^\ast) \leq d(x,y) + d(y,x^\ast) < 2\varepsilon = \min\{d(x,x^\ast),1\} \leq d(x,x^\ast),
    \end{align*}
    which is impossible. Hence the induced topology is Hausdorff.

    Conversely, suppose there exist distinct points $x,x^\ast \in X$ with $d(x,x^\ast)=0$. Let $O$ be any open neighbourhood of $x$. Since $O$ is open, the centred-ball characterisation following Proposition~\ref{prop:topology-extended-pseudometric} shows that there exists $\varepsilon > 0$ such that $B_\varepsilon(x) \subseteq O$. But $d(x,x^\ast)=0$ implies $x^\ast \in B_\varepsilon(x)$, hence $x^\ast \in O$. By symmetry, every open neighbourhood of $x^\ast$ also contains $x$. Therefore no two open neighbourhoods of $x$ and $x^\ast$ can be disjoint, so the topology is not Hausdorff.
\end{proof}

