\begin{prop}[Zero-Distance Quotient of a Pseudometric Space]\label{prop:pseudometric-quotient}
    Let $(X,d)$ be a pseudometric space, and define the relation $\sim$ on $X$ by $x \sim x^\ast$ if and only if $d(x,x^\ast)=0$. Then $\sim$ is an equivalence relation on $X$, and the map $d_\sim\colon X_\sim\times X_\sim\to[0,\infty]$ given by
    \begin{align*}
        d_\sim([x],[x^\ast]) = d(x,x^\ast)
    \end{align*}
    is well-defined and defines a metric on the quotient set $X_\sim=X/{\sim}$.
\end{prop}

environments.statement:
\label{prop:pseudometric-quotient}
    Let $(X,d)$ be a pseudometric space, and define the relation $\sim$ on $X$ by $x \sim x^\ast$ if and only if $d(x,x^\ast)=0$. Then $\sim$ is an equivalence relation on $X$, and the map $d_\sim\colon X_\sim\times X_\sim\to[0,\infty]$ given by
    \begin{align*}
        d_\sim([x],[x^\ast]) = d(x,x^\ast)
    \end{align*}
    is well-defined and defines a metric on the quotient set $X_\sim=X/{\sim}$.

environments.rawEnvironment:
\begin{defn}[Cauchy sequence, \cite{munkres2000topology}] \label{defn:Cauchy-sequence}
    Let $(X,d)$ be a metric space, and let $(x_n)_{n \in \mathbb{N}}$ be a sequence in $X$. The sequence is called Cauchy if for every $\varepsilon > 0$ there exists $N \in \mathbb{N}$ such that
    \begin{align*}
        m,n \geq N \implies d(x_m,x_n) < \varepsilon.
    \end{align*}
\end{defn}

environments.statement:
\label{defn:Cauchy-sequence}
    Let $(X,d)$ be a metric space, and let $(x_n)_{n \in \mathbb{N}}$ be a sequence in $X$. The sequence is called Cauchy if for every $\varepsilon > 0$ there exists $N \in \mathbb{N}$ such that
