\begin{defn}[Complete metric space] \label{defn:complete-space}\index{complete metric space}
    Let $(X,d)$ be a metric space. Then $(X,d)$ is called complete if every Cauchy sequence in $X$ converges to a limit in $X$.
\end{defn}

\begin{defn}[Separable metric space]\label{defn:separable}\index{separable metric space}
    Let $(X,d)$ be a metric space. Then $(X,d)$ is called separable if there exists a countable subset $D \subseteq X$ such that for every $x \in X$ and every $\varepsilon > 0$ there exists $y \in D$ with
    \begin{align*}
        d(x,y) < \varepsilon.
    \end{align*}
\end{defn}

environments.statement:
\label{defn:separable}\index{separable metric space}
