\begin{rem}[Pointwise spaces versus $L^p$ spaces]\label{rem:pointwise-versus-lp}
    We treat the elements of $C([a,b];X)$ and $D^\pm([a,b];X)$ below as pointwise functions, so their values $f(t)$ and graphs $\Gamma(f)$ are well-defined. By contrast, $L^p$ (Appendix~\ref{app:measure-theory}) consists of equivalence classes modulo almost-everywhere equality; a generic $L^p$ element has no representative-independent value at a fixed point and no canonical graph. Passing from a path space to $L^p$ therefore retains only the equivalence class of a path; operations that depend on point values, such as evaluation or the graph, are lost.
\end{rem}

\begin{defn}[Continuity]
    Let $(X,d)$ and $(Y,\rho)$ be metric spaces. A function $f:X \to Y$ is called continuous if for every $x_0 \in X$ and every $\varepsilon > 0$ there exists $\delta > 0$ such that, for every $x\in X$,
    \begin{align*}
        d(x,x_0) < \delta \implies \rho(f(x),f(x_0)) < \varepsilon.
    \end{align*}
\end{defn}

