\begin{defn}[Spaces of càdlàg and càglàd functions]\index{cadlag functions@c\`adl\`ag functions}\index{caglad functions@c\`agl\`ad functions}
    Let $a,b \in \mathbb{R}$ with $a < b$, let $(X,d)$ be a metric space, and let $f:[a,b] \to X$ be a function. We say that:
    \begin{enumerate}[(i)]
        \item $f$ is right-continuous if for every $t_0 \in [a,b)$ and every $\varepsilon > 0$ there exists $\delta > 0$ such that
        \begin{align*}
            t \in (t_0,\min\{t_0+\delta,b\}) \implies d(f(t),f(t_0)) < \varepsilon;
        \end{align*}
        \item $f$ is left-continuous if for every $t_0 \in (a,b]$ and every $\varepsilon > 0$ there exists $\delta > 0$ such that
        \begin{align*}
            t \in (\max\{a,t_0-\delta\},t_0) \implies d(f(t),f(t_0)) < \varepsilon;
        \end{align*}
        \item $f$ has right limits if for every $t_0 \in [a,b)$ there exists $R \in X$ such that for every $\varepsilon > 0$ there exists $\delta > 0$ with
        \begin{align*}
            t \in (t_0,\min\{t_0+\delta,b\}) \implies d(f(t),R) < \varepsilon;
        \end{align*}
        \item $f$ has left limits if for every $t_0 \in (a,b]$ there exists $L \in X$ such that for every $\varepsilon > 0$ there exists $\delta > 0$ with
        \begin{align*}
            t \in (\max\{a,t_0-\delta\},t_0) \implies d(f(t),L) < \varepsilon.
        \end{align*}
    \end{enumerate}
    We call $f$ càdlàg if it is right-continuous with left limits, and we write $f \in D^+([a,b];X)$. We call $f$ càglàd if it is left-continuous with right limits, and we write $f \in D^-([a,b];X)$.
\end{defn}

