\begin{lem}[Regular paths are bounded and Borel]\label{lem:regular-paths-bounded-borel}
    Let $a,b\in\mathbb{R}$ with $a<b$, let $(X,d)$ be a metric space, and let $f\in C([a,b];X)\cup D^+([a,b];X)\cup D^-([a,b];X)$. Then $f([a,b])$ is a bounded subset of $X$, and $f$ is Borel measurable.
\end{lem}

\begin{defn}[Time changes and their distortion]\index{increasing interval bijections}
    Let $a,b \in \mathbb{R}$ with $a < b$. Define
    \begin{align*}
        \Lambda([a,b]) = \{\lambda:[a,b] \to [a,b] \mid \lambda \text{ is strictly increasing and bijective}\},
    \end{align*}
    and define $\lVert\cdot\rVert_\circ:\Lambda([a,b]) \to [0,\infty]$ by
    \begin{align*}
        \lVert\lambda\rVert_\circ
        = \sup_{\substack{s,t \in [a,b]\\ s < t}}
        \left|\log\left(\frac{\lambda(t)-\lambda(s)}{t-s}\right)\right|.
    \end{align*}
\end{defn}

