\begin{prop}[{Characterisation of convergence in the Skorokhod metric, \cite[Section~12]{billingsley2013convergence}}]
    Let $a,b \in \mathbb{R}$ with $a < b$, let $(X,d)$ be a metric space, and let $D([a,b];X)$ denote either $D^+([a,b];X)$ or $D^-([a,b];X)$. A sequence $(f_n)_{n \in \mathbb{N}} \subseteq D([a,b];X)$ converges to $f \in D([a,b];X)$ in $(D([a,b];X),d_\circ)$ if and only if there exists a sequence $(\lambda_n)_{n \in \mathbb{N}} \subseteq \Lambda([a,b])$ such that
    \begin{align*}
        \lim_{n \to \infty} \sup_{t \in [a,b]} |\lambda_n(t)-t| = 0
    \end{align*}
    and
    \begin{align*}
        \lim_{n \to \infty} \sup_{t \in [a,b]} d(f_n(\lambda_n(t)),f(t)) = 0.
    \end{align*}
\end{prop}

