\begin{defn}[Inner product]\label{defn:inner-product}\index{inner product}
    Let $(V,+,\cdot)$ be a real vector space, and let $\langle \cdot,\cdot \rangle:V \times V \to \mathbb{R}$ be a function such that
    \begin{enumerate}[(i)]
        \item $\langle u,v \rangle = \langle v,u \rangle$ for all $u,v \in V$;
        \item $\langle a \cdot u + b \cdot v,w \rangle = a\langle u,w \rangle + b\langle v,w \rangle$ for all $u,v,w \in V$ and $a,b \in \mathbb{R}$;
        \item $\langle v,v \rangle \geq 0$ for all $v \in V$;
        \item $\langle v,v \rangle = 0$ if and only if $v$ is the zero vector of $V$.
    \end{enumerate}
    Then $\langle \cdot,\cdot \rangle$ is called an inner product, and $(V,\langle \cdot,\cdot \rangle)$ is called an inner product space.
\end{defn}

environments.statement:
\label{defn:inner-product}\index{inner product}
