\begin{prop}[Metric induced by norm]\label{prop:metric-induced-by-norm}
    Let $(V,\lVert\cdot\rVert)$ be a normed space, and define $d:V \times V \to [0,\infty)$ by
    \begin{align*}
        d(u,v) = \lVert u-v\rVert.
    \end{align*}
    Then $(V,d)$ is a metric space. We call $d$ the metric induced by the norm $\lVert\cdot\rVert$.
\end{prop}

