\begin{defn}[Banach, Hilbert, and separable spaces]\label{defn:banach-hilbert-separable}
    Let $(V,+,\cdot)$ be a real vector space. Then:
    \begin{enumerate}[(i)]
        \item a normed space\index{normed spaces} $(V,\lVert\cdot\rVert)$ is called a Banach space if the metric induced by $\lVert\cdot\rVert$ is complete;
        \item an inner product space $(V,\langle \cdot,\cdot \rangle)$ is called a Hilbert space if the metric induced by $\langle \cdot,\cdot \rangle$ is complete;
        \item a normed or inner product space is called separable if the induced metric space is separable.
    \end{enumerate}
\end{defn}

environments.statement:
\label{defn:banach-hilbert-separable}
    Let $(V,+,\cdot)$ be a real vector space. Then:
