\begin{prop}[Finite products]\label{prop:finite-products}
    Let $I$ be a finite index set and let $(V_i,\langle\cdot,\cdot\rangle_i)_{i\in I}$ be real Hilbert spaces, where for $I=\emptyset$ the product $\prod_{i\in I}V_i=\{\emptyset\}$ is the zero space. Then $\prod_{i\in I}V_i$ is a Hilbert space under
    \begin{align*}
        \langle u,v\rangle=\sum_{i\in I}\langle u_i,v_i\rangle_i,
    \end{align*}
    and it is separable if every factor is separable.
\end{prop}

