\begin{defn}[Bounded linear operator]\label{defn:bounded-linear-operator}\index{bounded linear operator}
    Let $(V,\lVert\cdot\rVert_V)$ and $(W,\lVert\cdot\rVert_W)$ be normed spaces, and let $T:V \to W$ be linear. We say that $T$ is a bounded linear operator if there exists a constant $C \in [0,\infty)$ such that
    \begin{align*}
        \lVert Tv\rVert_W \leq C \lVert v\rVert_V
    \end{align*}
    for all $v \in V$.
    We denote the vector space of bounded linear operators from $V$ to $W$ by $\mathcal{L}(V,W)$.
\end{defn}

