\begin{defn}[Operator norm]\label{defn:operator-norm}\index{operator norm}
    Let $(V,\lVert\cdot\rVert_V)$ and $(W,\lVert\cdot\rVert_W)$ be normed spaces, and let $T:V \to W$ be a bounded linear operator. We define the operator norm of $T$ by
    \begin{align*}
        \lVert T\rVert_{\mathrm{op}} = \sup_{\substack{v \in V\\ \lVert v\rVert_V \leq 1}} \lVert Tv\rVert_W.
    \end{align*}
    If $V \neq \{0\}$, then equivalently
    \begin{align*}
        \lVert T\rVert_{\mathrm{op}} = \sup_{\substack{v \in V\\ \lVert v\rVert_V = 1}} \lVert Tv\rVert_W.
    \end{align*}
\end{defn}

