\begin{prop}\label{prop:bounded-iff-continuous}
    Let $(V,\lVert\cdot\rVert_V)$ and $(W,\lVert\cdot\rVert_W)$ be normed spaces, and let $T:V \to W$ be linear. Then $T$ is bounded if and only if $T$ is continuous.
\end{prop}

\begin{defn}[Dual space]\label{defn:dual-space}\index{dual space}
    Let $(V,\lVert\cdot\rVert)$ be a normed space. The dual space of $V$ is the vector space
    \begin{align*}
        V^\ast = \mathcal{L}(V,\mathbb{R})
    \end{align*}
    of bounded linear functionals from $V$ into $\mathbb{R}$.
\end{defn}

