\begin{thm}[Riesz representation theorem]\label{thm:riesz-representation}\index{Riesz representation theorem}
    Let $(\mathcal{H},\langle \cdot, \cdot \rangle)$ be a real Hilbert space. Then for every $\varphi \in \mathcal{H}^\ast$ there exists a unique element $h_\varphi \in \mathcal{H}$ such that
    \begin{align*}
        \varphi(u) = \langle u, h_\varphi \rangle,
    \end{align*}
    for all $u \in \mathcal{H}$. Moreover,
    \begin{align*}
        \lVert\varphi\rVert_{\mathrm{op}} = \lVert h_\varphi\rVert.
    \end{align*}
\end{thm}

