\begin{defn}[Adjoint, self-adjoint, finite-rank, and compact operators]\label{defn:adjoint-compact-operators}\index{adjoint operator}\index{self-adjoint operator}\index{finite-rank operator}\index{compact operator}
    Let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real Hilbert space, write $\mathcal{L}(\mathcal{H})=\mathcal{L}(\mathcal{H},\mathcal{H})$, and let $T\in\mathcal{L}(\mathcal{H})$.
    \begin{enumerate}[(i)]
        \item The adjoint of $T$ is the operator $T^\ast\in\mathcal{L}(\mathcal{H})$ such that $\langle Tu,v\rangle=\langle u,T^\ast v\rangle$ for all $u,v\in\mathcal{H}$, and $T$ is called self-adjoint if $T^\ast=T$.
        \item The operator $T$ has finite rank if its image $T(\mathcal{H})$ is finite-dimensional.
        \item The operator $T$ is called compact if the closure of $\{Tv\mid v\in\mathcal{H},\ \lVert v\rVert\leq1\}$ is compact. We write $\mathcal{K}(\mathcal{H})$ for the set of compact operators in $\mathcal{L}(\mathcal{H})$.
    \end{enumerate}
\end{defn}

\begin{defn}[Fréchet Derivative]\label{defn:frechet-derivative}
    Let $\mathcal{H}$ and $\mathcal{G}$ be real Hilbert spaces. Let $f: \mathcal{H} \to \mathcal{G}$ be a function. The function $f$ is said to be \emph{Fréchet} differentiable at $x \in \mathcal{H}$ if there exists a bounded linear operator $A \in \mathcal{L}(\mathcal{H}, \mathcal{G})$ such that
    \begin{align*}
        \lim_{\lVert h\rVert\to 0} \frac{\lVert f(x + h) - f(x) - A h\rVert_{\mathcal{G}}}{\lVert h\rVert_{\mathcal{H}}}   = 0.
    \end{align*}
    Moreover, we call $A$ the Fréchet derivative of $f$ at $x$ and we write $D f(x)=A$. If $f$ is differentiable at every $x \in \mathcal{H}$, we write
    \begin{align*}
        Df &: \mathcal{H} \to \mathcal{L}(\mathcal{H}, \mathcal{G})\\
        x &\mapsto D f(x).
    \end{align*}
\end{defn}

environments.statement:
