\begin{lem}[Gradient of the squared loss]\label{lem:squared-loss-gradient}
    Let $\mathcal{H}$ be a real Hilbert space, let $y\in\mathcal{H}$, and let $\mathfrak{f}:\mathcal{H}\to\mathbb{R}$ be given by $\mathfrak{f}(\hat{y})=\lVert y-\hat{y}\rVert^2$. Then $\mathfrak{f}$ is Fréchet differentiable at every $\hat{y}\in\mathcal{H}$, with $D\mathfrak{f}(\hat{y})h=2\langle\hat{y}-y,h\rangle$ and $\nabla\mathfrak{f}(\hat{y})=2(\hat{y}-y)$.
\end{lem}

\begin{defn}[Measurable space and $\sigma$-algebra] \label{defn:measurable-space}\index{measurable space}\index{sigma-algebra@$\sigma$-algebra}
    Let $\Omega$ be a set and let $\mathcal{F} \subseteq \wp(\Omega)$ satisfy
    \begin{enumerate}[(i)]
        \item $\Omega \in \mathcal{F}$;
        \item $E \in \mathcal{F}$ implies $E^{\mathtt{C}} \in \mathcal{F}$;
        \item if $(E_n)_{n \in \mathbb{N}} \subseteq \mathcal{F}$, then $\bigcup_{n \in \mathbb{N}} E_n \in \mathcal{F}$.
    \end{enumerate}
    Then $\mathcal{F}$ is called a $\sigma$-algebra and $(\Omega,\mathcal{F})$ is called a measurable space.
\end{defn}

