\begin{defn}[Atom, purely atomic, and diffuse measure] \label{defn:atom-diffuse}\index{diffuse measure}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space. A set $A \in \mathcal{F}$ is called an atom of $\mu$ if $\mu(A)>0$ and for every $E \in \mathcal{F}$,
    \begin{align*}
        \min\{\mu(A \cap E),\mu(A \setminus E)\}=0.
    \end{align*}
    The measure $\mu$ is called purely atomic if every $E \in \mathcal{F}$ with $\mu(E)>0$ contains an atom. It is called diffuse if it has no atoms.
\end{defn}

