\begin{thm}[Atomic decomposition; \citealp{johnson1970atomic}] \label{thm:atomic}
    Let $(\Omega,\mathcal{F},\mu)$ be a $\sigma$-finite measure space. Then there exist unique measures $\alpha$ and $\beta$ on $(\Omega,\mathcal{F})$ such that
    \begin{align*}
        \mu = \alpha + \beta,
    \end{align*}
    where $\alpha$ is diffuse and $\beta$ is purely atomic. If moreover $\Omega$ is a Polish space and $\mathcal{F} = \mathcal{B}(\Omega)$, then there is an index set $I\subseteq\mathbb{N}$, possibly empty, such that
    \begin{align*}
        \beta = \sum_{n\in I} a_n\delta_{x_n},
    \end{align*}
    with $a_n=\beta(\{x_n\})>0$ and pairwise distinct points $x_n$, where every singleton $\{x_n\}$ is a point atom of $\beta$. When $I=\emptyset$, the sum denotes the zero measure.
\end{thm}

