\begin{defn}[Measurable function] \label{defn:measurable-function}\index{measurable function}
    Let $(\Omega,\mathcal{F})$ and $(S,\mathcal{S})$ be measurable spaces. A function $f:\Omega \to S$ is called $\mathcal{F}/\mathcal{S}$-measurable if
    \begin{align*}
        f^{-1}(B) \in \mathcal{F}
    \end{align*}
    for all $B \in \mathcal{S}$. If $(\Omega,\mathcal{F},\mathbb{P})$ is a probability space, then such a measurable map is called a random element, and a random variable when it is real-valued.
\end{defn}

