\begin{prop}[Measurable restrictions] \label{prop:measurable-restrictions}
    Let $(\Omega,\mathcal{F})$ and $(S,\mathcal{S})$ be measurable spaces, let $f:\Omega \to S$ be a function, and let $(E_n)_{n \in \mathbb{N}} \subseteq \mathcal{F}$ satisfy $\bigcup_{n \in \mathbb{N}} E_n = \Omega$. Then $f$ is $\mathcal{F}/\mathcal{S}$-measurable if and only if each restriction
    \begin{align*}
        f\restriction_{E_n}: E_n \to S
    \end{align*}
    is $\mathcal{F}\restriction_{E_n}/\mathcal{S}$-measurable.
\end{prop}

