\begin{defn}[Simple measurable function] \label{defn:simple-function}\index{simple measurable function}
    Let $(\Omega,\mathcal{F})$ and $(V,\mathcal{V})$ be measurable spaces, with $V$ also a vector space. A measurable function $s:\Omega \to V$ is called simple if
    \begin{align*}
        s(\omega) = \sum_{i=1}^n \mathbbm{1}_{E_i}(\omega) v_i
    \end{align*}
    for some $n \in \mathbb{N}$, some measurable sets $E_1,\dots,E_n \in \mathcal{F}$, and some vectors $v_1,\dots,v_n \in V$.
\end{defn}

