\begin{defn}[Bochner integral] \label{defn:bochner-integral}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space and let $(V,\lVert\cdot\rVert)$ be a separable Banach space endowed with its Borel $\sigma$-algebra $\mathcal{B}(V)$. A simple $\mathcal{F}/\mathcal{B}(V)$-measurable function represented on a finite measurable partition $(E_i)_{i=1}^n$ by
    \begin{align*}
        s(\omega)=\sum_{i=1}^n \mathbbm{1}_{E_i}(\omega) v_i
    \end{align*}
    is called Bochner integrable if
    \begin{align*}
        \int_\Omega \lVert s(\omega)\rVert \,\mathrm{d}\mu(\omega)
        =
        \sum_{i=1}^n \lVert v_i\rVert \mu(E_i)
        < \infty.
    \end{align*}
    In that case, we define
    \begin{align*}
        \int_\Omega s(\omega) \,\mathrm{d}\mu(\omega)
        =
        \sum_{i=1}^n v_i \mu(E_i).
    \end{align*}
In the scalar norm sum we use $0\cdot\infty:=0$. In the vector sum we omit every term with $v_i=0$; the integrability condition ensures that $\mu(E_i)<\infty$ whenever $v_i\neq0$.
    Any finite simple-function representation may be refined to such a measurable partition, and the resulting value is independent of the chosen partition representation.

    A measurable function $f:\Omega \to V$ is called Bochner integrable if there exists a sequence of Bochner-integrable simple functions $(s_n)_{n \in \mathbb{N}}$ such that
    \begin{align*}
        \int_\Omega \lVert f(\omega)-s_n(\omega)\rVert \,\mathrm{d}\mu(\omega) \to 0.
    \end{align*}
    We then define
    \begin{align*}
        \int_\Omega f(\omega) \,\mathrm{d}\mu(\omega)
        =
        \lim_{n \to \infty} \int_\Omega s_n(\omega) \,\mathrm{d}\mu(\omega),
    \end{align*}
    where the limit is taken in $V$.
\end{defn}

