\begin{defn}[Expected value] \label{defn:expected-value}\index{expected value}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $(V,\lVert\cdot\rVert)$ be a separable Banach space, and let $X:\Omega \to V$ be Bochner integrable. Then the expected value of $X$ is defined by
    \begin{align*}
        \mathbb{E}[X] = \int_\Omega X(\omega) \,\mathrm{d}\mathbb{P}(\omega).
    \end{align*}
\end{defn}

