\begin{defn}[$\mathcal{L}^p$ and $L^p$ spaces] \label{defn:lp-spaces}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space and let $(V,\lVert\cdot\rVert)$ be a separable Banach space. For a measurable function $f:\Omega \to V$ and $1 \leq p < \infty$, define
    \begin{align*}
        \lVert f\rVert_{\mathcal{L}^p}
        =
        \left(
            \int_\Omega \lVert f(\omega)\rVert^p \,\mathrm{d}\mu(\omega)
        \right)^{1/p}.
    \end{align*}
    For $p=\infty$, define
    \begin{align*}
        \lVert f\rVert_{\mathcal{L}^\infty}
        =
        \operatorname*{ess\,sup}_{\omega \in \Omega} \lVert f(\omega)\rVert
        :=\inf\{c\in[0,\infty]\mid \lVert f\rVert\leq c\ \mu\text{-a.e.}\}.
    \end{align*}
    Define an equivalence relation on measurable $V$-valued functions by
    \begin{align*}
        f \sim g
        \quad \iff \quad
        f = g \ \mu\text{-a.e.},
    \end{align*}
    and, writing $\mathcal{L}^p(\Omega,\mu;V)=\{f:\Omega \to V \mid f\text{ is measurable and }\lVert f\rVert_{\mathcal{L}^p}<\infty\}$, define
    \begin{align*}
        L^p(\Omega,\mu;V)
        =
        \mathcal{L}^p(\Omega,\mu;V)\big/\sim
    \end{align*}
    for $1 \leq p \leq \infty$. When the $\sigma$-algebra must be displayed, for instance for a sub-$\sigma$-algebra $\mathcal{G}\subseteq\mathcal{F}$ with $\mu$ restricted to $\mathcal{G}$, we write $L^p(\Omega,\mathcal{G},\mu;V)$. Writing $[f]$ for the almost-everywhere equivalence class of $f$, we set
    \begin{align*}
        [f]+[g]:=[f+g],
        \qquad
        c[f]:=[cf],
        \qquad
        \lVert[f]\rVert_{L^p}:=\lVert f\rVert_{\mathcal{L}^p}.
    \end{align*}
\end{defn}

