\begin{prop} \label{prop:cadlag-caglad-l2}
    Let $(V,\lVert\cdot\rVert)$ be a separable real Banach space, let $a,b \in \mathbb{R}$ with $a<b$, and let $\lambda$ denote Lebesgue measure on $[a,b]$, with the c\`adl\`ag and c\`agl\`ad spaces $D^\pm([a,b];V)$ as defined in Appendix~\ref{chap:analysis}. Then:
    \begin{enumerate}[(i)]
        \item if $f \in C([a,b];V)$, then $[f] \in L^2([a,b],\lambda;V)$;
        \item if $f \in D^+([a,b];V)$, then $[f] \in L^2([a,b],\lambda;V)$;
        \item if $f \in D^-([a,b];V)$, then $[f] \in L^2([a,b],\lambda;V)$.
    \end{enumerate}
\end{prop}

