\begin{defn}[{Product measure; \citealp[251E, 251K]{fremlin2016broad}}] \label{defn:product-measure}
    Let $(S,\mathcal{S},\mu)$ and $(T,\mathcal{T},\nu)$ be $\sigma$-finite measure spaces. The product $\sigma$-algebra is $\mathcal{S}\otimes\mathcal{T}:=\sigma(\{A\times B\mid A\in\mathcal{S},\,B\in\mathcal{T}\})$, and the product measure $\mu\otimes\nu$ is the unique measure on $(S\times T,\mathcal{S}\otimes\mathcal{T})$ such that
    \begin{align*}
        (\mu \otimes \nu)(A \times B)=\mu(A)\nu(B)
    \end{align*}
    for all $A \in \mathcal{S}$ and $B \in \mathcal{T}$, with $0\cdot\infty:=0$.
\end{defn}

