\begin{thm}[{Regular conditional distributions; \citealp[Chapter~6]{kallenberg2002foundations}}] \label{thm:regular-conditional-distribution}\index{regular conditional distribution}
    Let $(S,\mathcal{S})$ be a standard Borel space, let $(T,\mathcal{T})$ be a measurable space, and let $X:\Omega \to S$ and $Y:\Omega \to T$ be random elements. Then there exists a Markov kernel $Q$ from $T$ to $S$, called a regular conditional distribution of $X$ given $Y$, such that
    \begin{align*}
        \mathbb{P}(X \in A, Y \in B)
        =
        \int_B Q(y,A)\,\mathrm{d}(\mathbb{P}\circ Y^{-1})(y)
    \end{align*}
    for all $A \in \mathcal{S}$ and $B \in \mathcal{T}$, and $Q$ is unique $(\mathbb{P}\circ Y^{-1})$-almost everywhere. Moreover, writing $Q_y:=Q(y,\cdot)$, every bounded measurable $g:S \to \mathbb{R}$ satisfies
    \begin{align*}
        \mathbb{E}[g(X)\mid Y]
        =
        \int_S g\,\mathrm{d}Q_Y
        \qquad \text{a.s.}
    \end{align*}
\end{thm}

