\begin{thm}[Prokhorov metric; \citealp{prokhorov1956convergence,hirata2024formalization}] \label{thm:prokhorov-metric}\index{Prokhorov metric}
    Let $(X,d)$ be a complete and separable extended metric space and let $\bar{d}=\min\{d,1\}$. Define $\rho:\mathcal{M}(X)\times\mathcal{M}(X)\to[0,\infty)$ by
    \begin{align*}
        \rho(\mu,\eta)
        =
        \inf\big\{
            \varepsilon > 0
            \,\big|\,
            \mu(B) \leq \eta(B^\varepsilon)+\varepsilon
            \text{ and }
            \eta(B) \leq \mu(B^\varepsilon)+\varepsilon
            \text{ for all } B \in \mathcal{B}(X)
        \big\},
    \end{align*}
    where
    \begin{align*}
        B^\varepsilon = \{x \in X \mid \exists b \in B: \bar{d}(x,b)<\varepsilon\}.
    \end{align*}
    Then $\rho$ is a metric on $\mathcal{M}(X)$, the space $(\mathcal{M}(X),\rho)$ is complete and separable, and $\rho$ metrises weak convergence on $\mathcal{M}(X)$.
\end{thm}

