\begin{defn}[Random measure; \citealp{kallenberg2017random}] \label{defn:kallenberg-random-measure}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space and let $(X,d)$ be a complete and separable metric space with Borel $\sigma$-algebra $\mathcal{B}(X)$. A map
    \begin{align*}
        \xi:\Omega \times \mathcal{B}(X) \to [0,\infty]
    \end{align*}
    is called a random measure if
    \begin{enumerate}[(i)]
        \item for each $B \in \mathcal{B}(X)$, the partial map $\omega \mapsto \xi(\omega,B)$ is measurable;
        \item for each $\omega \in \Omega$, the partial map $B \mapsto \xi(\omega,B)$ is a finite measure on $(X,\mathcal{B}(X))$.
    \end{enumerate}
    If in addition $B \mapsto \xi(\omega,B)$ is integer-valued for every $\omega$, then $\xi$ is called an integer-valued random measure, or (finite) point process, as in Chapter~\ref{chap:stochastic-markets}. Its values $\xi(\omega,\cdot)$ lie in $\mathcal{N}(X)$.
\end{defn}

