\begin{prop}[Mean measure; \citealp{kallenberg2017random}] \label{prop:mean-measure}\index{mean measure}
    Let $\xi$ be a finite random measure on $X$ and assume that
    \begin{align*}
        \mathbb{E}[\xi(X)]<\infty.
    \end{align*}
    Then
    \begin{align*}
        (\mathbb{E}\xi)(B)=\mathbb{E}[\xi(B)],
        \qquad B \in \mathcal{B}(X),
    \end{align*}
    defines a finite measure $\mathbb{E}\xi \in \mathcal{M}(X)$.
\end{prop}

