\begin{defn}[{Monotone $[0,1]$-Valued $L^2$ Constraint Set and Distribution Selection Map}]\label{defn:cdf-constraint-selection}
    Fix $a<b$ and let $\mathfrak{D}_{[a,b]}$ denote the set of distribution functions on $\mathbb{R}$ supported on $[a,b]$. We define the constraint set $\mathcal{C}\subseteq L^2([a,b])$ by
    \begin{align*}
        \mathcal{C}
        =
        \left\{
        [f]\in L^2([a,b])
        \ \middle|\
        \begin{aligned}
            &0\leq f\leq1\ \text{a.e. and}\\[-0.2em]
            &[f]\text{ admits a non-decreasing representative}
        \end{aligned}
        \right\}.
    \end{align*}
    For each $[f]\in\mathcal{C}$, let $f^{\mathrm{rc}}$ denote its unique non-decreasing right-continuous representative on $[a,b)$, and define the selection map $\mathsf{S}:\mathcal{C}\to\mathfrak{D}_{[a,b]}$, used only in this appendix, by
    \begin{align*}
        \mathsf{S}([f])(x)
        =
        \begin{cases}
            0, & x<a,\\
            f^{\mathrm{rc}}(x), & a\leq x<b,\\
            1, & x\geq b.
        \end{cases}
    \end{align*}
\end{defn}

