    Let $\mathcal{C}\subseteq L^2([a,b])$ and $\mathsf{S}:\mathcal{C}\to\mathfrak{D}_{[a,b]}$ be as in Definition~\ref{defn:cdf-constraint-selection}. Then:
    \begin{enumerate}[(i)]
        \item the set $\mathcal{C}$ is non-empty, closed, and convex in $L^2([a,b])$, and its metric projection $P_{\mathcal{C}}:L^2([a,b])\to\mathcal{C}$ exists, is unique, and is $1$-Lipschitz;
        \item the conditional expectation satisfies $\mathbb{E}[\chi_t\mid\mathcal{F}_s]=[G_s(\cdot,\cdot)|_{[a,b]}]\in\mathcal{C}$ almost surely;
        \item the map $\mathsf{S}$ is the inverse of the restriction map $F\mapsto[F|_{[a,b]}]$ from $\mathfrak{D}_{[a,b]}$ onto $\mathcal{C}$ and is an isometry from $(\mathcal{C},\lVert\cdot\rVert_{L^2([a,b])})$ onto $\mathfrak{D}_{[a,b]}$ equipped with the Cram\'er distance $(\int_{\mathbb{R}}(F-G)^2\,\mathrm{d}x)^{1/2}$.
    \end{enumerate}
